import { Book } from "@/lib/types";

export const _2chronicles: Book = {
  id: "2chronicles",
  name: "2. Chronik",
  shortName: "2.Chr",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und Salomo, der Sohn Davids, erstarkte in seiner Königsherrschaft*. Und der HERR, sein Gott, war mit ihm* und machte ihn überaus groß*.", heading: "Salomos Opfer und Gebet um Weisheit — Sein Reichtum", footnotes: ["℘ 1Kö 2,12.46; 1Chr 29,23.24", "℘ 1Mo 39,2; 1Chr 22,11", "℘ Kap. 32,23; Jos 3,7; 1Chr 29,25"] },
      { number: 2, text: "*Und Salomo sprach zu ganz Israel, zu den Obersten über Tausend und über Hundert und zu den Richtern und zu allen Fürsten von ganz Israel, den Familienoberhäuptern*.", footnotes: ["℘ V. 2-13: 1Kö 3,4-15", "w. den Häuptern der Väter\n℘ 1Chr 27,1"] },
      { number: 3, text: "Und sie, Salomo und die ganze Versammlung mit ihm, gingen zu der Höhe, die bei Gibeon* war. Denn dort war das Begegnungszelt Gottes, das Mose, der Knecht des HERRN*, in der Wüste gemacht hatte. —", footnotes: ["℘ Jos 9,3", "℘ 5Mo 34,5"] },
      { number: 4, text: "Die Lade Gottes jedoch hatte David von Kirjat-Jearim heraufgebracht an die Stelle, die David für sie hergerichtet hatte*; denn er hatte ihr in Jerusalem ein Zelt aufgeschlagen*. —", footnotes: ["℘ 1Chr 15,3", "℘ 1Chr 15,1"] },
      { number: 5, text: "Und der bronzene Altar, den Bezalel, der Sohn Uris, des Sohnes Hurs, gemacht hatte*, war dort vor der Wohnung des HERRN. Und Salomo und die Versammlung suchten ihn dort auf.", footnotes: ["℘ 2Mo 31,2; 38,1-7"] },
      { number: 6, text: "Und Salomo opferte dort vor dem HERRN auf dem bronzenen Altar*, der bei dem Zelt der Begegnung war; und er opferte auf ihm tausend Brandopfer.", footnotes: ["℘ Kap. 8,12"] },
      { number: 7, text: "In jener Nacht erschien Gott dem Salomo und sprach zu ihm: Bitte, was ich dir geben soll!" },
      { number: 8, text: "Und Salomo sagte zu Gott: Du selbst hast ja an meinem Vater David große Gnade erwiesen*; und du hast mich zum König gemacht an seiner Stelle*.", footnotes: ["℘ 1Chr 17,16", "℘ 1Chr 29,23"] },
      { number: 9, text: "Und nun, HERR, Gott, möge sich dein Wort an meinen Vater David als zuverlässig erweisen*! Denn du hast mich zum König gemacht über ein Volk, das zahlreich ist wie der Staub der Erde*.", footnotes: ["℘ 1Chr 17,23; 28,5", "℘ 1Mo 13,16"] },
      { number: 10, text: "Gib mir nun Weisheit und Erkenntnis*, damit ich vor diesem Volk aus- und eingehen kann*! Denn wer kann dieses, dein großes Volk richten?* —", footnotes: ["℘ Spr 4,7", "℘ 4Mo 27,17", "℘ Jak 1,5"] },
      { number: 11, text: "Da sprach Gott zu Salomo: Weil dir dies am Herzen lag und du nicht gebeten hast um Reichtum, Güter und Ehre* oder um das Leben* derer, die dich hassen, und weil du auch nicht um viele Tage gebeten, sondern um Weisheit und Erkenntnis für dich gebeten hast, damit du mein Volk richten kannst*, über das ich dich zum König gemacht habe,", footnotes: ["o. Ansehen; o. Herrlichkeit", "o. um die Seele", "℘ Spr 8,15"] },
      { number: 12, text: "so sind dir Weisheit und Erkenntnis gegeben*. Und Reichtum und Güter und auch Ehre* will ich dir geben, wie sie die Könige, die vor dir gewesen sind, nicht gehabt haben und wie sie nach dir keiner haben wird*.", footnotes: ["℘ 1Kö 10,24", "o. Ansehen; o. Herrlichkeit", "℘ Kap. 9,22"] },
      { number: 13, text: "Und Salomo kam von der Höhe, die bei Gibeon war, von der Stelle vor dem Zelt der Begegnung, nach Jerusalem. Und er regierte über Israel*.", footnotes: ["℘ 1Kö 4,1"] },
      { number: 14, text: "*Und Salomo brachte Streitwagen und Pferde zusammen*, und er hatte 1 400 Streitwagen und 12 000 Pferde. Und er legte sie in die Wagenstädte und zu dem König nach Jerusalem*.", footnotes: ["℘ V. 14-17: 1Kö 10,26-29", "℘ 1Kö 5,6", "℘ Kap. 8,6; 9,25"] },
      { number: 15, text: "Und der König machte das Silber und das Gold in Jerusalem an Menge den Steinen gleich, und die Zedern machte er an Menge den Maulbeerfeigenbäumen gleich, die in der Niederung* sind*.", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 9,27"] },
      { number: 16, text: "Und die Ausfuhr der Pferde für Salomo erfolgte aus Ägypten *und aus Koe. Die Aufkäufer des Königs holten sie aus Koe* gegen Bezahlung.", footnotes: ["T. in Anlehnung an Vulg.; Mas. T.: und eine Ansammlung der Aufkäufer des Königs holte eine Ansammlung von Pferden", "T. in Anlehnung an Vulg.; Mas. T.: und eine Ansammlung der Aufkäufer des Königs holte eine Ansammlung von Pferden"] },
      { number: 17, text: "Bei der Ausfuhr aus Ägypten handelte man einen Wagen für* 600 Schekel Silber und ein Pferd für 150. Und so führte man sie für alle Könige der Hetiter und für die Könige von Aram durch die Aufkäufer* wieder aus*.", footnotes: ["w. Und man brachte herauf und führte aus Ägypten einen Wagen aus für", "w. durch ihre Hand", "℘ Kap. 9,28"] },
      { number: 18, text: "Und Salomo gedachte, ein Haus für den Namen des HERRN zu bauen sowie ein Haus für seine Königsherrschaft*.", footnotes: ["℘ 1Kö 7,1"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Und Salomo zählte 70 000 Lastträger ab und 80 000 Steinhauer im Gebirge und 3 600 Aufseher über sie.", heading: "Salomos Vertrag mit Hiram — Vorbereitungen zum Tempelbau", footnotes: ["℘ 1Kö 5,15-32"] },
      { number: 2, text: "Und Salomo sandte zu Hiram, dem König von Tyrus, und ließ ihm sagen: Wie du es bei meinem Vater David getan und ihm Zedern gesandt hast, damit er sich ein Haus baute, um darin zu wohnen*, so tu es auch bei mir!", footnotes: ["℘ 1Chr 14,1"] },
      { number: 3, text: "Siehe, ich will dem Namen des HERRN, meines Gottes, ein Haus bauen, um es ihm zu weihen, um wohlriechendes Räucherwerk als Rauchopfer vor ihm darzubringen* und um das ständige Schaubrot* aufzulegen* und morgens und abends Brandopfer zu opfern* an den Sabbaten und an den Neumonden und an den Festen des HERRN, unseres Gottes*. Das ist für ewig Israel auferlegt*.", footnotes: ["℘ Kap. 13,11; 2Mo 30,7", "w. die ständige Schicht", "℘ Kap. 4,19; 13,11; 2Mo 25,30", "℘ 2Mo 29,38.39; Esr 6,3", "℘ Kap. 8,13; 3Mo 23,2; 4Mo 28,9.11", "℘ Kap. 24,14; Neh 10,34"] },
      { number: 4, text: "Und das Haus, das ich bauen will, soll groß sein*; denn unser Gott ist größer als alle Götter*.", footnotes: ["℘ 1Chr 22,5", "℘ Ps 86,8; 96,4"] },
      { number: 5, text: "Aber wer kann ihm ein Haus bauen?* Denn der Himmel und die Himmel der Himmel* können ihn nicht fassen*. Und wer bin ich*, dass ich ihm ein Haus bauen sollte, es sei denn, um Rauchopfer vor ihm darzubringen?*", footnotes: ["℘ Jes 66,1", "℘ Ps 148,4", "℘ Kap. 6,18; 1Kö 8,27", "℘ 1Chr 29,14", "℘ Kap. 29,11; Lk 1,9.10"] },
      { number: 6, text: "Und nun sende mir einen Mann, der darin erfahren ist, in Gold und in Silber und in Bronze und in Eisen und in rotem Purpur und Karmesin und violettem Purpur zu arbeiten, und der Gravierungen* zu machen versteht*, zusammen mit den Künstlern, die bei mir in Juda und in Jerusalem sind, die mein Vater David bestellt hat*!", footnotes: ["o. Schnitzarbeit", "℘ 1Kö 7,13.14", "℘ 1Chr 22,15"] },
      { number: 7, text: "Und sende mir Zedern-, Wacholder- und Almuggimholz* vom Libanon*! Denn ich weiß, dass deine Knechte das Holz des Libanon zu schlagen verstehen. Und siehe, meine Knechte sollen mit deinen Knechten zusammenarbeiten*.", footnotes: ["℘ 1Kö 10,11", "℘ Hes 27,5", "w. mit deinen Knechten sein"] },
      { number: 8, text: "Und man soll mir Holz zubereiten in Menge. Denn das Haus, das ich bauen will, soll groß und wunderbar sein*.", footnotes: ["℘ 1Chr 22,5"] },
      { number: 9, text: "Und siehe, ich werde deinen Knechten, den Holzfällern, die das Holz schlagen, Weizen zur Verpflegung* geben, 20 000 Kor, und 20 000 Kor Gerste und 20 000 Bat Wein und 20 000 Bat Öl.", footnotes: ["so mit Vulg., der syr. und der aram. Üs.; Mas. T.: Weizen von ausgeschlagenen Ähren"] },
      { number: 10, text: "Und Hiram, der König von Tyrus, antwortete in einem Schreiben und sandte es an Salomo: Weil der HERR sein Volk liebt, hat er dich zum König über sie gemacht*.", footnotes: ["℘ Kap. 9,8; 1Chr 14,2"] },
      { number: 11, text: "Und Hiram sprach: Gepriesen sei der HERR, der Gott Israels, der Himmel und Erde gemacht hat*, dass er dem König David einen weisen Sohn gegeben hat, voller Verstand und Einsicht, der dem HERRN ein Haus bauen will und ein Haus für seine Königsherrschaft!", footnotes: ["℘ 1Mo 1,1"] },
      { number: 12, text: "So sende ich nun einen kunstfertigen, einsichtsvollen Mann, Hiram-Abi*,", footnotes: ["d. h. Hiram ist mein Vater; einige LXX-Handschr. üs.: Hiram, meinen Sohn"] },
      { number: 13, text: "den Sohn einer Frau von den Töchtern Dan. Und sein Vater war ein Tyrer. Er versteht, in Gold und Silber zu arbeiten, in Bronze, in Eisen, in Steinen und in Holz, in rotem Purpur, in violettem Purpur und in Byssus und in Karmesin und jegliche Gravierung* zu machen und jeden Entwurf zu ersinnen, der ihm aufgegeben wird, zusammen mit deinen Künstlern und den Künstlern meines Herrn David, deines Vaters.", footnotes: ["o. allerlei Schnitzarbeit"] },
      { number: 14, text: "Und nun, den Weizen und die Gerste, das Öl und den Wein, von denen mein Herr gesprochen hat, möge er seinen Knechten senden." },
      { number: 15, text: "Wir aber, wir werden Holz vom Libanon* schlagen nach all deinem Bedarf und werden es dir in Flößen auf dem Meer nach Jafo* bringen*. Du kannst es dann nach Jerusalem hinaufschaffen.", footnotes: ["℘ Jes 60,13", "℘ Jon 1,3", "℘ Jos 19,46; Esr 3,7"] },
      { number: 16, text: "Und Salomo zählte alle Fremden, die im Land Israel waren*, nach der Zählung, die schon sein Vater David unter ihnen vorgenommen hatte*; und es fanden sich 153 600.", footnotes: ["℘ Kap. 8,7.8; 30,25", "℘ Jos 9,27; 1Chr 22,2"] },
      { number: 17, text: "Und er machte von ihnen 70 000 zu Lastträgern und 80 000 zu Steinhauern im Gebirge und 3 600 zu Aufsehern, um das Volk zur Arbeit anzuhalten." },
    ]},
    { number: 3, verses: [
      { number: 1, text: "*Und Salomo fing an, das Haus des HERRN zu bauen in Jerusalem, auf dem Berg Morija*, wo der HERR* seinem Vater David erschienen war, an der Stelle, die David bestimmt hatte, auf der Tenne Ornans, des Jebusiters*.", heading: "Salomos Tempelbau", footnotes: ["℘ V. 1-14: 1Kö 6", "℘ 1Mo 22,2", "w. er", "℘ 2Sam 24,16.18; 1Chr 21,18; 22,1"] },
      { number: 2, text: "Und er fing an zu bauen im zweiten Monat, am zweiten Tag im vierten Jahr seiner Regierung*.", footnotes: ["w. Königsherrschaft"] },
      { number: 3, text: "Und dies waren die Grundmaße, die Salomo für den Bau des Hauses Gottes* festlegte*: die Länge, nach dem früheren Ellenmaß, war sechzig Ellen und die Breite zwanzig Ellen. —", footnotes: ["℘ 1Chr 28,11.12", "so mit der aram. Üs.; Mas. T.: Und diese waren die Grundmauern Salomos für den Bau des Hauses Gottes"] },
      { number: 4, text: "Und die Vorhalle*, die der Länge nach vor der Breite des Hauses war, war zwanzig Ellen und die Höhe 120*. Und er überzog sie innen mit reinem Gold.", footnotes: ["℘ Kap. 29,17", "einige griech. und syr. Handschr.: 20 Ellen"] },
      { number: 5, text: "Und den großen Raum* verkleidete er mit Wacholderholz, und er verkleidete es mit gutem Gold. Und er brachte Palmen und Kettenwerk darauf an.", footnotes: ["w. das große Haus; d. i. das Heilige"] },
      { number: 6, text: "Und er belegte das Haus mit Edelsteinen zum Schmuck*. Das Gold aber war Gold aus Parwajim.", footnotes: ["℘ 1Chr 29,2-5.8"] },
      { number: 7, text: "Und er verkleidete das Haus, die Balken, die Schwellen und seine Wände und seine Türflügel mit Gold, und an den Wänden hatte er Cherubim eingeschnitzt." },
      { number: 8, text: "Und er machte das Haus des Allerheiligsten. Seine Länge vor der Breite des Hauses her war zwanzig Ellen und seine Breite zwanzig Ellen. Und er verkleidete es mit gutem Gold im Gewicht von sechshundert Talenten." },
      { number: 9, text: "Und das Gewicht der Nägel war etwa fünfzig Schekel Gold. Auch die Obergemächer* verkleidete er mit Gold.", footnotes: ["℘ 1Chr 28,11"] },
      { number: 10, text: "Und er machte im Haus des Allerheiligsten zwei Cherubim, eine Bildhauerarbeit*. Und man überzog sie mit Gold*.", footnotes: ["o. eine Gussarbeit", "℘ 2Mo 25,18"] },
      { number: 11, text: "Und die Flügel der Cherubim — ihre Länge war zwanzig Ellen —: Der Flügel des einen, von fünf Ellen, berührte die eine Wand des Hauses; und der andere Flügel, von fünf Ellen, berührte den Flügel des andern Cherubs*;", footnotes: ["℘ Hes 1,9"] },
      { number: 12, text: "und der Flügel des andern Cherubs, von fünf Ellen, berührte die andere Wand des Hauses; und der andere Flügel, von fünf Ellen, stieß an den Flügel des einen Cherubs." },
      { number: 13, text: "Die Flügel dieser Cherubim waren — ausgebreitet — zwanzig Ellen. Und sie selbst standen auf ihren Füßen, und ihre Gesichter waren dem Raum* zugewandt.", footnotes: ["w. dem Haus"] },
      { number: 14, text: "Und er machte den Vorhang aus violettem und rotem Purpur und Karmesin und Byssus und brachte Cherubim darauf an*.", footnotes: ["℘ 2Mo 26,31; Mt 27,51"] },
      { number: 15, text: "*Und er machte vor dem Haus zwei Säulen*. 35 Ellen war die Länge; und das Kapitell, das oben auf ihr war, maß fünf Ellen.", footnotes: ["℘ V. 15-17: 1Kö 7,15-20", "℘ 1Chr 18,8"] },
      { number: 16, text: "Und er machte Ketten im Hinterraum* und brachte sie oben auf die Säulen. Und er machte hundert Granatäpfel und befestigte sie an den Ketten*.", footnotes: ["d. i. das Allerheiligste; andere üs. mit Textänderung: Ketten nach Art einer Halskette", "℘ Kap. 4,12.13"] },
      { number: 17, text: "Und er stellte die Säulen vor dem Tempel auf, eine zur Rechten und eine zur Linken; und er gab der Rechten den Namen Jachin* und der Linken den Namen Boas*.", footnotes: ["d. h. er wird feststellen", "d. h. in der Stärke"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und er machte einen bronzenen Altar*. Zwanzig Ellen war seine Länge und zwanzig Ellen seine Breite und zehn Ellen seine Höhe.", heading: "Tempelausstattung", footnotes: ["℘ Kap. 7,7; 8,12; 15,8; 2Mo 27,1.2; 1Kö 8,64; 2Kö 16,14; Hes 43,13"] },
      { number: 2, text: "*Und er machte das Meer*, gegossen, zehn Ellen von seinem einen Rand bis zu seinem anderen Rand, ringsum rund, und fünf Ellen seine Höhe. Und eine Messschnur von dreißig Ellen umspannte es ringsherum.", footnotes: ["℘ V. 2-6: 1Kö 7,23-39", "℘ 2Mo 38,8"] },
      { number: 3, text: "Und unter ihm waren Gestalten von Rindern*, die es ringsherum umgaben, je zehn auf die Elle, das Meer ringsum einschließend. In zwei Reihen waren die Rinder bei seinem Guss mitgegossen worden.", footnotes: ["o. Gebilde wie Rinder"] },
      { number: 4, text: "Es stand auf zwölf Rindern. Drei waren nach Norden gewandt, drei waren nach Westen gewandt, drei waren nach Süden gewandt, drei waren nach Osten gewandt. Und das Meer war oben auf ihnen, und ihre Hinterteile waren alle nach innen gekehrt." },
      { number: 5, text: "Seine Dicke war eine Handbreit und sein Rand wie der Rand eines Bechers, gearbeitet als Lilienblüte. An Inhalt fasste es dreitausend Bat." },
      { number: 6, text: "Und er machte zehn Kessel. Und er stellte fünf zur Rechten und fünf zur Linken auf, damit man darin wusch; was zum Brandopfer gehört, spülte man darin ab*. Und das Meer war für die Priester, damit sie sich darin wuschen*.", footnotes: ["℘ 3Mo 1,9.13", "℘ 2Mo 30,18-21"] },
      { number: 7, text: "*Und er machte die zehn goldenen Leuchter gemäß ihrer Vorschrift*, und er stellte sie im Tempel auf, fünf zur Rechten und fünf zur Linken.", footnotes: ["℘ Kap. 4,7-5,1: 1Kö 7,40-51; 1Chr 28,14-19", "℘ 2Mo 25,31-40"] },
      { number: 8, text: "Und er machte zehn Tische und stellte sie in den Tempel, fünf zur Rechten und fünf zur Linken. Und er machte hundert goldene Sprengschalen*.", footnotes: ["℘ Jer 52,19"] },
      { number: 9, text: "Und er machte den Vorhof für die Priester* und den großen Hof* und die Flügeltüren zu dem Hof; und ihre Flügel* überzog er mit Bronze.", footnotes: ["℘ 1Kö 6,36", "℘ 2Mo 27,9; 1Kö 7,12; 2Kö 21,5; Hes 42,15", "w. Flügeltüren"] },
      { number: 10, text: "Und das Meer stellte er an der rechten Seite ostwärts, in Richtung Süden auf*.", footnotes: ["℘ 1Kö 7,39"] },
      { number: 11, text: "Und Hiram machte die Töpfe und die Schaufeln und die Sprengschalen. — Und so vollendete Hiram die Arbeit an dem Werk, das er für den König Salomo im Haus Gottes ausführte:" },
      { number: 12, text: "zwei Säulen und die kugelförmigen Kapitelle* oben auf den beiden Säulen; und die beiden Geflechte, um die beiden kugelförmigen Kapitelle*, die oben auf den Säulen waren, zu bedecken;", footnotes: ["w. die kugelförmigen Schalen und die Kapitelle", "w. die beiden kugelförmigen Schalen der Kapitelle"] },
      { number: 13, text: "und die vierhundert Granatäpfel für die beiden Geflechte: zwei Reihen Granatäpfel für das einzelne Geflecht, um die beiden kugelförmigen Kapitelle*, die auf der Oberseite der Säulen waren*, zu bedecken.", footnotes: ["w. die beiden kugelförmigen Schalen der Kapitelle", "℘ Kap. 3,16; 1Kö 7,21.22"] },
      { number: 14, text: "Und er machte die Gestelle und machte die Kessel auf den Gestellen," },
      { number: 15, text: "das eine Meer und die zwölf Rinder darunter" },
      { number: 16, text: "und die Töpfe und die Schaufeln und die Fleischgabeln. Alle dazugehörigen* Geräte machte Hiram-Abiw dem König Salomo für das Haus des HERRN aus polierter Bronze*.", footnotes: ["w. Alle ihre", "℘ 2Mo 38,3; 1Chr 18,8"] },
      { number: 17, text: "In der Jordanebene* ließ der König sie gießen in der Erdgießerei zwischen Sukkot und Zereda.", footnotes: ["w. Im Umkreis des Jordan"] },
      { number: 18, text: "Und Salomo machte alle diese Geräte in sehr großer Menge; denn das Gewicht der Bronze war nicht feststellbar." },
      { number: 19, text: "Und Salomo machte all die Geräte, die das Haus Gottes brauchte*, und zwar den goldenen Altar und die Tische, auf denen die Schaubrote liegen,", footnotes: ["℘ Kap. 2,3"] },
      { number: 20, text: "und die Leuchter und ihre Lampen aus gediegenem Gold*, dass sie gemäß der Vorschrift vor dem Hinterraum* angezündet würden,", footnotes: ["℘ Kap. 13,11", "d. i. das Allerheiligste"] },
      { number: 21, text: "und die Blüten und die Lampen und die Dochtscheren aus Gold — das alles war reinstes Gold —" },
      { number: 22, text: "und die Messer und die Sprengschalen und die Schalen und die Feuerbecken aus gediegenem Gold; und den Eingang des Hauses, seine inneren Türflügel, die zum Allerheiligsten führten, und die Türflügel des Hauses zum Tempelraum aus Gold*.", footnotes: ["℘ 1Kö 6,31-35"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "So wurde das ganze Werk vollendet, das Salomo für das Haus des HERRN machte*. Und Salomo brachte die heiligen Gaben* seines Vaters David hinein, nämlich das Silber und das Gold und alle Geräte. Er legte sie in die Schatzkammern des Hauses Gottes*.", footnotes: ["℘ Apg 7,47", "o. heiligen Dinge", "℘ 1Chr 26,27"] },
      { number: 2, text: "*Damals versammelte Salomo die Ältesten von Israel und alle Oberhäupter der Stämme, die Fürsten der Geschlechter* der Söhne Israel, nach Jerusalem, um die Lade des Bundes des HERRN heraufzuholen aus der Stadt Davids, das ist Zion*.", heading: "Tempelweihe", footnotes: ["℘ V. 2-14: 1Kö 8,1-11", "w. die Fürsten der Väter", "℘ 1Chr 15,3"] },
      { number: 3, text: "Und alle Männer von Israel versammelten sich zum König an dem Fest* im Monat Etanim, das ist der siebte Monat*.", footnotes: ["℘ Kap. 7,8", "Sonst Tischri genannt, ein Teil von September und Oktober. Das Laubhüttenfest fand am 15. dieses Monats statt."] },
      { number: 4, text: "Alle Ältesten von Israel kamen. Und die Leviten trugen die Lade." },
      { number: 5, text: "Und sie brachten die Lade hinauf, dazu das Zelt der Begegnung und alle heiligen Geräte, die im Zelt waren. Die Priester und die Leviten brachten sie hinauf." },
      { number: 6, text: "Und der König Salomo und die ganze Gemeinde Israel, die sich bei ihm eingefunden hatte und vor der Lade stand, opferten Schafe und Rinder, die vor Menge nicht berechnet und nicht gezählt werden konnten." },
      { number: 7, text: "Und die Priester brachten die Lade des Bundes des HERRN an ihren Platz*, in den Hinterraum des Hauses, in das Allerheiligste, unter die Flügel der Cherubim.", footnotes: ["℘ Kap. 35,3"] },
      { number: 8, text: "Denn die Cherubim breiteten die Flügel aus über den Platz der Lade, und die Cherubim bedeckten die Lade und ihre Stangen von oben her." },
      { number: 9, text: "Und die Stangen waren so lang, dass die Enden der Stangen vom Heiligen aus* vor dem Hinterraum zu sehen waren. Aber nach außen waren sie nicht sichtbar. Und sie sind* dort bis zum heutigen Tag.", footnotes: ["so mit mehreren hebr. Handschr., LXX und 1Kö 8,8; Mas. T.: von der Lade her", "so mit vielen hebr. Handschr., LXX, der aram. u. der syr. Üs. und 1Kö 8,8; Mas. T.: Und sie die Lade ist"] },
      { number: 10, text: "Nichts war in der Lade als nur die beiden Tafeln, die Mose am Horeb hineingetan hatte, als der HERR einen Bund schloss mit den Söhnen Israel, als sie aus Ägypten zogen." },
      { number: 11, text: "Und es geschah, als die Priester aus dem Heiligen hinausgingen — denn alle Priester, die sich eingefunden hatten, hatten sich geheiligt*, ohne sich an die Abteilungen zu halten —", footnotes: ["℘ Kap. 29,15; 35,6; 1Chr 15,14"] },
      { number: 12, text: "und als die Leviten, die Sänger waren, sie alle, nämlich Asaf, Heman, Jedutun, ihre Söhne und ihre Brüder, in Byssus gekleidet*, mit Zimbeln und mit Harfen und Zithern* an der Ostseite des Altars standen und bei ihnen etwa 120 Priester, die auf Trompeten trompeteten* —,", footnotes: ["℘ Esr 3,10", "℘ 1Chr 25,1", "℘ Kap. 7,6; 1Chr 15,24"] },
      { number: 13, text: "und es geschah, als die Trompeter und die Sänger wie ein Mann waren, um eine Stimme hören zu lassen*, den HERRN zu loben und zu preisen, und als sie die Stimme erhoben mit Trompeten und Zimbeln und Musikinstrumenten beim Lob des HERRN*: Denn er ist gütig, denn seine Gnade währt ewig*! — da wurde das Haus, das Haus des HERRN, mit einer Wolke erfüllt*.", footnotes: ["℘ Röm 15,6", "℘ Kap. 20,22; 1Chr 16,4; Neh 12,27; Ps 22,4; 81,2.3", "℘ Kap. 7,6; 20,21; 1Chr 16,34.41; Ps 100,5", "℘ Kap. 7,1; 2Mo 29,43"] },
      { number: 14, text: "Und die Priester konnten wegen der Wolke nicht hinzutreten*, um den Dienst zu verrichten. Denn die Herrlichkeit des HERRN erfüllte das Haus Gottes*.", footnotes: ["℘ Offb 15,8", "℘ Kap. 7,1; 2Mo 29,43"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "*Damals sprach Salomo: Der HERR hat gesagt, dass er im Dunkel wohnen will.", heading: "Salomos Ansprache und Gebet", footnotes: ["℘ 1Kö 8,12-53"] },
      { number: 2, text: "Ich aber, ich habe dir ein fürstliches Haus gebaut* und eine Stätte, wo du thronen* sollst für Ewigkeiten.", footnotes: ["℘ Apg 7,47", "o. wohnen"] },
      { number: 3, text: "Darauf wandte der König sein Angesicht und segnete die ganze Versammlung Israels, wobei die ganze Versammlung Israels dastand." },
      { number: 4, text: "Und er sprach: Gepriesen sei der HERR, der Gott Israels*, der mit seinem Mund zu meinem Vater David geredet* und mit seiner Hand erfüllt hat, was er verheißen, als er sprach:", footnotes: ["℘ Neh 8,6", "℘ V. 15"] },
      { number: 5, text: "Von dem Tag an, da ich mein Volk aus dem Land Ägypten herausführte, habe ich aus allen Stämmen Israels keine Stadt erwählt, um darin ein Haus zu bauen, damit mein Name dort sei*; und ich habe keinen Mann erwählt, dass er Fürst über mein Volk Israel sei.", footnotes: ["℘ V. 20; Kap. 7,16; 12,13; 20,8.9; 30,8; 33,4.7; 2Kö 21,4.7; 1Chr 17,5; Esr 7,16; Sach 3,2"] },
      { number: 6, text: "Aber Jerusalem habe ich erwählt, dass mein Name dort sei*, und David habe ich erwählt, dass er über mein Volk Israel König sei*.", footnotes: ["℘ V. 20; Kap. 7,16; 12,13; 20,8.9; 30,8; 33,4.7; 2Kö 21,4.7; 1Chr 17,5; Esr 7,16; Sach 3,2", "℘ 1Chr 17,7; Ps 78,68.70"] },
      { number: 7, text: "Nun lag es meinem Vater David am Herzen, dem Namen des HERRN, des Gottes Israels, ein Haus zu bauen." },
      { number: 8, text: "Und der HERR sprach zu meinem Vater David: Dass dir das am Herzen lag, meinem Namen ein Haus zu bauen, daran hast du gut getan; denn es lag dir das am Herzen." },
      { number: 9, text: "Jedoch wirst du selbst das Haus nicht bauen*, sondern dein Sohn, der aus deinen Lenden hervorkommt*, der wird meinem Namen das Haus bauen.", footnotes: ["℘ 1Chr 28,3", "d. h. der von dir abstammt; die Lenden galten als Sitz der Zeugungskraft"] },
      { number: 10, text: "Und der HERR hat sein Wort aufrechterhalten, das er geredet hat. So bin ich denn an die Stelle meines Vaters David getreten und habe mich auf den Thron Israels gesetzt, so wie der HERR zugesagt hat, und habe dem Namen des HERRN, des Gottes Israels, das Haus gebaut*.", footnotes: ["℘ 1Chr 22,11; Apg 7,47"] },
      { number: 11, text: "Und ich habe dort die Lade hingestellt, in der der Bund des HERRN ist, den er mit den Söhnen Israel geschlossen hat." },
      { number: 12, text: "Und er trat vor den Altar des HERRN angesichts der ganzen Versammlung Israels und breitete seine Hände aus." },
      { number: 13, text: "Denn Salomo hatte ein Gestell* aus Bronze gemacht* und es mitten in den Hof gestellt: fünf Ellen seine Länge und fünf Ellen seine Breite und drei Ellen seine Höhe. Und er trat darauf und kniete angesichts der ganzen Versammlung Israels auf seine Knie nieder*, breitete seine Hände aus zum Himmel*", footnotes: ["o. eine Plattform; o. eine Tribüne", "℘ Neh 8,4", "℘ Ps 95,6", "℘ 2Mo 9,29; Esr 9,5; Neh 1,4"] },
      { number: 14, text: "und sprach: HERR, Gott Israels! Kein Gott ist dir gleich im Himmel und auf der Erde*, der du den Bund und die Gnade deinen Knechten bewahrst, die vor dir leben* mit ihrem ganzen Herzen,", footnotes: ["℘ Kap. 20,6; 2Mo 8,6", "w. gehen"] },
      { number: 15, text: "der du deinem Knecht, meinem Vater David, gehalten hast, was du ihm zugesagt hast*! Mit deinem Mund hast du es geredet, und mit deiner Hand hast du es erfüllt, wie es am heutigen Tag ist.", footnotes: ["℘ V. 4"] },
      { number: 16, text: "Und nun, HERR, Gott Israels, halte deinem Knecht, meinem Vater David, was du ihm zugesagt hast, als du sprachst: Es soll dir nicht an einem Mann fehlen vor meinem Angesicht*, der auf dem Thron Israels sitzt, wenn nur deine Söhne auf ihren Weg achten, dass sie in meinem Gesetz leben*, wie du vor mir gelebt hast*!*", footnotes: ["w. Nicht soll dir ausgerottet werden ein Mann von meinem Angesicht weg", "w. gehen", "w. gegangen bist", "℘ Kap. 7,17.18; 13,5; 21,7; 23,3; 2Sam 7,16"] },
      { number: 17, text: "Und nun, HERR, Gott Israels, möge sich dein Wort als zuverlässig erweisen, das du zu deinem Knecht David geredet hast!* —", footnotes: ["℘ 2Sam 7,25"] },
      { number: 18, text: "Ja, sollte Gott wirklich bei dem Menschen auf der Erde wohnen?* Siehe, der Himmel und die Himmel der Himmel können dich nicht fassen*, wie viel weniger dieses Haus, das ich gebaut habe!", footnotes: ["℘ 2Mo 29,45; Joh 1,14; Offb 21,3", "℘ Kap. 2,5; Jer 23,24; Eph 4,10"] },
      { number: 19, text: "Doch wende dich zu dem Gebet deines Knechtes und zu seinem Flehen, HERR, mein Gott, dass du hörst auf das Rufen und auf das Gebet, das dein Knecht vor dir betet," },
      { number: 20, text: "dass deine Augen Tag und Nacht geöffnet seien über dieses Haus, über die Stätte, von der du gesagt hast, dass du deinen Namen dort niederlegen willst*, dass du hörst auf das Gebet, das dein Knecht zu dieser Stätte hin betet*!", footnotes: ["℘ V. 5.6", "℘ V. 40; Kap. 7,15"] },
      { number: 21, text: "Und höre auf das Flehen deines Knechtes und deines Volkes Israel, das sie zu dieser Stätte hin richten werden! *Du selbst mögest es hören von der Stätte her, wo du thronst, vom Himmel her*! Ja, höre und vergib!*", footnotes: ["o. Du selbst mögest es hören am Ort deines Wohnens und im Himmel. Und wenn du es hörst, dann vergib!", "℘ Kap. 30,27; Jes 18,4", "o. Du selbst mögest es hören am Ort deines Wohnens und im Himmel. Und wenn du es hörst, dann vergib!"] },
      { number: 22, text: "Wenn jemand gegen seinen Nächsten sündigt und der einen Fluch auf ihn legt*, um ihn unter einen Fluch zu stellen, und er kommt und spricht den Fluch aus vor deinem Altar in diesem Haus,", footnotes: ["so mit einigen hebr. Handschr. und LXX; Mas. T.: und von ihm einen geleisteten Fluch einfordert"] },
      { number: 23, text: "dann höre du es vom Himmel her, und handle und richte deine Knechte, indem du dem Schuldigen vergiltst, um seinen Weg auf seinen Kopf zu bringen, und indem du den Gerechten gerecht sprichst, um ihm nach seiner Gerechtigkeit zu geben*.", footnotes: ["℘ Hes 18,20"] },
      { number: 24, text: "Und wenn dein Volk Israel vor dem Feind geschlagen wird, weil sie gegen dich gesündigt haben*, und sie kehren zu dir um und preisen deinen Namen und beten und flehen vor dir um Gnade in diesem Haus,", footnotes: ["℘ 5Mo 28,25"] },
      { number: 25, text: "dann höre du es vom Himmel her, und vergib die Sünde deines Volkes Israel! Und bring sie in das Land zurück, das du ihnen und ihren Vätern gegeben hast!*", footnotes: ["℘ Ps 106,44-47"] },
      { number: 26, text: "Bleibt der Himmel verschlossen, so dass es keinen Regen gibt*, weil sie gegen dich gesündigt haben*, und sie beten zu dieser Stätte hin und preisen deinen Namen und kehren um von ihrer Sünde, weil du sie demütigst*,", footnotes: ["℘ Kap. 7,13", "℘ 5Mo 11,17", "℘ Spr 28,13"] },
      { number: 27, text: "dann höre du es im Himmel und vergib die Sünde deiner Knechte und deines Volkes Israel*! Denn du zeigst ihnen den guten Weg, auf dem sie gehen sollen. Und gib Regen auf dein Land, das du deinem Volk zum Erbteil gegeben hast!*", footnotes: ["℘ Joe 2,12.13", "℘ Kap. 7,14"] },
      { number: 28, text: "Wenn eine Hungersnot im Lande herrscht*, wenn eine Pest ausbricht, wenn es Getreidebrand und Vergilben des Getreides, Heuschrecken oder Heuschreckenlarven gibt*, wenn seine Feinde es im Land seiner Tore belagern, wenn es irgendeine Plage und irgendeine Krankheit gibt —", footnotes: ["℘ Kap. 7,13", "℘ Joe 1,4"] },
      { number: 29, text: "jedes Gebet, jedes Flehen, das dann von irgendeinem Menschen oder von deinem ganzen Volk Israel vorgebracht wird, je nachdem, was einer als seine Plage oder seinen Schmerz erkennt*, wenn er seine Hände gegen dieses Haus hin ausbreitet*,", footnotes: ["℘ Ps 32,5.6", "℘ Kap. 20,9"] },
      { number: 30, text: "das erhöre du vom Himmel her, der Stätte, wo du thronst*! Und vergib und gib jedem nach all seinen Wegen, da du sein Herz kennst* — denn du, du allein kennst das Herz der Menschenkinder* —,", footnotes: ["w. der Stätte deines Thronens o. Wohnens", "℘ 1Chr 29,17; Ps 7,10; Spr 15,11", "℘ Joh 2,25; Apg 1,24"] },
      { number: 31, text: "damit sie dich fürchten, so dass sie auf deinen Wegen gehen all die Tage, die sie in dem Land leben, das du unsern Vätern gegeben hast!" },
      { number: 32, text: "Und auch auf den Ausländer, der nicht von deinem Volk Israel ist, aber wegen deines großen Namens und deiner starken Hand und deines ausgestreckten Armes aus fernem Land kommt — wenn sie kommen und beten zu diesem Haus hin," },
      { number: 33, text: "dann höre du es vom Himmel her, der Stätte, wo du thronst*! Und handle nach allem, worum der Ausländer zu dir ruft, damit alle Völker der Erde deinen Namen erkennen und damit sie dich fürchten wie dein Volk Israel* und damit sie erkennen, dass dein Name ausgerufen ist über diesem Haus, das ich gebaut habe!", footnotes: ["w. der Stätte deines Thronens o. Wohnens", "℘ Ps 86,9"] },
      { number: 34, text: "Wenn dein Volk zum Krieg gegen seine Feinde auszieht auf dem Weg, den du sie sendest, und wenn sie dann zu dir beten in Richtung auf diese Stadt hin, die du erwählt hast, und auf das Haus hin, das ich deinem Namen gebaut habe," },
      { number: 35, text: "dann höre vom Himmel her ihr Gebet und ihr Flehen und schaffe ihnen ihr Recht!" },
      { number: 36, text: "Wenn sie gegen dich sündigen — denn es gibt keinen Menschen, der nicht sündigt — und du über sie erzürnst und sie vor dem Feind dahingibst und ihre Bezwinger* sie gefangen wegführen in ein fernes oder in ein nahes Land,", footnotes: ["w. ihre Fänger, o. ihre Wegführer"] },
      { number: 37, text: "und sie nehmen es sich zu Herzen in dem Land, wohin sie gefangen weggeführt worden sind, und kehren um und flehen zu dir im Land ihrer Gefangenschaft, indem sie sagen: Wir haben gesündigt, wir haben uns schuldig gemacht und haben gottlos gehandelt*! —", footnotes: ["℘ Kap. 7,14; Dan 9,5"] },
      { number: 38, text: "und sie kehren zu dir um mit ihrem ganzen Herzen und mit ihrer ganzen Seele im Land ihrer Gefangenschaft, wohin man sie gefangen weggeführt hat, und sie beten in Richtung auf ihr Land, das du ihren Vätern gegeben hast, und auf die Stadt hin, die du erwählt hast, und auf das Haus hin, das ich deinem Namen gebaut habe," },
      { number: 39, text: "dann höre vom Himmel her, der Stätte, wo du thronst*, ihr Gebet und ihr Flehen und schaffe ihnen ihr Recht*! Und vergib deinem Volk, worin sie gegen dich gesündigt haben*! —", footnotes: ["w. der Stätte deines Thronens o. Wohnens", "℘ Jer 50,34", "℘ Ps 65,4; 85,3"] },
      { number: 40, text: "Nun, mein Gott, lass doch deine Augen offen sein und deine Ohren achthaben auf das Gebet an diesem Ort!*", footnotes: ["℘ V. 20"] },
      { number: 41, text: "Und nun, mach dich auf, HERR, Gott, zu deiner Ruhe, du und die Lade deiner Kraft!* Lass deine Priester, HERR, Gott, bekleidet sein mit Rettung* und deine Frommen des Guten sich freuen!*", footnotes: ["℘ Ps 132,8", "o. Heil", "℘ Jes 65,18"] },
      { number: 42, text: "HERR, Gott, weise das Gesicht deines Gesalbten nicht ab*! Denke an die Gnadenerweise deinem Knecht David gegenüber!*", footnotes: ["℘ Ps 84,10", "℘ Ps 132,10; Jes 55,3"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Und als Salomo zu Ende gebetet hatte, da fuhr das Feuer vom Himmel herab und verzehrte das Brandopfer und die Schlachtopfer*. Und die Herrlichkeit des HERRN erfüllte das Haus*.", heading: "Salomos Festopfer — Gottes Antwort", footnotes: ["℘ 1Kö 8,54-66; 9,1-9", "℘ 1Kö 18,38; 1Chr 21,26", "℘ Kap. 5,13.14; Ps 26,8"] },
      { number: 2, text: "Und die Priester konnten nicht in das Haus des HERRN hineingehen, denn die Herrlichkeit des HERRN erfüllte das Haus des HERRN*.", footnotes: ["℘ Kap. 5,13.14; Ps 26,8"] },
      { number: 3, text: "Und alle Söhne Israel sahen das Feuer herabfahren und die Herrlichkeit des HERRN über dem Haus. Da knieten sie mit dem Gesicht zur Erde auf das Pflaster nieder und beteten an*, und sie priesen den HERRN: Denn er ist gütig, denn seine Gnade währt ewig!", footnotes: ["w. und warfen sich nieder\n℘ Kap. 20,18; 29,28-30; 2Mo 4,31; 3Mo 9,24"] },
      { number: 4, text: "Und der König und das ganze Volk brachten vor dem HERRN Schlachtopfer dar*.", footnotes: ["w. schlachteten vor dem HERRN Schlachtopfer"] },
      { number: 5, text: "Und der König Salomo brachte als Schlachtopfer 22 000 Rinder und 120 000 Schafe dar*. So weihten der König und das ganze Volk das Haus Gottes ein.", footnotes: ["w. schlachtete als Schlachtopfer . . . 120 000 Schafe"] },
      { number: 6, text: "Und die Priester standen in ihren Dienstabteilungen* und die Leviten mit den Musikinstrumenten des HERRN, die der König David gemacht hatte, um den HERRN zu preisen: Denn seine Gnade währt ewig*! — wenn David auf ihnen den Lobpreis darbrachte*. Und die Priester bliesen ihnen gegenüber die Trompeten*, und ganz Israel stand.", footnotes: ["℘ Esr 6,18", "℘ Kap. 5,13", "℘ 1Chr 15,16", "℘ Kap. 5,12; 23,18; 29,27"] },
      { number: 7, text: "Und Salomo heiligte die Mitte des Vorhofes, der vor dem Haus des HERRN lag. Denn dort bereitete er die Brandopfer und die Fettstücke der Heilsopfer* zu. Denn der bronzene Altar, den Salomo gemacht hatte*, konnte das Brandopfer und das Speisopfer und die Fettstücke nicht fassen.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 4,1"] },
      { number: 8, text: "Und Salomo veranstaltete zu jener Zeit das Fest* und ganz Israel mit ihm, eine sehr große Versammlung von da, wo man nach Hamat hineinkommt*, bis an den Bach Ägyptens, sieben Tage lang*.", footnotes: ["d. i. das Laubhüttenfest", "o. von Lebo-Hamat", "℘ Kap. 5,3"] },
      { number: 9, text: "Und am achten Tag hielten sie eine Festversammlung. Denn sie feierten die Einweihung des Altars sieben Tage* und das Fest sieben Tage.", footnotes: ["℘ 2Mo 29,37; 1Kö 8,2"] },
      { number: 10, text: "Und am 23. Tag des siebten Monats entließ er das Volk zu ihren Zelten, fröhlich und guten Mutes über das Gute, das der HERR dem David und dem Salomo und seinem Volk Israel erwiesen hatte." },
      { number: 11, text: "Und so vollendete Salomo das Haus des HERRN und das Haus des Königs. Und alles, was Salomo ins Herz gekommen war, im Haus des HERRN und in seinem Haus zu machen, war ihm gelungen." },
      { number: 12, text: "Da erschien der HERR dem Salomo in der Nacht und sprach zu ihm: Ich habe dein Gebet gehört und mir diese Stätte zum Opferhaus erwählt*.", footnotes: ["℘ 5Mo 12,6"] },
      { number: 13, text: "Wenn ich den Himmel verschließe und kein Regen fällt oder wenn ich der Heuschrecke gebiete, das Land abzufressen, und wenn ich eine Pest unter mein Volk sende*,", footnotes: ["℘ Kap. 6,26.28"] },
      { number: 14, text: "und mein Volk, über dem mein Name ausgerufen ist*, demütigt sich*, und sie beten und suchen mein Angesicht* und kehren um von ihren bösen Wegen, dann werde ich vom Himmel her hören und ihre Sünden vergeben und ihr Land heilen*.", footnotes: ["℘ 4Mo 6,27; Jer 14,9", "℘ Kap. 6,37.38", "℘ Kap. 20,3.4; Ps 27,8; Jes 45,19; Jer 50,4", "℘ Kap. 6,27; Hes 33,12"] },
      { number: 15, text: "Jetzt werden meine Augen offen und meine Ohren aufmerksam sein auf das Gebet an dieser Stätte*.", footnotes: ["℘ Kap. 6,20.40; 1Kö 8,29; Jes 37,17"] },
      { number: 16, text: "Und jetzt habe ich dieses Haus erwählt und geheiligt, damit mein Name dort sei für ewig*. Und meine Augen und mein Herz sollen dort sein alle Tage.", footnotes: ["℘ Kap. 6,5.6; 30,8; 33,4.7; Ps 132,13"] },
      { number: 17, text: "Und du, wenn du vor mir lebst*, ebenso wie dein Vater David gelebt hat*, indem du nach allem handelst, was ich dir geboten habe, und wenn du meine Ordnungen und meine Rechtsbestimmungen einhältst,", footnotes: ["w. gehst", "w. gegangen ist"] },
      { number: 18, text: "dann werde ich den Thron deiner Königsherrschaft festigen, so wie ich mit deinem Vater David einen Bund geschlossen und gesagt habe: Es soll dir nicht an einem Mann fehlen*, der über Israel herrscht*.", footnotes: ["w. Nicht soll dir ein Mann ausgerottet werden", "℘ Kap. 6,16; Ps 132,11.12"] },
      { number: 19, text: "Wenn ihr euch aber abwendet und meine Ordnungen und meine Gebote, die ich euch vorgelegt habe, verlasst* und hingeht und andern Göttern dient und euch vor ihnen niederwerft*,", footnotes: ["℘ Kap. 33,8; 5Mo 28,15", "℘ 2Mo 20,5"] },
      { number: 20, text: "dann werde ich sie ausreißen aus meinem Land, das ich ihnen gegeben habe. Und dieses Haus, das ich meinem Namen geheiligt habe, werde ich von meinem Angesicht wegstoßen* und werde es zum Sprichwort und zur Spottrede unter allen Völkern machen.", footnotes: ["℘ Kap. 36,19"] },
      { number: 21, text: "Und dieses Haus, das erhaben war* — jeder, der an ihm vorübergeht, wird sich entsetzen und sagen: Warum hat der HERR an diesem Land und an diesem Haus so gehandelt?", footnotes: ["eine LXX-Ausgabe: Und dieses Haus wird verwüstet werden"] },
      { number: 22, text: "Dann wird man sagen: Weil sie den HERRN, den Gott ihrer Väter, der sie aus dem Land Ägypten herausgeführt hat, verlassen und sich an andere Götter gehalten haben und sich vor ihnen niedergeworfen und ihnen gedient haben, darum hat er all dieses Unheil über sie gebracht*.", footnotes: ["℘ Jer 22,5.8.9"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Und es geschah am Ende der zwanzig Jahre, in denen Salomo das Haus des HERRN* und sein eigenes Haus gebaut hatte*,", heading: "Salomos Städtebauten, Zwangsarbeiter, Tempeldienst und Schifffahrt", footnotes: ["℘ 1Kö 9,10-28", "℘ 1Kö 6,38", "℘ 1Kö 7,1; 9,1"] },
      { number: 2, text: "da baute Salomo die Städte aus, die Hiram dem Salomo gegeben hatte; und er ließ die Söhne Israel dort wohnen." },
      { number: 3, text: "Und Salomo zog nach Hamat-Zoba* und überwältigte es.", footnotes: ["℘ 2Sam 8,3; 2Kö 14,28; 19,13; 1Chr 18,3"] },
      { number: 4, text: "Und er baute Tadmor in der Wüste und alle Vorratsstädte*, die er in Hamat baute.", footnotes: ["℘ Kap. 17,12"] },
      { number: 5, text: "Und er baute das obere Bet-Horon und das untere Bet-Horon*, feste Städte mit Mauern, Toren und Riegeln,", footnotes: ["℘ Jos 16,3"] },
      { number: 6, text: "und Baalat und alle Vorratsstädte*, die Salomo hatte, und alle Wagenstädte und die Pferdestädte* und alles, was Salomo sonst noch zu bauen wünschte* in Jerusalem und auf dem Libanon und im ganzen Land seiner Herrschaft*. —", footnotes: ["℘ Kap. 17,12", "℘ Kap. 1,14", "w. alle Lust Salomos, die er Lust hatte zu bauen", "℘ Pred 2,4"] },
      { number: 7, text: "Alles Volk, das übrig geblieben war von den Hetitern und den Amoritern und den Perisitern und den Hewitern und den Jebusitern, die nicht von Israel waren*,", footnotes: ["℘ 5Mo 7,1; Esr 9,1"] },
      { number: 8, text: "deren Söhne*, die nach ihnen im Land übrig geblieben waren, die die Söhne Israel nicht ausgetilgt hatten, die hob Salomo zur Zwangsarbeit aus; und so ist es bis auf den heutigen Tag*.", footnotes: ["w. von ihren Söhnen", "℘ Kap. 2,16.17; 1Kö 5,29"] },
      { number: 9, text: "Aber von den Söhnen Israel machte Salomo keine Sklaven für seine Arbeit; sondern sie waren Kriegsleute und Oberste über seine Wagenkämpfer* und Oberste über seine Streitwagen und seine Pferde.", footnotes: ["w. seine Dritten; d. i. der dritte Mann auf einem Streitwagen"] },
      { number: 10, text: "Und das sind die Obersten der Vögte*, die der König Salomo hatte: 250, die über das Volk herrschten.", footnotes: ["so mit der Leseform des Mas. T.; mit der Schreibform: der Besatzungen"] },
      { number: 11, text: "Und Salomo führte die Tochter des Pharao aus der Stadt Davids herauf in das Haus, das er für sie gebaut hatte*. Denn er sagte: Eine Frau soll mir nicht in dem Haus Davids, des Königs von Israel, wohnen; denn die Räume* sind ein Heiligtum, weil die Lade des HERRN gekommen ist.", footnotes: ["℘ 1Kö 7,8", "w. sie"] },
      { number: 12, text: "Damals opferte Salomo dem HERRN Brandopfer auf dem Altar des HERRN*, den er vor der Vorhalle gebaut hatte*,", footnotes: ["℘ Kap. 1,6", "℘ Kap. 4,1"] },
      { number: 13, text: "und zwar nach der Bestimmung* für jeden Tag, indem er opferte nach dem Gebot des Mose an den Sabbaten und an den Neumonden und an den Festen* dreimal im Jahr: Am Fest der ungesäuerten Brote und am Fest der Wochen und am Fest der Laubhütten.", footnotes: ["w. nach dem Wort", "℘ Kap. 2,3; Hes 45,17"] },
      { number: 14, text: "Und er bestellte nach der Vorschrift seines Vaters David die Abteilungen der Priester zu ihrem Dienst* und die Leviten zu ihren Ämtern, zum Loben und Dienen vor den Priestern nach der Bestimmung* für jeden Tag*, und die Torhüter in ihren Abteilungen für jedes Tor*; denn so war das Gebot Davids*, des Mannes Gottes*.", footnotes: ["℘ Kap. 29,25", "w. nach dem Wort", "℘ 1Chr 25,1; Hebr 13,15", "℘ Kap. 23,19; 35,15; 1Chr 9,17-24; 26,1; Neh 12,25", "℘ 1Chr 23-26", "℘ 5Mo 33,1; Neh 12,36"] },
      { number: 15, text: "Und man wich nicht von dem Gebot des Königs über die Priester und die Leviten ab, auch nicht bei jeder anderen Sache und bei den Schätzen*. —", footnotes: ["℘ 1Chr 26,20-28"] },
      { number: 16, text: "Und so wurde das ganze Werk Salomos fertiggestellt, vom Tag der Grundlegung des Hauses des HERRN bis zu seiner Vollendung. Das Haus des HERRN war fertig*.", footnotes: ["℘ 1Kö 6,37.38"] },
      { number: 17, text: "Damals ging Salomo nach Hezjon-Geber* und nach Elot*, am Ufer des Meeres im Land Edom.", footnotes: ["℘ Kap. 20,36", "d. i. Elat"] },
      { number: 18, text: "Und Hiram schickte ihm durch seine Knechte Schiffe und seekundige Knechte*. Und sie gelangten mit den Knechten Salomos nach Ofir und holten von dort 450 Talente Gold* und brachten es zum König Salomo.", footnotes: ["℘ Kap. 9,21", "℘ Kap. 9,10"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Und die Königin von Saba hörte von Salomos Ruf. Und sie kam nach Jerusalem, um Salomo mit Rätselfragen zu prüfen, mit einem sehr zahlreichen Gefolge* und mit Kamelen, die Balsamöle und Gold in Menge trugen und Edelsteine. Und sie kam zu Salomo und redete mit ihm alles, was in ihrem Herzen war*.", heading: "Die Königin von Saba bei Salomo", footnotes: ["℘ 1Kö 10,1-13", "o. mit sehr reichen Schätzen", "℘ Lk 11,31"] },
      { number: 2, text: "Und Salomo beantwortete ihr alle ihre Fragen*. Nichts war vor Salomo verborgen, das er ihr nicht hätte beantworten können*.", footnotes: ["w. Und Salomo teilte ihr all ihre Worte mit", "w. das er ihr nicht mitteilte"] },
      { number: 3, text: "Und als die Königin von Saba die Weisheit Salomos sah und das Haus, das er gebaut hatte," },
      { number: 4, text: "und die Speise auf seiner Tafel* und die Sitzordnung* seiner Knechte und die Aufwartung seiner Diener und ihre Kleidung und seine Mundschenken und ihre Kleidung und sein Brandopfer, das er im Haus des HERRN opferte*, da geriet sie vor Staunen außer sich*", footnotes: ["℘ 1Kö 5,2.3", "w. das Sitzen, o. den Sitzplatz", "T.; Mas. T.: und sein Obergemach, von dem er ins Haus des HERRN hinaufging", "w. da hatte sie keinen Atem mehr"] },
      { number: 5, text: "und sagte zu dem König: Das Wort ist Wahrheit gewesen, das ich in meinem Land über deine Taten* und über deine Weisheit gehört habe.", footnotes: ["w. Sachen, o. Worte"] },
      { number: 6, text: "Ich habe ihren Worten nicht geglaubt, bis ich gekommen bin und meine Augen es gesehen haben. Und siehe, nicht die Hälfte ist mir berichtet worden von der Größe deiner Weisheit. Du hast die Kunde, die ich gehört habe, übertroffen." },
      { number: 7, text: "Glücklich sind deine Männer* und glücklich diese deine Knechte, die ständig vor dir stehen und deine Weisheit hören!", footnotes: ["eine LXX-Ausgabe: deine Frauen"] },
      { number: 8, text: "Gepriesen sei der HERR, dein Gott, der Gefallen an dir gehabt hat, dich auf seinen Thron zu setzen als König für den HERRN, deinen Gott!* Weil dein Gott Israel liebt, um es ewig bestehen zu lassen, hat er dich als König über sie gesetzt*, damit du Recht und Gerechtigkeit übst.", footnotes: ["℘ Kap. 13,8; 1Chr 29,23", "℘ Kap. 2,10"] },
      { number: 9, text: "Und sie gab dem König 120 Talente Gold und Balsamöle in großer Menge und Edelsteine. Nie wieder hat es solches Balsamöl gegeben wie dieses, das die Königin von Saba dem König Salomo gab." },
      { number: 10, text: "(Auch die Knechte Hirams und die Knechte Salomos, die Gold aus Ofir* holten, brachten Almuggimhölzer und Edelsteine.", footnotes: ["℘ Kap. 8,18"] },
      { number: 11, text: "Und der König machte von den Almuggimhölzern Treppen* für das Haus des HERRN und für das Haus des Königs und Zithern und Harfen für die Sänger. Solches Holz ist früher im Land Juda nicht gesehen worden.)", footnotes: ["so mit LXX und Vulg.; Mas. T.: Straßen, o. Aufschüttungen"] },
      { number: 12, text: "Der König Salomo aber gab der Königin von Saba alles, was sie sich wünschte*, was sie erbat, abgesehen von dem Gegengeschenk für das, was sie dem König gebracht hatte. Und sie wandte sich und zog in ihr Land, sie und ihre Knechte.", footnotes: ["w. jeden Wunsch von ihr"] },
      { number: 13, text: "*Und das Gewicht des Goldes, das bei Salomo in einem einzigen Jahr einging, war 666 Talente Gold", heading: "Salomos Reichtum", footnotes: ["℘ 1Kö 10,14-29"] },
      { number: 14, text: "außer dem, was die Handelsleute und die Händler einbrachten. Und alle Könige von Arabien und die Statthalter des Landes brachten Salomo Gold und Silber*.", footnotes: ["℘ Ps 68,30"] },
      { number: 15, text: "Und der König Salomo machte zweihundert Langschilde aus legiertem Gold* — mit sechshundert Schekel legiertem Gold überzog er jeden Langschild —", footnotes: ["o. gehämmertem Gold\n℘ Kap. 12,9"] },
      { number: 16, text: "und dreihundert Kleinschilde aus legiertem Gold* — mit dreihundert Schekel Gold überzog er jeden Kleinschild. Und der König gab sie in das Libanonwaldhaus.", footnotes: ["o. gehämmertem Gold"] },
      { number: 17, text: "Und der König machte einen großen Thron aus Elfenbein und überzog ihn mit reinem Gold." },
      { number: 18, text: "Der Thron hatte sechs Stufen und einen goldenen Fußschemel, die an dem Thron befestigt waren. Und Armlehnen waren auf dieser und auf jener Seite am Sitzplatz. Und zwei Löwen standen neben den Armlehnen;" },
      { number: 19, text: "und zwölf Löwen standen da auf den sechs Stufen, auf dieser und auf jener Seite. Niemals ist so etwas gemacht worden für irgendein Königreich." },
      { number: 20, text: "Und alle Trinkgefäße des Königs Salomo waren aus Gold, und alle Geräte des Libanonwaldhauses waren aus gediegenem Gold; das Silber galt in den Tagen Salomos überhaupt nichts." },
      { number: 21, text: "Denn Schiffe des Königs fuhren nach Tarsis* mit den Knechten Hirams*. Einmal in drei Jahren kamen Tarsisschiffe, beladen mit Gold und Silber*, Elfenbein und Affen und Pavianen*.", footnotes: ["℘ Jon 1,3", "℘ Kap. 8,18", "℘ Jer 10,9; Hes 27,12", "o. Pfauen"] },
      { number: 22, text: "So war der König Salomo größer als alle Könige der Erde an Reichtum und Weisheit*.", footnotes: ["℘ Kap. 1,12; 1Kö 5,9-11"] },
      { number: 23, text: "Und alle Könige der Erde suchten das Angesicht Salomos, um seine Weisheit zu hören, die Gott in sein Herz gegeben hatte." },
      { number: 24, text: "Und sie brachten jeder sein Geschenk*: Geräte aus Silber und Geräte aus Gold und Gewänder, Waffen und Balsamöle, Pferde und Maultiere. So geschah es Jahr für Jahr*. —", footnotes: ["℘ Kap. 17,11; Ri 3,15", "w. Die Sache des Jahres in ihrem Jahr\n℘ Ps 68,30"] },
      { number: 25, text: "Und Salomo hatte viertausend Stallplätze für Pferde und Streitwagen und 12 000 Pferde. Und er legte sie in die Wagenstädte und in die Umgebung des Königs nach Jerusalem*.", footnotes: ["℘ Kap. 1,14"] },
      { number: 26, text: "Und er war Herrscher über alle Könige, vom Euphratstrom an bis zum Land der Philister und bis zur Grenze Ägyptens*.", footnotes: ["℘ 2Mo 23,31; 1Kö 5,1.4"] },
      { number: 27, text: "Und der König machte das Silber in Jerusalem an Menge den Steinen gleich, und die Zedern machte er an Menge den Maulbeerfeigenbäumen gleich, die in der Niederung* sind*.", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 1,15"] },
      { number: 28, text: "Und man führte Pferde für Salomo aus Ägypten und aus allen Ländern aus*.", footnotes: ["℘ Kap. 1,16.17"] },
      { number: 29, text: "*Die übrige Geschichte* Salomos, die frühere und die spätere*, ist die nicht geschrieben in der Geschichte* Nathans, des Propheten*, und in der Weissagung Ahijas, des Siloniters*, und in den Gesichten Jedos, des Sehers*, über Jerobeam, den Sohn des Nebat*?", heading: "Salomos Tod", footnotes: ["℘ 1Kö 11,41-43", "w. Der Rest der Begebenheiten", "℘ 1Chr 29,29", "w. in den Begebenheiten", "℘ Ps 68,30", "℘ 1Kö 11,29", "℘ Kap. 12,15; 13,22", "℘ Kap. 10,2; 1Kö 11,26"] },
      { number: 30, text: "Und Salomo regierte in Jerusalem vierzig Jahre über ganz Israel*.", footnotes: ["℘ 1Chr 29,23"] },
      { number: 31, text: "Und Salomo legte sich zu seinen Vätern, und man begrub ihn in der Stadt seines Vaters David. Und sein Sohn Rehabeam wurde König an seiner Stelle*.", footnotes: ["℘ Kap. 10,1"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und Rehabeam ging nach Sichem; denn ganz Israel war nach Sichem gekommen, um ihn zum König zu machen*.", heading: "Die Teilung des Reiches — Rehabeam und Jerobeam", footnotes: ["℘ 1Kö 12,1-20", "℘ Kap. 9,31"] },
      { number: 2, text: "Und es geschah, als Jerobeam, der Sohn des Nebat*, das hörte — er war aber in Ägypten, wohin er vor dem König Salomo geflohen war* —, da kehrte Jerobeam aus Ägypten zurück.", footnotes: ["℘ Kap. 9,29", "℘ 1Kö 11,40"] },
      { number: 3, text: "Und sie sandten hin und ließen ihn rufen. Da kamen Jerobeam und ganz Israel und redeten zu Rehabeam und sagten:" },
      { number: 4, text: "Dein Vater hat unser Joch hart gemacht. Und nun erleichtere den harten Dienst deines Vaters und sein schweres Joch, das er auf uns gelegt hat! Dann wollen wir dir dienen." },
      { number: 5, text: "Er sagte zu ihnen: Noch drei Tage, dann kommt wieder zu mir! Und das Volk ging hin." },
      { number: 6, text: "Und der König Rehabeam beriet sich mit den Alten, die vor seinem Vater Salomo gestanden hatten, als er noch am Leben war, und sagte: Wie ratet ihr, diesem Volk Antwort zu geben?" },
      { number: 7, text: "Und sie redeten zu ihm und sagten: Wenn du zu diesem Volk gütig und ihnen zu Willen bist und gute Worte zu ihnen redest, dann werden sie alle Tage deine Knechte sein." },
      { number: 8, text: "Doch er verwarf den Rat der Alten*, den sie ihm geraten hatten, und beriet sich mit den Jüngeren*, die mit ihm groß geworden waren und die vor ihm standen.", footnotes: ["℘ Spr 27,10", "w. mit den Kindern"] },
      { number: 9, text: "Und er sagte zu ihnen: Was ratet ihr, dass wir diesem Volk zur Antwort geben, das zu mir geredet und gesagt hat: Erleichtere das Joch, das dein Vater auf uns gelegt hat?" },
      { number: 10, text: "Und die Jüngeren*, die mit ihm groß geworden waren, redeten zu ihm und sagten: So sollst du zu dem Volk sagen*, das zu dir geredet und gesagt hat: Dein Vater hat unser Joch schwer gemacht. Du aber erleichtere es uns! — so sollst du zu ihnen reden: Mein kleiner Finger ist dicker als die Hüften meines Vaters!", footnotes: ["w. Kinder", "℘ Spr 19,27"] },
      { number: 11, text: "Nun denn, mein Vater hat euch ein schweres Joch aufgeladen, ich aber will euer Joch noch schwerer machen*. Mein Vater hat euch mit Peitschen gezüchtigt, ich aber will euch mit Skorpionen* züchtigen.", footnotes: ["w. ich will auf euer Joch hinzufügen", "o. Geißeln"] },
      { number: 12, text: "Und Jerobeam und das ganze Volk kamen zu Rehabeam am dritten Tag, wie der König geredet hatte, als er sagte: Kommt am dritten Tag wieder zu mir!" },
      { number: 13, text: "Und der König antwortete ihnen hart. Und der König Rehabeam verwarf den Rat der Alten" },
      { number: 14, text: "und redete zu ihnen nach dem Rat der Jüngeren*: Mein Vater hat euer Joch schwer gemacht, ich aber will es noch schwerer machen*. Mein Vater hat euch mit Peitschen gezüchtigt, ich aber will euch mit Skorpionen* züchtigen.", footnotes: ["w. Kinder", "w. ich will auf euer Joch hinzufügen", "o. Geißeln"] },
      { number: 15, text: "So hörte der König nicht auf das Volk. Denn es war eine Wendung vonseiten Gottes*, damit der HERR sein Wort aufrecht hielte, das er durch Ahija, den Siloniter, zu Jerobeam, dem Sohn des Nebat, geredet hatte.*", footnotes: ["℘ Kap. 22,7; 25,20; 5Mo 2,30; 1Sam 2,25; 2Sam 17,14", "℘ 1Kö 11,29-39"] },
      { number: 16, text: "Und als ganz Israel sah, dass der König nicht auf sie hörte, da antwortete das Volk dem König: Was für einen Anteil haben wir an David? Wir haben kein Erbteil am Sohn Isais! Jeder zu seinen Zelten, Israel! Nun sieh nach deinem Haus, David! Und ganz Israel ging zu seinen Zelten." },
      { number: 17, text: "Die Söhne Israel aber, die in den Städten Judas wohnten, über sie wurde Rehabeam König*.", footnotes: ["℘ Kap. 11,3.12"] },
      { number: 18, text: "Und der König Rehabeam schickte Hadoram, den Aufseher über die Zwangsarbeit, aus. Aber die Söhne Israel steinigten ihn, so dass er starb. Der König Rehabeam aber bestieg eilends den Wagen*, um nach Jerusalem zu fliehen.", footnotes: ["o. Dem König Rehabeam gelang es gerade noch, den Wagen zu besteigen"] },
      { number: 19, text: "So brach Israel mit dem Haus Davids bis auf den heutigen Tag." },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Und Rehabeam kam nach Jerusalem und versammelte das Haus Juda und Benjamin, 180 000 auserlesene Krieger, um mit Israel zu kämpfen, damit er das Königreich an Rehabeam zurückbrächte.", heading: "Rehabeam von Juda", footnotes: ["℘ V. 1-4: 1Kö 12,21-24"] },
      { number: 2, text: "Da geschah das Wort des HERRN zu Schemaja*, dem Mann Gottes:", footnotes: ["℘ Kap. 12,5.15"] },
      { number: 3, text: "Sage zu Rehabeam, dem Sohn Salomos, dem König von Juda, und zu ganz Israel in Juda und Benjamin*:", footnotes: ["℘ Kap. 10,17"] },
      { number: 4, text: "So spricht der HERR: Ihr sollt nicht hinaufziehen und sollt nicht mit euren Brüdern kämpfen! Kehrt um, jeder in sein Haus, denn von mir ist diese Sache ausgegangen! Da hörten sie auf die Worte des HERRN und kehrten um und zogen nicht gegen Jerobeam." },
      { number: 5, text: "Und Rehabeam wohnte in Jerusalem. Und er baute Städte zu Festungen aus in Juda*.", footnotes: ["℘ Kap. 12,4; 14,6; 17,12"] },
      { number: 6, text: "Und er baute Bethlehem* und Etam* und Tekoa*", footnotes: ["℘ 1Mo 35,19", "℘ Ri 15,8.11", "℘ Kap. 20,20; 2Sam 14,2; Neh 3,5.27"] },
      { number: 7, text: "und Bet-Zur* und Socho* und Adullam*", footnotes: ["℘ Jos 15,58", "℘ Kap. 28,18; Jos 15,35", "℘ Ps 68,30"] },
      { number: 8, text: "und Gat* und Marescha* und Sif*", footnotes: ["℘ Kap. 26,6; 1Chr 18,1", "℘ Kap. 14,8; 20,37; Jos 15,44", "℘ Jos 15,55"] },
      { number: 9, text: "und Adorajim und Lachisch* und Aseka*", footnotes: ["℘ Kap. 25,27; 32,9; Jos 10,31", "℘ Jos 15,35; Jer 34,7"] },
      { number: 10, text: "und Zora* und Ajalon* und Hebron*, befestigte Städte, die in Juda und Benjamin sind.", footnotes: ["℘ Jos 15,33", "℘ Kap. 28,18; Jos 10,12", "℘ Jos 15,13"] },
      { number: 11, text: "Und er machte die Festungen stark und legte Befehlshaber* hinein und Vorräte von Speise, Öl und Wein*,", footnotes: ["w. Fürsten", "℘ Kap. 17,12.13"] },
      { number: 12, text: "und in jede Stadt Schilde und Spieße; und er machte sie überaus stark*. Und Juda und Benjamin gehörten ihm*.", footnotes: ["℘ Kap. 17,12.13", "℘ Kap. 10,17; 15,2; Hes 37,16"] },
      { number: 13, text: "Und die Priester und die Leviten, die in ganz Israel waren, stellten sich bei ihm ein* aus allen ihren Gebieten*.", footnotes: ["w. stellten sich zu ihm", "℘ Kap. 23,2"] },
      { number: 14, text: "Denn die Leviten verließen ihre Weideplätze und ihr Besitztum* und zogen nach Juda und nach Jerusalem. Denn Jerobeam und seine Söhne hatten sie aus dem Priesterdienst des HERRN verstoßen*,", footnotes: ["℘ 4Mo 35,2-8", "℘ Kap. 13,9"] },
      { number: 15, text: "und er hatte sich Priester angestellt für die Höhen und für die Bocksdämonen* und für die Kälber, die er gemacht hatte*.", footnotes: ["w. für die Haarigen\n℘ 3Mo 17,7", "℘ 1Kö 12,28-31"] },
      { number: 16, text: "Und ihnen folgten aus allen Stämmen Israels die, die ihr Herz darauf richteten, den HERRN, den Gott Israels, zu suchen*. Sie kamen nach Jerusalem, um dem HERRN, dem Gott ihrer Väter, zu opfern*.", footnotes: ["℘ Kap. 15,12; 19,3; 20,3.4; Sach 8,21", "℘ Kap. 15,9.11; 30,11"] },
      { number: 17, text: "Und sie unterstützten das Königreich Juda und stärkten Rehabeam, den Sohn Salomos, drei Jahre lang. Denn drei Jahre lang gingen sie auf dem Weg Davids und Salomos*.", footnotes: ["℘ Kap. 12,1"] },
      { number: 18, text: "Und Rehabeam nahm sich zur Frau Mahalat, die Tochter Jerimots, des Sohnes Davids, und der Abihajil, der Tochter Eliabs*, des Sohnes Isais.", footnotes: ["℘ 1Sam 17,28"] },
      { number: 19, text: "Und sie gebar ihm Söhne: Jëusch und Schemarja und Saham." },
      { number: 20, text: "Und nach ihr nahm er Maacha, die Tochter Absaloms. Und sie gebar ihm Abija* und Attai und Sisa und Schelomit.", footnotes: ["℘ Kap. 13,1.2; 1Kö 15,1.2"] },
      { number: 21, text: "Und Rehabeam liebte Maacha, die Tochter Absaloms, mehr als alle seine Frauen und seine Nebenfrauen. Denn er hatte achtzehn Frauen genommen und sechzig Nebenfrauen*; und er zeugte achtundzwanzig Söhne und sechzig Töchter.", footnotes: ["℘ 5Mo 17,17"] },
      { number: 22, text: "Und Rehabeam setzte Abija, den Sohn der Maacha, als Oberhaupt*, als Fürsten unter seinen Brüdern ein; denn er dachte daran, ihn zum König zu machen.", footnotes: ["℘ 5Mo 21,15-17"] },
      { number: 23, text: "Und er handelte verständig und verteilte alle seine Söhne in alle Landschaften Judas und Benjamins, in alle befestigten Städte und gab ihnen Nahrung in Fülle* und suchte eine Menge Frauen für sie aus*.", footnotes: ["℘ Kap. 21,3", "Andere üs.: aber er befragte die Menge der Götter seiner Frauen"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Und es geschah, als die Königsherrschaft Rehabeams gefestigt und er stark geworden war*, verließ er das Gesetz des HERRN* und ganz Israel mit ihm*.", heading: "Einfall der Ägypter — Rehabeams Tod", footnotes: ["℘ 1Kö 14,21-31", "℘ Kap. 11,17", "℘ Kap. 26,16", "℘ 5Mo 32,15; Jes 1,4"] },
      { number: 2, text: "Und es geschah im fünften Jahr des Königs Rehabeam, da zog Schischak, der König von Ägypten, gegen Jerusalem herauf — denn sie hatten treulos gegen den HERRN gehandelt* —", footnotes: ["℘ Kap. 24,18; Ri 2,13-15; Jes 63,10"] },
      { number: 3, text: "mit 1 200 Streitwagen und mit 60 000 Pferden, und das Volk, das mit ihm aus Ägypten kam, war nicht zu zählen*: Libyer, Sukkijiter und Kuschiter*.", footnotes: ["℘ Kap. 14,8", "℘ Kap. 16,8; Hes 30,5"] },
      { number: 4, text: "Und er nahm die befestigten Städte ein*, die Juda gehörten, und kam bis vor Jerusalem.", footnotes: ["℘ Kap. 11,5-10"] },
      { number: 5, text: "Da kam der Prophet Schemaja* zu Rehabeam und zu den Obersten von Juda, die sich vor Schischak nach Jerusalem zurückgezogen hatten, und sagte zu ihnen: So spricht der HERR: Ihr habt mich verlassen, darum habe auch ich euch verlassen und euch in die Hand Schischaks gegeben*.", footnotes: ["℘ Kap. 11,2; 1Kö 12,22", "℘ Kap. 15,2; 24,20; 1Chr 28,9; Jer 2,19"] },
      { number: 6, text: "Und die Obersten von Israel* und der König demütigten sich* und sagten: Der HERR ist gerecht!*", footnotes: ["Gemeint ist hier Israel im weiteren Sinne; vgl. Kap. 21,2; 28,19.", "℘ 3Mo 26,41", "℘ 2Mo 9,27; Ps 62,13"] },
      { number: 7, text: "Als aber der HERR sah, dass sie sich gedemütigt hatten, geschah das Wort des HERRN zu Schemaja: Sie haben sich gedemütigt. Ich will sie nicht vernichten und will ihnen bald* Rettung geben, und mein Zorn soll sich nicht durch Schischak über Jerusalem ergießen*.", footnotes: ["o. ein wenig", "℘ Kap. 32,26; 33,12.13; 1Kö 21,29"] },
      { number: 8, text: "Doch sollen sie ihm zu Knechten sein*, damit sie meinen Dienst und den Dienst der Königreiche der Länder *unterscheiden lernen*.", footnotes: ["℘ Ps 106,42", "w. erkennen", "w. erkennen\n℘ 5Mo 28,47.48; Jes 26,13"] },
      { number: 9, text: "Und Schischak, der König von Ägypten, zog gegen Jerusalem herauf. Und er nahm die Schätze des Hauses des HERRN weg und die Schätze des Hauses des Königs, alles nahm er weg. Und er nahm die goldenen Schilde weg, die Salomo gemacht hatte*.", footnotes: ["℘ Kap. 9,15.16"] },
      { number: 10, text: "Und der König Rehabeam machte an ihrer Stelle bronzene Schilde, und er vertraute sie der Hand der Obersten der Leibwächter an, die den Eingang des Hauses des Königs bewachten." },
      { number: 11, text: "Und es geschah, sooft der König in das Haus des HERRN hineinging, kamen die Leibwächter und trugen die Schilde* und brachten sie dann wieder in das Wachtzimmer der Leibwächter zurück.", footnotes: ["w. sie"] },
      { number: 12, text: "Weil er sich also gedemütigt hatte, wandte sich der Zorn des HERRN von ihm ab, so dass er ihn nicht völlig vernichtete. Es war ja auch in Juda noch etwas Gutes*.", footnotes: ["℘ Kap. 19,3; 1Kö 14,13"] },
      { number: 13, text: "Und der König Rehabeam erstarkte in Jerusalem und regierte weiter. Denn Rehabeam war 41 Jahre alt, als er König wurde, und regierte siebzehn Jahre in Jerusalem, der Stadt, die der HERR aus allen Stämmen Israels erwählt hatte, um seinen Namen dort niederzulegen*. Und der Name seiner Mutter war Naama, die Ammoniterin.", footnotes: ["℘ Kap. 6,6.20; 1Kö 11,36"] },
      { number: 14, text: "Aber er tat, was böse war; denn er richtete sein Herz nicht darauf, den HERRN zu suchen." },
      { number: 15, text: "Und die Geschichte* Rehabeams, die frühere und die spätere*, ist sie nicht geschrieben in der Geschichte des Propheten Schemaja* und des Sehers Iddo?* Dies gilt auch für das Geschlechtsregister*. Und die Kriege zwischen Rehabeam und Jerobeam dauerten die ganze Zeit an*.", footnotes: ["w. die Begebenheiten", "℘ Kap. 16,11; 20,34; 28,26; 35,27; 1Chr 29,29", "℘ Kap. 11,2; 1Kö 12,22", "℘ Kap. 9,29", "o. des Sehers Iddo nach Art der Geschlechtsregister", "w. dauerten alle Tage an\n℘ Kap. 13,1.2"] },
      { number: 16, text: "Und Rehabeam legte sich zu seinen Vätern, und er wurde begraben in der Stadt Davids. Und sein Sohn Abija wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 13,1.2"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "*Im achtzehnten Jahr des Königs Jerobeam wurde Abija König über Juda*.", heading: "Abija von Juda — Sieg über Israel", footnotes: ["℘ 1Kö 15,1-8", "℘ Kap. 12,15.16"] },
      { number: 2, text: "Er regierte drei Jahre in Jerusalem. Und der Name seiner Mutter war Michaja, die Tochter Uriëls von Gibea*. Und es war Krieg zwischen Abija und Jerobeam*.", footnotes: ["℘ Kap. 11,20", "℘ Kap. 12,15.16"] },
      { number: 3, text: "Und Abija begann den Krieg mit einem Heer von tapferen Kriegern, 400 000 auserlesenen Männern. Und Jerobeam stellte sich gegen ihn in Schlachtordnung auf mit 800 000 auserlesenen Männern, tapferen Helden. —" },
      { number: 4, text: "Da stellte sich Abija oben auf den Berg Zemarajim*, der im Gebirge Ephraim liegt, und sprach: Hört mich an, Jerobeam und ganz Israel!", footnotes: ["℘ Jos 18,22"] },
      { number: 5, text: "Solltet ihr nicht erkannt haben, dass der HERR, der Gott Israels, das Königtum über Israel für ewig dem David gegeben hat, ihm und seinen Söhnen*, durch einen Salzbund?*", footnotes: ["℘ Kap. 6,16", "℘ 4Mo 18,19"] },
      { number: 6, text: "Aber Jerobeam, der Sohn Nebats, der Knecht Salomos, des Sohnes Davids, erhob sich und empörte sich gegen seinen Herrn*.", footnotes: ["℘ 1Kö 11,26"] },
      { number: 7, text: "Und es versammelten sich zu ihm ehrlose Männer*, Söhne der Bosheit*, und machten sich stark gegen Rehabeam, den Sohn Salomos*. Rehabeam aber war noch jung und zaghaft* und konnte ihnen nicht standhalten.", footnotes: ["℘ Ri 9,4", "o. des Verderbens; o. der Nichtsnutzigkeit", "o. waren Rehabeam . . . überlegen", "w. ein junger Mann und weichen Herzens"] },
      { number: 8, text: "Und nun denkt ihr, standhalten zu können dem Königtum des HERRN* in der Hand der Söhne Davids, weil ihr eine große Menge seid* und die goldenen Kälber bei euch sind, die Jerobeam euch zu Göttern gemacht hat*!", footnotes: ["℘ Kap. 9,8", "℘ Ps 33,16", "℘ 1Kö 12,28.29; Hos 8,5.6"] },
      { number: 9, text: "Habt ihr nicht die Priester des HERRN, die Söhne Aarons, und die Leviten verstoßen und euch Priester gemacht wie die Völker der andern Länder*? Wer immer mit einem Jungstier und sieben Widdern kam, um sich zum Priester weihen zu lassen*, der wurde Priester der Nicht-Götter*.", footnotes: ["℘ Kap. 11,14.15", "w. um seine Hand zu füllen", "℘ Gal 4,8"] },
      { number: 10, text: "Wir aber sind gewiss: Der HERR ist unser Gott*, und wir haben ihn nicht verlassen. Und als Priester dienen dem HERRN Söhne Aarons und die Leviten im Dienst des HERRN*.", footnotes: ["℘ Jos 24,17", "℘ Neh 13,30"] },
      { number: 11, text: "Und sie bringen dem HERRN jeden Morgen und jeden Abend Brandopfer und wohlriechendes Räucherwerk dar*. Und wir haben das Schichtbrot auf dem reinen Tisch* und den goldenen Leuchter und seine Lampen, um sie Abend für Abend* anzuzünden. Denn wir versehen den Dienst des HERRN, unseres Gottes*; ihr aber habt ihn verlassen.", footnotes: ["℘ Kap. 2,3", "℘ Kap. 12,15.16", "℘ Kap. 4,20; 3Mo 24,2-8", "℘ 4Mo 1,53"] },
      { number: 12, text: "Siehe, Gott ist mit uns*, an unserer Spitze. Bei uns sind seine Priester und die Lärmtrompeten, um Lärm zu blasen* gegen euch. Söhne Israel, kämpft nicht gegen den HERRN, den Gott eurer Väter*! Denn es wird euch nicht gelingen.", footnotes: ["℘ Kap. 32,8; Jes 8,10", "℘ 4Mo 10,9", "℘ Hi 9,4; Apg 5,39"] },
      { number: 13, text: "Aber Jerobeam ließ Leute im Hinterhalt eine Umgehung machen, um ihnen in den Rücken zu kommen, so dass sie vor Juda waren und der Hinterhalt hinter Juda*.", footnotes: ["w. hinter ihnen"] },
      { number: 14, text: "Und als Juda sich umwandte, siehe, da hatten sie den Kampf vorn und hinten*. Da schrien sie zu dem HERRN*, und die Priester bliesen mit den Trompeten*,", footnotes: ["℘ 2Sam 10,9", "℘ Kap. 18,31; 32,20; 1Chr 5,20", "℘ 4Mo 10,9"] },
      { number: 15, text: "und die Männer von Juda erhoben ein Kriegsgeschrei*. Und es geschah, als die Männer von Juda das Kriegsgeschrei erhoben, da schlug Gott Jerobeam und ganz Israel vor Abija und Juda*.", footnotes: ["℘ Jos 6,20", "℘ Kap. 14,12; 20,22"] },
      { number: 16, text: "Und die Söhne Israel flohen vor Juda, und Gott gab sie in ihre Hand*.", footnotes: ["℘ Jos 21,44"] },
      { number: 17, text: "Und Abija und sein Volk brachten ihnen eine große Niederlage bei*, und es blieben von Israel 500 000 auserlesene Männer erschlagen liegen.", footnotes: ["w. schlugen unter ihnen einen großen Schlag"] },
      { number: 18, text: "So wurden die Söhne Israel zu dieser Zeit gedemütigt. Aber die Söhne Juda wurden stark, weil sie sich auf den HERRN, den Gott ihrer Väter, gestützt hatten*.", footnotes: ["℘ Kap. 14,10; 16,8; 1Chr 5,20; Ps 25,2.3; Nah 1,7"] },
      { number: 19, text: "Und Abija jagte Jerobeam nach, und er nahm ihm Städte ab: Bethel* und seine Tochterstädte und Jeschana und seine Tochterstädte und Efron und seine Tochterstädte*.", footnotes: ["℘ 1Mo 28,19", "℘ Kap. 15,8; 17,2"] },
      { number: 20, text: "Und Jerobeam behielt keine Macht mehr in den Tagen Abijas. Und der HERR schlug ihn, und er starb*.", footnotes: ["℘ 1Sam 25,38; 1Kö 14,20"] },
      { number: 21, text: "Abija aber erstarkte. Und er nahm vierzehn Frauen und zeugte zweiundzwanzig Söhne und sechzehn Töchter." },
      { number: 22, text: "Und die übrige Geschichte* Abijas und seine Wege und seine Reden sind geschrieben in der Schrift* des Propheten Iddo*.", footnotes: ["w. der Rest der Begebenheiten", "o. Erforschung; o. Auslegung", "℘ Kap. 9,29"] },
      { number: 23, text: "Und Abija legte sich zu seinen Vätern, und man begrub ihn in der Stadt Davids. Und sein Sohn Asa wurde an seiner Stelle König. In seinen Tagen hatte das Land zehn Jahre Ruhe*.", footnotes: ["℘ Kap. 14,4-6; 15,15"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Und Asa tat, was gut und recht war in den Augen des HERRN, seines Gottes*.", heading: "Asa von Juda — Abschaffung des Götzendienstes — Sieg über die Kuschiter", footnotes: ["℘ V. 1-5: 1Kö 15,11.12", "℘ Kap. 21,12; 31,20"] },
      { number: 2, text: "Und er beseitigte die fremden Altäre und die Höhen und zerschlug die Gedenksteine* und hieb die Ascherim um*.", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "℘ Kap. 17,6; 31,1; 34,7; 2Mo 23,24; 5Mo 12,3"] },
      { number: 3, text: "Und er sagte zu Juda, dass sie den HERRN, den Gott ihrer Väter, suchen und das Gesetz und das Gebot tun sollten*.", footnotes: ["℘ Kap. 33,16; 1Mo 18,19"] },
      { number: 4, text: "Und er beseitigte aus allen Städten Judas die Höhen und die Räucheraltäre. Und das Königreich hatte Ruhe unter ihm." },
      { number: 5, text: "Und er baute befestigte Städte in Juda*. Denn das Land hatte Ruhe, und es war kein Krieg gegen ihn in jenen Jahren, denn der HERR hatte ihm Ruhe verschafft*.", footnotes: ["℘ Kap. 11,5", "℘ Kap. 13,23; Jos 23,1"] },
      { number: 6, text: "Und er sagte zu Juda: Lasst uns diese Städte ausbauen und mit Mauern umgeben und Türmen, Toren und Riegeln. Noch liegt das Land frei vor uns, denn wir haben den HERRN, unseren Gott, gesucht*. Wir haben ihn gesucht, und er hat uns Ruhe verschafft ringsumher. Und so bauten sie, und es gelang ihnen*.", footnotes: ["℘ Kap. 17,4; 26,5; 31,21; 34,3", "℘ 1Chr 22,13"] },
      { number: 7, text: "Und Asa hatte ein Heer, das Langschild und Spieß trug: Aus Juda 300 000 und aus Benjamin 280 000 Mann, die Kleinschilde trugen und den Bogen spannten. Alle waren tapfere Helden*.", footnotes: ["℘ Kap. 17,13-19; 25,5; 26,13"] },
      { number: 8, text: "*Und der Kuschite Serach zog gegen sie aus mit einem Heer von tausend mal tausend Mann und dreihundert Wagen*; und er kam bis Marescha*.", footnotes: ["℘ V. 8-14: vgl. Kap. 20,1-30", "℘ Kap. 12,2.3; 16,8", "℘ Kap. 11,8"] },
      { number: 9, text: "Und Asa zog ihm entgegen; und sie stellten sich in Schlachtordnung auf im Tal Zefata bei Marescha." },
      { number: 10, text: "Und Asa rief den HERRN, seinen Gott, an* und sagte: HERR, außer dir ist keiner, der helfen könnte im Kampf zwischen einem Mächtigen und einem Kraftlosen*. Hilf uns, HERR, unser Gott! Denn wir stützen uns auf dich*, und in deinem Namen sind wir gegen diese Menge gezogen*. Du bist der HERR, unser Gott! Kein Mensch kann etwas gegen dich ausrichten*.", footnotes: ["℘ Kap. 32,20; Ps 31,15", "℘ 1Sam 14,6", "℘ Kap. 13,18; Ps 20,8", "℘ Kap. 32,8; 1Sam 17,45", "℘ 5Mo 20,1; Ps 9,20"] },
      { number: 11, text: "Und der HERR schlug die Kuschiter vor Asa und vor Juda*, so dass die Kuschiter flohen*.", footnotes: ["℘ Kap. 26,7", "℘ Kap. 13,15; Ps 22,6"] },
      { number: 12, text: "Und Asa und das Volk, das bei ihm war, jagten ihnen nach bis Gerar*. Und es fielen von den Kuschitern so viele, dass sie sich nicht wieder erholen konnten; denn sie wurden zerschmettert vor dem HERRN und vor seinem Heer*. Und sie trugen sehr viel Beute davon*.", footnotes: ["℘ 1Mo 10,19", "℘ 2Mo 12,41", "℘ Kap. 15,11; 1Chr 5,21"] },
      { number: 13, text: "Auch schlugen sie alle Städte rings um Gerar, denn der Schrecken des HERRN war auf sie gekommen*. Und sie plünderten alle Städte, denn es gab viel Plündergut darin.", footnotes: ["℘ Kap. 17,10; 1Mo 35,5"] },
      { number: 14, text: "Und auch die Zeltlager bei den Herden schlugen sie und führten Schafe in Menge weg und Kamele. Und sie kehrten nach Jerusalem zurück*.", footnotes: ["℘ 1Kö 15,23"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und auf Asarja, den Sohn Odeds, kam der Geist Gottes*.", heading: "Erneuerung des Bundes mit Gott", footnotes: ["℘ Kap. 20,14; 24,20; 4Mo 24,2; Ri 3,10"] },
      { number: 2, text: "Und er ging hinaus, Asa entgegen, und sagte zu ihm: Hört mich an, Asa und ganz Juda und Benjamin*! Der HERR ist mit euch, wenn ihr mit ihm seid*. Und wenn ihr ihn sucht, wird er sich von euch finden lassen*. Wenn ihr ihn aber verlasst, wird er euch auch verlassen*.", footnotes: ["℘ Kap. 11,12", "℘ Am 5,14; Jak 4,8", "℘ V. 15; Kap. 33,12.13; 5Mo 4,29; Jes 51,1; 55,7; Sach 1,3", "℘ Kap. 12,5; 4Mo 14,42.43; Jos 24,20; Ri 10,13; 1Sam 12,14.15.25; Jer 2,17"] },
      { number: 3, text: "Und Israel war lange Zeit* ohne den wahren Gott* und ohne belehrenden Priester* und ohne Gesetz*.", footnotes: ["w. viele Tage", "w. Gott der Wahrheit, o. Gott der Treue", "℘ 3Mo 10,11", "℘ Kap. 17,7; Kla 2,9"] },
      { number: 4, text: "Aber in ihrer Bedrängnis kehrten sie um zu dem HERRN, dem Gott Israels; und sie suchten ihn, und er ließ sich von ihnen finden*.", footnotes: ["℘ V. 15; Kap. 33,12.13; 5Mo 4,29; Jes 51,1; 55,7; Sach 1,3"] },
      { number: 5, text: "In jenen Zeiten gab es keine Sicherheit* für den, der hinaus-, und für den der hineinging*; sondern viele Beunruhigungen* kamen über alle Bewohner der Länder*.", footnotes: ["w. keinen Frieden", "℘ 5Mo 28,19", "o. große Wirren", "℘ Ri 5,6; Sach 8,10"] },
      { number: 6, text: "Und es stieß sich Nation an Nation und Stadt an Stadt*; denn Gott beunruhigte* sie durch allerlei Bedrängnis.", footnotes: ["℘ Jes 19,2; Hag 2,22", "o. verwirrte"] },
      { number: 7, text: "Ihr aber, seid stark und lasst eure Hände nicht schlaff werden!* Denn es gibt einen Lohn für euer Tun!*", footnotes: ["℘ Kap. 19,11; 32,7; Jos 1,6-9; Sach 8,9", "℘ Jos 14,14; Jer 31,16; 1Kor 15,58"] },
      { number: 8, text: "*Als aber Asa diese Worte und die Weissagung des Propheten Oded hörte, fasste er Mut. Und er schaffte die Scheusale weg aus dem ganzen Land Juda und Benjamin und aus den Städten, die er auf dem Gebirge Ephraim eingenommen hatte*, und er erneuerte den Altar des HERRN, der vor der Vorhalle des HERRN stand*.", footnotes: ["℘ V. 8-19: 1Kö 15,9-15", "℘ Kap. 13,19; Ri 10,16", "℘ Kap. 4,1"] },
      { number: 9, text: "Und er versammelte ganz Juda und Benjamin und die Fremden, die aus Ephraim und Manasse und aus Simeon bei ihnen wohnten. Denn in Menge waren sie aus Israel zu ihm übergelaufen*, als sie sahen, dass der HERR, sein Gott, mit ihm war*.", footnotes: ["℘ Kap. 11,16", "℘ 1Mo 26,28; Sach 8,23"] },
      { number: 10, text: "Und sie versammelten sich in Jerusalem im dritten Monat, im fünfzehnten Jahr der Regierung* Asas.", footnotes: ["w. Königsherrschaft"] },
      { number: 11, text: "Und sie opferten dem HERRN an jenem Tag von der Beute, die sie heimgebracht hatten*, 700 Rinder und 7 000 Schafe.", footnotes: ["℘ Kap. 14,12-14; 4Mo 31,28"] },
      { number: 12, text: "Und sie traten in den Bund*, den HERRN, den Gott ihrer Väter, zu suchen* mit ihrem ganzen Herzen und mit ihrer ganzen Seele*.", footnotes: ["℘ Kap. 29,10; 5Mo 29,11", "℘ Kap. 11,16; 19,3.4; 23,16; 34,31.32; Jos 24,25; 2Kö 23,3", "℘ 5Mo 10,12"] },
      { number: 13, text: "Jeder aber, der den HERRN, den Gott Israels*, nicht suchen würde, sollte getötet werden, vom Kleinsten bis zum Größten, vom Mann bis zur Frau.", footnotes: ["℘ 2Mo 22,19; Zef 1,6"] },
      { number: 14, text: "Und sie schworen dem HERRN mit lauter Stimme und mit Jauchzen und unter Trompeten- und Hörnerschall." },
      { number: 15, text: "Und ganz Juda freute sich über den Schwur. Denn sie schworen mit ihrem ganzen Herzen und suchten den HERRN* mit ihrem ganzen Willen*; und er ließ sich von ihnen finden*. Und der HERR schaffte ihnen Ruhe ringsumher*.", footnotes: ["w. suchten ihn\n℘ Kap. 11,16; 19,3.4; 23,16; 34,31.32; Jos 24,25; 2Kö 23,3", "℘ 2Mo 24,3.7; Ps 119,10", "℘ V. 2.4; 1Chr 16,10", "℘ Kap. 13,23; 20,30"] },
      { number: 16, text: "Und auch Maacha, die Mutter des Königs Asa, entfernte er aus ihrer Stellung als Gebieterin, weil sie der Aschera ein Schandbild gemacht hatte. Und Asa rottete ihr Schandbild aus und zermalmte und verbrannte es im Tal Kidron*.", footnotes: ["℘ Kap. 29,16; 30,14; 2Kö 23,6"] },
      { number: 17, text: "Die Höhen aber wichen nicht aus Israel*; doch war das Herz Asas ungeteilt all seine Tage*.", footnotes: ["℘ Kap. 28,4; 33,17; 1Kö 3,2", "℘ Kap. 20,32.33"] },
      { number: 18, text: "Und er brachte die heiligen Gaben* seines Vaters und seine heiligen Gaben* in das Haus Gottes: Silber und Gold und Geräte.", footnotes: ["o. heiligen Dinge", "o. heiligen Dinge"] },
      { number: 19, text: "Und es war kein Krieg bis zum 35. Jahr der Regierung* Asas*.", footnotes: ["w. Königsherrschaft", "℘ Kap. 16,9"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "*Im 36. Jahr der Regierung* Asas zog Bascha, der König von Israel, gegen Juda herauf und baute Rama* aus, um bei Asa, dem König von Juda, niemanden hinaus- und hineingehen zu lassen.", heading: "Asas Bund mit Aram gegen Israel — Seine Krankheit und sein Tod", footnotes: ["℘ 1Kö 15,16-24", "w. Königsherrschaft", "℘ Jer 40,1"] },
      { number: 2, text: "Da nahm Asa Silber und Gold aus den Schätzen des Hauses des HERRN und des Hauses des Königs*. Und er sandte zu Ben-Hadad, dem König von Aram*, der in Damaskus wohnte, und ließ ihm sagen:", footnotes: ["℘ Kap. 28,21", "℘ 2Kö 12,18"] },
      { number: 3, text: "Ein Bund sei zwischen mir und dir und zwischen meinem Vater und deinem Vater! Siehe, ich sende dir Silber und Gold. Auf, mach deinen Bund mit Bascha, dem König von Israel, ungültig, dass er von mir abzieht!" },
      { number: 4, text: "Und Ben-Hadad hörte auf den König Asa*, und er sandte seine Heerobersten gegen die Städte Israels. Und sie schlugen Ijon und Dan und Abel-Majim und alle Vorratsplätze der Städte Naftalis.", footnotes: ["℘ 2Kö 16,9"] },
      { number: 5, text: "Und es geschah, als Bascha das hörte, da ließ er davon ab, Rama auszubauen, und stellte seine Arbeit ein." },
      { number: 6, text: "Der König Asa aber holte* ganz Juda, und sie trugen die Steine und das Bauholz Ramas weg, mit denen Bascha gebaut hatte; und er baute damit Geba und Mizpa aus.", footnotes: ["w. nahm"] },
      { number: 7, text: "Zu jener Zeit kam der Seher Hanani* zu Asa, dem König von Juda, und sagte zu ihm: Weil du dich auf den König von Aram gestützt hast und dich nicht auf den HERRN, deinen Gott, gestützt hast, darum ist das Heer des Königs von Aram deiner Hand entronnen*.", footnotes: ["℘ Kap. 19,2; 20,34; 1Kö 16,1.7", "℘ Ps 146,3"] },
      { number: 8, text: "Waren nicht die Kuschiter und die Libyer eine gewaltige Heeresmacht mit Wagen und Reitern in großer Menge? Doch weil du dich auf den HERRN stütztest, gab er sie in deine Hand*.", footnotes: ["℘ Kap. 12,3; 13,18; 14,8"] },
      { number: 9, text: "Denn des HERRN Augen durchlaufen die ganze Erde*, um denen treu beizustehen*, deren Herz ungeteilt auf ihn gerichtet ist*. Hierin hast du töricht gehandelt*. Darum wirst du von nun an Kriege haben*.", footnotes: ["℘ Hi 28,24; 34,21; Ps 33,14; Spr 15,3; Jer 32,19; Sach 4,10", "o. um fest zu denen zu halten", "℘ Kap. 19,9; Esr 5,5; Ps 33,18", "℘ 1Mo 31,28", "℘ Kap. 15,19; Jes 31,1"] },
      { number: 10, text: "Und Asa wurde ärgerlich über den Seher und legte ihn ins Gefängnis in den Block*; denn er war deshalb wütend auf ihn. Auch tat Asa zu dieser Zeit einigen von dem Volk Gewalt an.", footnotes: ["w. in das Haus des Blocks\n℘ Kap. 18,26; 25,16; 26,19; 1Kö 13,4; Mt 14,3"] },
      { number: 11, text: "Und siehe, die Geschichte* Asas, die frühere und die spätere*, siehe, sie ist geschrieben in dem Buch der Könige von Juda und Israel.", footnotes: ["w. die Begebenheiten", "℘ Kap. 12,15"] },
      { number: 12, text: "Und im 39. Jahr seiner Regierung erkrankte Asa an seinen Füßen. Seine Krankheit war überaus schwer; aber auch in seiner Krankheit suchte er nicht den HERRN, sondern die Ärzte*.", footnotes: ["℘ 1Chr 10,14"] },
      { number: 13, text: "Und Asa legte sich zu seinen Vätern; und er starb im 41. Jahr seiner Regierung." },
      { number: 14, text: "Und man begrub ihn in seinem Grab, das er sich in der Stadt Davids hatte aushauen lassen. Und man legte ihn auf ein Lager, das man angefüllt hatte mit Balsamöl und verschiedenen Arten von Salben, gemischt nach der Kunst* der Salbenmischung*; und man veranstaltete für ihn einen sehr großen Brand*.", footnotes: ["o. nach dem Werk", "℘ 1Mo 50,2; Mk 16,1; Joh 19,40", "℘ Kap. 21,19; 32,33; Jer 34,5"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und sein Sohn Joschafat wurde an seiner Stelle König*. Und er erwies sich stark gegenüber Israel.", heading: "Joschafat von Juda — Fürsorge für sein Volk — Seine erfolgreiche Regierung", footnotes: ["℘ 1Kö 15,24; 2Kö 1,17"] },
      { number: 2, text: "Er legte Streitkräfte in alle befestigten Städte Judas und legte Besatzungen in das Land Juda und in die Städte Ephraims, die sein Vater Asa eingenommen hatte*.", footnotes: ["℘ V. 19; Kap. 13,19"] },
      { number: 3, text: "Und der HERR war mit Joschafat*. Denn er ging auf den früheren Wegen seines Vaters David* und suchte nicht die Baalim,", footnotes: ["℘ 1Sam 18,14", "℘ Kap. 21,12; 22,9; 27,6; 29,2; 34,2; 1Kö 3,3"] },
      { number: 4, text: "sondern er suchte den Gott seines Vaters und lebte* in seinen Geboten* und nicht so, wie es Israel machte*.", footnotes: ["w. ging", "℘ Kap. 21,12; 22,9; 27,6; 29,2; 34,2; 1Kö 3,3", "℘ Kap. 14,6; 1Kö 9,4; 12,28-30"] },
      { number: 5, text: "Und der HERR befestigte das Königtum in seiner Hand*. Und ganz Juda gab Joschafat Geschenke*, und er hatte Reichtum und Ehre in Fülle*.", footnotes: ["℘ Spr 16,12", "℘ 1Sam 10,27", "℘ Kap. 18,1; 32,23.27.29"] },
      { number: 6, text: "Und sein Herz gewann Mut auf den Wegen des HERRN, und er beseitigte wieder die Höhen und die Ascherim aus Juda*. —", footnotes: ["℘ Kap. 14,2; 19,3"] },
      { number: 7, text: "Und im dritten Jahr seiner Regierung sandte er seine Obersten Ben-Hajil und Obadja und Secharja und Netanel und Michaja, dass sie in den Städten Judas lehren sollten*,", footnotes: ["℘ Kap. 15,3; Esr 7,25"] },
      { number: 8, text: "und mit ihnen die Leviten Schemaja und Netanja und Sebadja und Asaël und Schemiramot und Jonatan und Adonija und Tobija und Tob-Adonija, die Leviten, und mit ihnen die Priester Elischama und Joram." },
      { number: 9, text: "Und sie lehrten in Juda, und sie hatten das Buch des Gesetzes des HERRN bei sich und zogen in allen Städten Judas umher und lehrten das Volk*.", footnotes: ["℘ Kap. 35,3; Neh 8,7.8.13; Mal 2,7"] },
      { number: 10, text: "Und der Schrecken des HERRN kam über alle Königreiche der Länder, die rings um Juda herum waren, so dass sie nicht gegen Joschafat kämpften*.", footnotes: ["℘ Kap. 14,13; Mi 7,17"] },
      { number: 11, text: "Und von den Philistern brachte man Joschafat Tribut* und Silber als Abgabe*. Auch die Araber brachten ihm Kleinvieh: 7 700 Widder und 7 700 Ziegenböcke. —", footnotes: ["℘ Kap. 9,24; 26,8; 1Kö 5,1; Hes 27,21", "w. als Last"] },
      { number: 12, text: "Und Joschafat wurde immer größer, bis er überaus groß war. Und er baute in Juda Burgen und Vorratsstädte*.", footnotes: ["℘ Kap. 8,4.6; 11,5.11; 27,4"] },
      { number: 13, text: "Und er hatte große Vorräte* in den Städten Judas und Kriegsleute, kriegstüchtige* Männer, in Jerusalem*.", footnotes: ["o. gewaltige Arbeiten", "o. vermögende; o. angesehene", "℘ Kap. 26,10-15"] },
      { number: 14, text: "Und das war ihr Dienst nach ihren Sippen: Für Juda waren Oberste über Tausend: Adna, der Oberste, und mit ihm 300 000 kriegstüchtige* Männer,", footnotes: ["o. vermögende; o. angesehene"] },
      { number: 15, text: "und neben ihm Johanan, der Oberste, und mit ihm 280 000," },
      { number: 16, text: "und neben ihm Amasja, der Sohn Sichris, der sich freiwillig für den HERRN gestellt hatte, und mit ihm 200 000 kriegstüchtige* Männer*;", footnotes: ["o. vermögende; o. angesehene", "℘ Ri 5,2.9"] },
      { number: 17, text: "und von Benjamin: Eljada, ein kriegstüchtiger Mann, und mit ihm 200 000 Männer, mit Bogen und Schild ausgerüstet*,", footnotes: ["℘ Kap. 14,7"] },
      { number: 18, text: "und neben ihm Josabad und mit ihm 180 000 zum Heer gerüstete Männer*.", footnotes: ["℘ 1Chr 7,11"] },
      { number: 19, text: "Diese waren es, die dem König dienten außer denen, die der König in die befestigten Städte von ganz Juda gelegt hatte*.", footnotes: ["℘ V. 2; Kap. 33,14"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "*So hatte Joschafat Reichtum und Ehre in Fülle*. Und er verschwägerte sich mit Ahab*.", heading: "Joschafats Bündnis mit Ahab — Gemeinsamer Krieg gegen die Aramäer — Joschafats Rettung und Ahabs Tod — Strafrede gegen Joschafat", footnotes: ["℘ 1Kö 22,1-40", "℘ Kap. 17,5", "℘ Kap. 20,35; 21,6; 1Kö 22,45; 2Kor 6,14"] },
      { number: 2, text: "Und nach Verlauf von einigen Jahren zog er zu Ahab nach Samaria hinab. Und Ahab schlachtete für ihn und für das Volk, das bei ihm war, Schafe und Rinder in Menge. Und er verleitete ihn, gegen Ramot in Gilead hinaufzuziehen." },
      { number: 3, text: "Und Ahab, der König von Israel, sagte zu Joschafat, dem König von Juda: Willst du mit mir nach Ramot in Gilead ziehen? Und er sprach zu ihm: Ich bin wie du, und mein Volk ist wie dein Volk. Ich ziehe mit dir in den Kampf*.", footnotes: ["℘ Kap. 19,2"] },
      { number: 4, text: "Und Joschafat sagte zum König von Israel: Befrage doch heute* das Wort des HERRN!", footnotes: ["o. zuerst"] },
      { number: 5, text: "Da versammelte der König von Israel die Propheten, vierhundert Mann, und er sagte zu ihnen: Sollen wir gegen Ramot in Gilead in den Kampf ziehen, oder soll ich es lassen? Sie sagten: Zieh hinauf, und Gott wird es in die Hand des Königs geben*!", footnotes: ["℘ Jer 23,16.17"] },
      { number: 6, text: "Aber Joschafat sagte: Ist hier kein Prophet des HERRN mehr, dass wir durch ihn den HERRN befragen?*", footnotes: ["℘ 2Kö 3,11"] },
      { number: 7, text: "Da sagte der König von Israel zu Joschafat: Einen Mann gibt es noch, durch den man den HERRN befragen könnte, aber ich hasse ihn, denn er weissagt nichts Gutes über mich, sondern immer nur Böses. Es ist Micha, der Sohn des Jimla. Joschafat aber sagte: Der König spreche nicht so! —" },
      { number: 8, text: "Da rief der König von Israel einen Hofbeamten* und sagte: Hol schnell Micha, den Sohn des Jimla!", footnotes: ["w. einen Eunuchen"] },
      { number: 9, text: "Und der König von Israel und Joschafat, der König von Juda, saßen jeder auf seinem Thron, bekleidet mit königlichen Gewändern, und sie saßen auf einem freien Platz am Toreingang von Samaria. Und alle Propheten weissagten vor ihnen." },
      { number: 10, text: "Und Zedekia, der Sohn des Kenaana, machte sich eiserne Hörner und sagte: So spricht der HERR: Mit denen wirst du die Aramäer niederstoßen, bis du sie vernichtet hast." },
      { number: 11, text: "Ebenso weissagten alle Propheten, indem sie sagten: Zieh hinauf nach Ramot in Gilead und führe Israel zum Sieg! Der HERR wird es in die Hand des Königs geben." },
      { number: 12, text: "Der Bote aber, der hingegangen war, Micha zu rufen, redete zu ihm und sagte: Siehe, die Worte der Propheten sind einstimmig* gut für den König. Lass doch dein Wort sein wie das Wort eines von ihnen und rede Gutes!", footnotes: ["w. mit einem Mund"] },
      { number: 13, text: "Micha aber sagte: So wahr der HERR lebt, nur was mein Gott mir sagen wird, das werde ich reden!" },
      { number: 14, text: "Und als er zum König kam, sagte der König zu ihm: Micha, sollen wir nach Ramot in Gilead in den Kampf ziehen, oder soll ich es lassen? Da sagte er: Zieht hinauf und führt Israel zum Sieg! Und sie werden in eure Hand gegeben werden." },
      { number: 15, text: "Der König aber sagte zu ihm: Wievielmal muss ich dich beschwören, dass du im Namen des HERRN nichts zu mir redest als nur Wahrheit?" },
      { number: 16, text: "Da sagte er: Ich sah ganz Israel auf den Bergen zerstreut wie Schafe, die keinen Hirten haben. Und der HERR sprach: Diese haben keinen Herrn. Sie sollen in Frieden zurückkehren, jeder in sein Haus!" },
      { number: 17, text: "Da sagte der König von Israel zu Joschafat: Habe ich dir nicht gesagt, er weissagt nichts Gutes über mich, sondern nur Böses?" },
      { number: 18, text: "Und Micha* sprach: Darum hört das Wort des HERRN: Ich sah den HERRN auf seinem Thron sitzen und das ganze Heer des Himmels zu seiner Rechten und zu seiner Linken stehen.", footnotes: ["w. er"] },
      { number: 19, text: "Und der HERR sprach: Wer will Ahab, den König von Israel, betören, dass er hinaufzieht und bei Ramot in Gilead fällt? Und der eine sagte dies, und der andere sagte das." },
      { number: 20, text: "Da trat der Geist hervor und stellte sich vor den HERRN und sagte: Ich will ihn betören. Und der HERR sprach zu ihm: Womit?" },
      { number: 21, text: "Da sagte er: Ich will ausgehen und will ein Lügengeist sein im Mund aller seiner Propheten. Und er sprach: Du sollst ihn betören und wirst es auch können. Geh aus und mach es so!*", footnotes: ["℘ 2Thes 2,11.12"] },
      { number: 22, text: "Und nun, siehe, der HERR hat einen Lügengeist in den Mund dieser deiner Propheten gegeben*, denn der HERR hat Unheil über dich geredet.", footnotes: ["℘ Jes 19,14"] },
      { number: 23, text: "Da trat Zedekia, der Sohn des Kenaana, heran und schlug Micha auf die Backe und sagte: Auf welchem Weg ist denn der Geist des HERRN von mir gewichen, um mit dir zu reden?" },
      { number: 24, text: "Micha sagte: Siehe, du wirst es an jenem Tag sehen, wenn du von Zimmer zu Zimmer flüchtest*, um dich zu verstecken.", footnotes: ["w. kommst"] },
      { number: 25, text: "Da sagte der König von Israel: Nehmt Micha und führt ihn zurück zu Amon, dem Obersten der Stadt, und zu Joasch, dem Sohn des Königs," },
      { number: 26, text: "und sagt: So spricht der König: Setzt diesen ins Gefängnis* und speist ihn mit Brot der Bedrängnis und mit Wasser der Bedrängnis*, bis ich in Frieden zurückkomme!", footnotes: ["℘ Kap. 16,10; Jer 36,26", "s. Anm. zu 1Kö 22,27"] },
      { number: 27, text: "Micha aber sagte: Wenn du je in Frieden zurückkehrst, dann hat der HERR nicht durch mich geredet! Und er sprach: Hört es, ihr Völker alle!" },
      { number: 28, text: "Und der König von Israel und Joschafat, der König von Juda, zogen hinauf nach Ramot in Gilead." },
      { number: 29, text: "Und der König von Israel sagte zu Joschafat: Ich will mich verkleiden und in den Kampf ziehen. Du aber lege deine königlichen Kleider an! So verkleidete sich der König von Israel, und sie zogen in den Kampf*.", footnotes: ["℘ Kap. 35,22"] },
      { number: 30, text: "Der König von Aram hatte aber seinen Wagenführern befohlen: Ihr sollt weder gegen einen Geringen noch gegen einen Großen kämpfen, sondern gegen den König von Israel allein!" },
      { number: 31, text: "Und es geschah, als die Wagenführer Joschafat sahen, da sagten sie sich: Das ist der König von Israel! Und sie umringten ihn, um ihn anzugreifen*. Da schrie Joschafat um Hilfe*. Und der HERR half ihm, und Gott lenkte sie von ihm ab*.", footnotes: ["w. um zu kämpfen", "℘ Kap. 13,14", "w. lockte sie von ihm fort\n℘ 1Chr 5,20; Ps 56,10"] },
      { number: 32, text: "Und es geschah, als die Wagenführer sahen, dass nicht er der König von Israel war, da wandten sie sich von ihm ab." },
      { number: 33, text: "Und ein Mann spannte den Bogen aufs Geratewohl* und traf den König von Israel zwischen die Tragbänder des Panzers und den Panzer. Da sagte er zu seinem Wagenlenker: Wende um* und bring mich aus der Schlacht* heraus, denn ich bin schwer verwundet*!", footnotes: ["w. in seiner Arglosigkeit", "w. Wende deine Hände", "so mit LXX und Vulg.; Mas. T.: aus dem Lager", "w. durch eine Verwundung entkräftet\n℘ Kap. 35,23"] },
      { number: 34, text: "Und der Kampf wurde heftig an jenem Tag, und der König von Israel blieb aufrecht stehen in dem Wagen angesichts der Aramäer bis zum Abend. Und er starb zur Zeit des Sonnenuntergangs." },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und Joschafat, der König von Juda, kehrte in Frieden zurück nach Jerusalem in sein Haus." },
      { number: 2, text: "Da ging ihm der Seher Jehu*, der Sohn Hananis, entgegen, und er sagte zu dem König Joschafat: Sollst du so dem Gottlosen helfen* und die lieben, die den HERRN hassen?* Darum ist auf dir Zorn vonseiten des HERRN.", footnotes: ["℘ Kap. 16,7; 20,34", "℘ Kap. 18,3", "℘ Ps 139,21.22"] },
      { number: 3, text: "Jedoch ist etwas Gutes bei dir gefunden worden*. Denn du hast die Ascheren aus dem Land weggeschafft* und dein Herz darauf gerichtet, Gott zu suchen*.", footnotes: ["℘ Kap. 12,12", "℘ Kap. 17,6", "℘ Kap. 11,16; 22,9"] },
      { number: 4, text: "Und Joschafat blieb in Jerusalem. Und er zog wieder unter das Volk hinaus von Beerscheba bis zum Gebirge Ephraim und brachte sie zurück zu dem HERRN, dem Gott ihrer Väter*.", heading: "Joschafats Rechtspflege", footnotes: ["℘ Kap. 15,9-13"] },
      { number: 5, text: "Und er setzte Richter im Land ein, in allen befestigten Städten Judas, Stadt für Stadt*.", footnotes: ["℘ 5Mo 16,18"] },
      { number: 6, text: "Und er sagte zu den Richtern: Seht zu, was ihr tut! Denn nicht im Auftrag von* Menschen richtet ihr, sondern im Auftrag des HERRN*. Und er ist mit euch, wenn ihr Recht sprecht*.", footnotes: ["w. für", "w. für den HERRN", "℘ 5Mo 1,17"] },
      { number: 7, text: "So sei denn der Schrecken des HERRN über euch*. Habt acht, wie ihr handelt!* Denn bei dem HERRN, unserm Gott, ist kein Unrecht*, kein Ansehen der Person* und kein Annehmen von Geschenken*.", footnotes: ["℘ 1Sam 11,7", "℘ Ps 82,2-4", "℘ 1Mo 18,25", "w. kein Aufheben des Gesichts\n℘ Hi 13,10; Apg 10,34; Jak 2,1", "℘ 2Mo 18,21; 5Mo 10,17; Hi 8,3; 34,19"] },
      { number: 8, text: "Auch in Jerusalem bestellte Joschafat Leviten und Priester und Familienoberhäupter* Israels für das Gericht des HERRN *und für die Rechtsstreitigkeiten* der Einwohner von Jerusalem*.", footnotes: ["w. Häupter der Väter", "so in Anlehnung an LXX und die alten lat. Üs.; Mas. T.: für den Rechtsstreit. Und sie kehrten nach Jerusalem zurück", "℘ 1Chr 23,4; Ps 122,5", "so in Anlehnung an LXX und die alten lat. Üs.; Mas. T.: für den Rechtsstreit. Und sie kehrten nach Jerusalem zurück"] },
      { number: 9, text: "Und er befahl ihnen und sagte: So sollt ihr es machen in der Furcht des HERRN, in Treue* und mit ungeteiltem Herzen*.", footnotes: ["℘ 1Kor 4,2", "℘ Kap. 16,9"] },
      { number: 10, text: "Was für ein Rechtsstreit auch immer vor euch kommt vonseiten eurer Brüder, die in ihren Städten wohnen, zwischen Bluttat und Bluttat, zwischen Gesetz und Gebot, Ordnungen und Rechtsbestimmungen, so sollt ihr sie verwarnen*, damit sie nicht an dem HERRN schuldig werden und damit nicht ein Zorn über euch und über eure Brüder kommt*. So sollt ihr es machen, damit ihr nicht schuldig werdet.", footnotes: ["℘ 2Mo 18,16; 5Mo 21,5", "℘ 4Mo 17,11"] },
      { number: 11, text: "Und siehe, Amarja*, der Oberpriester*, steht über euch in allen Sachen des HERRN und Sebadja, der Sohn Ismaels, der Fürst des Hauses Juda, in allen Sachen des Königs*. Und als Verwalter sind die Leviten vor euch*. Seid stark* und handelt, und der HERR wird mit dem Guten sein!*", footnotes: ["℘ 1Chr 5,37", "o. der erste Priester", "℘ 1Chr 26,30", "d. h. stehen euch die Leviten zur Verfügung", "℘ Kap. 15,7", "℘ Jer 6,16"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*Und es geschah danach, da kamen die Söhne Moab und die Söhne Ammon und mit ihnen einige von den Mëunitern* zum Kampf gegen Joschafat.", heading: "Joschafats Sieg über die Übermacht der Ammoniter", footnotes: ["℘ vgl. Kap. 14,8-14", "so mit LXX; Mas. T.: Ammonitern\n℘ Kap. 26,7; 1Chr 4,41"] },
      { number: 2, text: "Und man kam und berichtete Joschafat: Eine große Menge ist gegen dich gekommen von jenseits des Meeres*, von Aram. Und siehe, sie sind schon in Hazezon-Tamar*, das ist En-Gedi*.", footnotes: ["d. h. östl. vom Toten Meer", "℘ 1Mo 14,7; Hes 47,19", "℘ Jos 15,62; Hes 47,10"] },
      { number: 3, text: "Da fürchtete sich Joschafat und richtete sein Angesicht darauf, den HERRN zu suchen*. Und er rief ein Fasten aus in ganz Juda*.", footnotes: ["℘ Kap. 7,14; 11,16; Esr 8,21; Ps 56,4; Am 5,4", "℘ 1Sam 7,6; Jer 36,9; Jon 3,5"] },
      { number: 4, text: "Und Juda versammelte sich, um von dem HERRN Hilfe zu suchen. Sogar aus allen Städten Judas kamen sie, um den HERRN zu suchen*. —", footnotes: ["℘ Kap. 7,14; 11,16; Esr 8,21; Ps 56,4; Am 5,4"] },
      { number: 5, text: "Und Joschafat stand in der Versammlung Judas und Jerusalems im Haus des HERRN vor dem neuen Vorhof." },
      { number: 6, text: "Und er sprach: HERR, Gott unserer Väter, bist du es nicht, der da Gott im Himmel ist*, und bist nicht du Herrscher über alle Königreiche der Nationen?* Und in deiner Hand ist Kraft und Macht*; und niemand kann gegen dich bestehen*.", footnotes: ["o. bist du nicht, der da ist, Gott im Himmel\n℘ Kap. 5,14; 1Kö 8,30.44; Mt 6,9", "℘ Ps 46,11", "℘ 1Chr 29,12", "℘ Hi 9,4; Jes 14,27; Jer 49,19"] },
      { number: 7, text: "Hast du, unser Gott, nicht die Bewohner dieses Landes vor deinem Volk Israel vertrieben* und es den Nachkommen Abrahams, deines Freundes*, gegeben für ewig?*", footnotes: ["℘ Jos 23,9; Ps 44,3", "℘ Jes 41,8; Jak 2,23", "℘ 1Mo 12,7; 5Mo 4,38; Jos 1,6"] },
      { number: 8, text: "Und sie haben darin gewohnt* und haben dir ein Heiligtum darin gebaut für deinen Namen* und gesagt:", footnotes: ["℘ Jos 21,43", "℘ Kap. 6,5.6"] },
      { number: 9, text: "Wenn Unglück über uns kommt, Schwert, Strafgericht oder Pest oder Hungersnot, und wir treten vor dieses Haus und vor dich* — denn dein Name ist in diesem Haus* — und schreien zu dir um Hilfe aus unserer Bedrängnis, dann wirst* du hören und retten*.", footnotes: ["℘ Kap. 6,29; Esr 10,1", "℘ Kap. 6,5.6", "o. mögest", "℘ 1Kö 8,30.37; Ps 50,15"] },
      { number: 10, text: "Und nun, siehe, da stehen die Söhne Ammon und Moab und die vom Gebirge Seïr. Als Israel aus dem Land Ägypten kam, hast du nicht erlaubt, bei ihnen einzudringen, sondern sie* mussten ihnen weichen und haben sie nicht ausgerottet*.", footnotes: ["d. h. die Israeliten", "℘ 4Mo 20,21; 5Mo 2,19.37"] },
      { number: 11, text: "Siehe da, sie vergelten es uns, indem sie kommen, um uns aus deinem Besitz zu vertreiben*, den du uns zum Besitz gegeben hast*.", footnotes: ["℘ Ps 83,5; Am 1,11", "℘ 1Mo 12,7; 5Mo 4,38; Jos 1,6"] },
      { number: 12, text: "Unser Gott, willst du sie nicht richten?* Denn in uns ist keine Kraft vor dieser großen Menge, die gegen uns kommt. Wir erkennen nicht, was wir tun sollen, sondern auf dich sind unsere Augen gerichtet*.", footnotes: ["℘ Ps 94,2", "℘ Ps 25,15"] },
      { number: 13, text: "Und ganz Juda stand vor dem HERRN mit ihren Kindern, ihren Frauen und ihren Söhnen*.", footnotes: ["℘ 5Mo 29,9.10; Joe 2,16"] },
      { number: 14, text: "Und auf Jahasiël, den Sohn Secharjas, des Sohnes Benajas, des Sohnes Jehiëls, des Sohnes Mattanjas, den Leviten, von den Söhnen Asafs, auf ihn kam der Geist des HERRN mitten in der Versammlung*.", footnotes: ["℘ Kap. 15,1"] },
      { number: 15, text: "Und er sprach: Merkt auf, ganz Juda und ihr Bewohner von Jerusalem und du, König Joschafat! So spricht der HERR zu euch: Fürchtet euch nicht und seid nicht niedergeschlagen vor dieser großen Menge*! Denn der Kampf ist nicht eure Sache, sondern Gottes!*", footnotes: ["℘ Kap. 32,7", "℘ 2Mo 14,13.14; Ri 7,21; 1Sam 17,47; 1Kö 20,13; Jes 37,6"] },
      { number: 16, text: "Morgen zieht gegen sie hinab. Siehe, sie kommen die Anhöhe von Ziz herauf, und ihr werdet sie am Ausgang des Tales finden vor der Wüste Jeruël." },
      { number: 17, text: "Nicht ihr werdet dabei kämpfen müssen*. Tretet hin, steht und seht die Rettung des HERRN, die er euch verschafft*, Juda und Jerusalem! Fürchtet euch nicht und seid nicht niedergeschlagen!* Zieht ihnen morgen entgegen, und der HERR wird mit euch sein!* —", footnotes: ["℘ 4Mo 14,9; 5Mo 3,22", "o. die Rettung des HERRN, der mit euch ist\n℘ 2Mo 6,1", "℘ 2Mo 6,1", "℘ 2Mo 6,1"] },
      { number: 18, text: "Da neigte sich Joschafat mit dem Gesicht zur Erde. Und ganz Juda und die Bewohner von Jerusalem fielen nieder vor dem HERRN, um den HERRN anzubeten*.", footnotes: ["℘ Kap. 7,3; Neh 8,6"] },
      { number: 19, text: "Und die Leviten, von den Söhnen der Kehatiter und von den Söhnen der Korachiter, standen auf, um den HERRN, den Gott Israels, zu loben mit überaus lauter Stimme*.", footnotes: ["℘ 1Chr 15,16; Neh 9,4"] },
      { number: 20, text: "Und sie machten sich des Morgens früh auf und zogen aus zur Wüste Tekoa*. Und bei ihrem Auszug trat Joschafat hin und sagte: Hört mir zu, Juda und ihr Bewohner von Jerusalem! Glaubt an den HERRN, euren Gott, dann werdet ihr bestehen*! Glaubt seinen Propheten, dann wird es euch gelingen!*", footnotes: ["℘ Kap. 11,6", "℘ Ps 125,1; Jes 28,16; 2Petr 1,19", "℘ Mt 8,13"] },
      { number: 21, text: "Und er beriet sich mit dem Volk und stellte Sänger für den HERRN auf, die Loblieder sangen in heiligem Schmuck, indem sie vor den zum Kampf Gerüsteten auszogen und sprachen: Preist den HERRN, denn seine Gnade währt ewig!*", footnotes: ["℘ Kap. 5,13; Ps 18,4"] },
      { number: 22, text: "Und zu der Zeit, da sie mit Jubel und Lobgesang anfingen*, legte der HERR einen Hinterhalt* gegen die Söhne Ammon, Moab und die vom Gebirge Seïr, die gegen Juda gekommen waren; und sie wurden geschlagen*.", footnotes: ["℘ Kap. 5,13; Ps 18,4", "o. gab der HERR Auflauerer. — Mit Textänderung lesen andere: gab der HERR Verwirrungen", "℘ Kap. 13,15; Jos 6,16; 2Sam 22,4"] },
      { number: 23, text: "Und die Söhne Ammon und Moab standen auf gegen die Bewohner des Gebirges Seïr, um an ihnen den Bann zu vollstrecken und sie auszutilgen. Und als sie die Bewohner von Seïr aufgerieben hatten, halfen sie, sich gegenseitig umzubringen*.", footnotes: ["℘ Ri 7,22"] },
      { number: 24, text: "Und Juda kam auf den Aussichtspunkt zur Wüste hin. Und sie sahen sich nach der Menge um, und siehe, da waren es Leichen, die auf der Erde lagen; niemand war entkommen*.", footnotes: ["℘ 2Mo 14,28; 2Kö 19,35"] },
      { number: 25, text: "Da kamen Joschafat und sein Volk, um ihre Beute einzusammeln*. Und sie fanden unter ihnen in reicher Menge sowohl Besitz als auch Kleider* und kostbare Geräte und plünderten so viel für sich*, dass sie es nicht mehr tragen konnten. Drei Tage brachten sie mit dem Einsammeln* der Beute zu, denn sie war groß*.", footnotes: ["w. zu rauben, o. zu plündern", "so mit 7 hebr. Handschr. und einer Ausgabe der Vulg.; Mas. T.: Leichen", "℘ 4Mo 31,53; Jos 11,14; 2Kö 7,16", "w. mit dem Rauben o. Plündern", "℘ Sach 14,14"] },
      { number: 26, text: "Und am vierten Tag sammelten sie sich im Tal Beracha*. Denn dort dankten sie dem HERRN*; daher gab man diesem Ort den Namen Tal Beracha bis auf den heutigen Tag.", footnotes: ["d. h. Dank, o. Lobpreis", "℘ Joe 4,2"] },
      { number: 27, text: "Und alle Männer von Juda und Jerusalem kehrten zurück, mit Joschafat an ihrer Spitze, um nach Jerusalem zurückzukehren mit Freuden*; denn der HERR hatte ihnen Freude an ihren Feinden gegeben*.", footnotes: ["℘ Neh 12,43", "℘ 1Sam 2,1"] },
      { number: 28, text: "Und sie kamen nach Jerusalem, zum Haus des HERRN, mit Harfen und mit Zithern und mit Trompeten*.", footnotes: ["℘ Ps 95,1.2"] },
      { number: 29, text: "Und der Schrecken Gottes fiel auf alle Königreiche der Länder*, als sie hörten, dass der HERR mit den Feinden Israels gekämpft hatte*.", footnotes: ["℘ Kap. 14,13", "℘ 2Mo 14,14.25"] },
      { number: 30, text: "Und das Königreich Joschafats hatte Ruhe. Und sein Gott schaffte ihm Ruhe ringsumher*.", footnotes: ["℘ Kap. 15,15; 3Mo 26,6; Hi 11,19; Spr 3,24; Zef 3,13"] },
      { number: 31, text: "*Und so regierte Joschafat über Juda. Er war 35 Jahre alt, als er König wurde, und er regierte 25 Jahre in Jerusalem. Und der Name seiner Mutter war Asuba, die Tochter des Schilhi.", heading: "Joschafats Gottesfurcht — Sein vergebliches Bündnis mit Ahasja von Israel", footnotes: ["℘ 1Kö 22,41-51"] },
      { number: 32, text: "Und er ging auf dem Weg seines Vaters Asa und wich nicht davon ab, indem er tat, was recht war in den Augen des HERRN*.", footnotes: ["℘ Kap. 15,17"] },
      { number: 33, text: "Nur die Höhen wichen nicht*, denn das Volk hatte sein Herz noch nicht auf den Gott seiner Väter gerichtet*.", footnotes: ["℘ Kap. 15,17", "℘ Kap. 30,19; 33,17; 5Mo 29,3; 1Sam 7,3"] },
      { number: 34, text: "Die übrige Geschichte* Joschafats, die frühere und die spätere*, siehe, sie ist geschrieben in der Geschichte* Jehus, des Sohnes Hananis*, die in das Buch der Könige von Israel aufgenommen ist*.", footnotes: ["w. Der Rest der Begebenheiten", "℘ Kap. 12,15", "w. in den Begebenheiten", "℘ Kap. 16,7", "℘ Kap. 25,26; 1Kö 14,19"] },
      { number: 35, text: "Danach verband sich Joschafat, der König von Juda, mit Ahasja, dem König von Israel*. Dieser handelte gottlos*.", footnotes: ["℘ Kap. 18,1; 21,6", "℘ 1Kö 22,53.54"] },
      { number: 36, text: "Und er verband sich mit ihm*, Schiffe zu bauen, um nach Tarsis zu fahren; und sie bauten Schiffe zu Ezjon-Geber*.", footnotes: ["w. Und er verband ihn mit sich\n℘ Eph 5,7", "℘ Kap. 8,17; 1Kö 10,22"] },
      { number: 37, text: "Und Eliëser, der Sohn des Dodawa, von Marescha* weissagte gegen Joschafat und sprach: Weil du dich mit Ahasja verbunden hast, wird der HERR dein Werk zerstören. Und die Schiffe wurden zertrümmert und konnten nicht nach Tarsis fahren.", footnotes: ["℘ Kap. 11,8"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Und Joschafat legte sich zu seinen Vätern und wurde bei seinen Vätern begraben in der Stadt Davids. Und sein Sohn Joram wurde an seiner Stelle König. —", heading: "Joram von Juda — Sein Götzendienst und seine Bestrafung", footnotes: ["℘ 2Kö 8,16-24"] },
      { number: 2, text: "Und er hatte Brüder, Söhne Joschafats: Asarja und Jehiël und Secharja und Asarjahu und Michael und Schefatja; diese alle waren Söhne Joschafats, des Königs von Israel*.", footnotes: ["Gemeint ist hier Israel im weiteren Sinne; vgl. Kap. 12,6; 28,19."] },
      { number: 3, text: "Und ihr Vater gab ihnen viele Geschenke an Silber und an Gold und an Kostbarkeiten, dazu befestigte Städte in Juda*. Aber das Königtum gab er Joram, denn er war der Erstgeborene*.", footnotes: ["℘ Kap. 11,23", "℘ 5Mo 21,17"] },
      { number: 4, text: "Als Joram nun die Herrschaft über das Königreich seines Vaters angetreten hatte und erstarkt war, brachte er alle seine Brüder* mit dem Schwert um und auch einige Oberste von Israel*.", footnotes: ["℘ V. 13; Ri 9,5", "Gemeint ist hier Israel im weiteren Sinne; vgl. Kap. 12,6; 28,19."] },
      { number: 5, text: "32 Jahre war Joram alt, als er König wurde, und er regierte acht Jahre in Jerusalem." },
      { number: 6, text: "Und er ging auf dem Weg der Könige von Israel*, wie es das Haus Ahabs getan hatte, denn er hatte eine Tochter Ahabs zur Frau*. Und er tat, was böse war in den Augen des HERRN.", footnotes: ["℘ Kap. 20,35; 28,2", "℘ Kap. 18,1; 22,2"] },
      { number: 7, text: "Aber der HERR wollte das Haus Davids nicht zugrunde richten, wegen des Bundes, den er mit David geschlossen hatte, und weil er gesagt hatte, dass er ihm und seinen Söhnen eine Leuchte geben wolle alle Tage*.", footnotes: ["℘ Kap. 6,16; 1Kö 11,36"] },
      { number: 8, text: "In seinen Tagen fiel Edom von der Herrschaft unter der Hand Judas ab und setzte einen eigenen König über sich*.", footnotes: ["℘ Kap. 28,17"] },
      { number: 9, text: "Da zog Joram hinüber mit seinen Obersten und alle Kriegswagen mit ihm. Und es geschah, als er sich des Nachts aufmachte, da schlug er Edom, das ihn und die Obersten der Kriegswagen eingekreist hatte." },
      { number: 10, text: "Doch fiel Edom von der Herrschaft unter der Hand Judas ab bis auf den heutigen Tag. Damals, in jener Zeit, fiel auch Libna* von der Herrschaft unter seiner Hand ab; denn er hatte den HERRN, den Gott seiner Väter, verlassen*.", footnotes: ["℘ Jos 10,29", "℘ Kap. 28,6; Jes 1,28; Jer 2,19"] },
      { number: 11, text: "Auch er machte Höhen auf den Bergen Judas* und hielt die Bewohner von Jerusalem zur Hurerei an*, und er verführte Juda*.", footnotes: ["℘ Ps 78,58; Hes 16,24", "℘ 2Mo 34,16; 5Mo 31,16; Jer 3,8.9; Hes 23,11.44", "℘ Jes 65,7; Jer 3,8; Hos 4,15; 12,1; 2Petr 2,2"] },
      { number: 12, text: "Da gelangte ein Schreiben von dem Propheten Elia* an ihn, das lautete: So spricht der HERR, der Gott deines Vaters David: Weil du nicht auf den Wegen deines Vaters Joschafat* und auf den Wegen Asas*, des Königs von Juda, gegangen bist,", footnotes: ["℘ 1Kö 17,1", "℘ Kap. 17,3.4", "℘ Kap. 14,1"] },
      { number: 13, text: "sondern auf dem Weg der Könige von Israel gegangen bist und Juda und die Bewohner von Jerusalem zur Hurerei angehalten hast, nach den Hurereien des Hauses Ahabs*, und weil du auch deine Brüder, das Haus deines Vaters, umgebracht hast*, die besser waren als du*:", footnotes: ["℘ Kap. 24,18; 1Kö 16,30-33", "℘ V. 4", "℘ 1Kö 2,32"] },
      { number: 14, text: "Siehe, der HERR wird dein Volk und deine Söhne und deine Frauen und all deinen Besitz mit einer großen Plage treffen*.", footnotes: ["w. plagen"] },
      { number: 15, text: "Du aber wirst eine schwere Krankheit erleiden, eine Krankheit deiner Eingeweide*, bis deine Eingeweide im Laufe der Zeit* infolge der Krankheit heraustreten werden.", footnotes: ["w. Du aber wirst in großen Krankheiten sein, in Erkrankung deiner Eingeweide", "w. Tage über Tage"] },
      { number: 16, text: "Und der HERR erweckte gegen Joram den Geist der Philister und der Araber, die neben den Kuschitern wohnen*.", footnotes: ["℘ Kap. 26,7"] },
      { number: 17, text: "Und sie zogen gegen Juda herauf und drangen darin ein und nahmen den ganzen Besitz weg, der sich im Haus des Königs befand, und auch seine Söhne und seine Frauen. Und es blieb ihm kein Sohn übrig außer Joahas, dem jüngsten von seinen Söhnen*. —", footnotes: ["℘ Kap. 22,1; 25,23; Am 1,6"] },
      { number: 18, text: "Und nach alldem plagte ihn der HERR mit einer unheilbaren Krankheit in seinen Eingeweiden*.", footnotes: ["℘ Apg 12,23"] },
      { number: 19, text: "Und es geschah im Laufe der Zeit*, und zwar zur Zeit, als das Ende von zwei Jahren eintrat, dass seine Eingeweide bei seiner Krankheit heraustraten; und er starb unter großen Schmerzen*. Und sein Volk machte ihm keinen Brand, wie es für seine Väter einen Brand gemacht hatte*.", footnotes: ["w. für Tage von Tagen; d. h. vielleicht auch: zu einer bestimmten Zeit", "℘ Kap. 24,25", "℘ Kap. 16,14"] },
      { number: 20, text: "Er war 32 Jahre alt, als er König wurde, und regierte acht Jahre in Jerusalem. Er ging dahin, ohne bedauert zu werden*. Und man begrub ihn in der Stadt Davids, aber nicht in den Gräbern der Könige*.", footnotes: ["o. ungeliebt; o. ohne Kostbarkeiten als Grabbeigaben", "℘ Kap. 24,25; 28,27; 33,20"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "*Und die Bewohner von Jerusalem machten Ahasja*, seinen jüngsten Sohn*, an seiner Stelle zum König. Denn alle älteren hatte die Kriegsschar umgebracht, die mit den Arabern ins Lager gekommen war*. So wurde Ahasja, der Sohn Jorams, des Königs von Juda, König.", heading: "Ahasja von Juda — Sein Bündnis mit dem Haus Ahabs und sein Untergang", footnotes: ["℘ 2Kö 8,25-29; 9,1-29", "d. i. Joahas", "℘ Kap. 21,17; 2Kö 8,24; 10,13", "℘ Kap. 15,17"] },
      { number: 2, text: "22 Jahre* war Ahasja alt, als er König wurde, und er regierte ein Jahr in Jerusalem; und der Name seiner Mutter war Atalja, die Tochter Omris*.", footnotes: ["so mit mehreren alten Üs.; Mas. T.: 42 Jahre", "Gemeint ist die Enkeltochter Omris.\n℘ Kap. 21,6; 2Kö 8,18"] },
      { number: 3, text: "Auch er ging auf den Wegen des Hauses Ahabs; denn seine Mutter war seine Beraterin zu gottlosem Handeln*.", footnotes: ["℘ Kap. 24,7.17; 1Mo 27,13; 5Mo 13,7; Mt 14,8"] },
      { number: 4, text: "Und er tat, was böse war in den Augen des HERRN, wie das Haus Ahabs; denn die waren nach dem Tod seines Vaters seine Berater zu seinem Verderben*.", footnotes: ["℘ Kap. 24,17.18; Mi 6,16"] },
      { number: 5, text: "Auch ging er auf ihren Rat ein und zog mit Joram, dem Sohn Ahabs, dem König von Israel*, in den Kampf gegen Hasaël, den König von Aram, nach Ramot in Gilead. Und die Aramäer* verwundeten Joram.", footnotes: ["℘ 2Kö 3,1", "LXX: die Bogenschützen"] },
      { number: 6, text: "Da kehrte er zurück, um sich in Jesreel von den Wunden heilen zu lassen, die sie ihm bei Rama geschlagen hatten, als er gegen Hasaël, den König von Aram, kämpfte. Und Ahasja*, der Sohn Jorams, der König von Juda, zog hinab, um Joram, den Sohn Ahabs, in Jesreel zu besuchen, weil er krank war.", footnotes: ["so mit mehreren hebr. Handschr., LXX, Vulg. und der syr. Üs. und 2Kö 8,29; Mas. T.: Asarja"] },
      { number: 7, text: "Aber von Gott aus war es der Untergang* Ahasjas, dass er zu Joram ging*. Denn als er angekommen war, zog er mit Joram aus gegen Jehu, den Sohn Nimschis, den der HERR gesalbt hatte, um das Haus Ahabs auszurotten*.", footnotes: ["w. war es die Zertretung", "℘ Kap. 10,15; 1Kö 12,15.24; Jos 11,20; Spr 16,9", "℘ 2Kö 10,11"] },
      { number: 8, text: "Und es geschah, als Jehu an dem Haus Ahabs Gericht übte*, da traf er die Obersten von Juda und die Söhne der Brüder Ahasjas, die im Dienst Ahasjas standen; und er brachte sie um*.", footnotes: ["℘ Kap. 24,24", "℘ 2Kö 10,12-14"] },
      { number: 9, text: "Und er suchte Ahasja, und man nahm ihn gefangen, als er sich in Samaria versteckt hielt; und sie brachten ihn zu Jehu und töteten ihn*. Und sie begruben ihn, denn sie sagten: Er ist ein Sohn Joschafats, der den HERRN mit seinem ganzen Herzen gesucht hat*. Und das Haus Ahasjas hatte niemand mehr, der zum Königtum fähig gewesen wäre.", footnotes: ["℘ Kap. 24,25; 25,27; 33,24", "℘ Kap. 17,3.4; 19,3"] },
      { number: 10, text: "*Als aber Atalja, die Mutter Ahasjas, sah, dass ihr Sohn tot war, machte sie sich auf und brachte die ganze königliche Nachkommenschaft vom Haus Juda um*.", heading: "Herrschaft der Atalja in Jerusalem", footnotes: ["℘ 2Kö 11,1-3", "℘ 1Kö 1,21"] },
      { number: 11, text: "Doch Joscheba, die Tochter des Königs, nahm Joasch, den Sohn Ahasjas, und stahl ihn aus der Mitte der Königssöhne, die getötet werden sollten, und sie brachte ihn und seine Amme in die Bettenkammer. So verbarg ihn Joscheba, die Tochter des Königs Joram, die Frau des Priesters Jojada — denn sie war die Schwester Ahasjas — vor Atalja, so dass sie ihn nicht tötete." },
      { number: 12, text: "Und er hielt sich sechs Jahre lang bei ihnen im Haus Gottes versteckt*. Atalja aber herrschte als Königin über das Land.", footnotes: ["℘ Spr 28,28"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "*Und im siebten Jahr fasste Jojada Mut *und schloss mit den Obersten über Hundert, Asarja, dem Sohn Jerohams, und Ismael, dem Sohn Johanans, und Asarja, dem Sohn Obeds, und Maaseja, dem Sohn Adajas, und Elischafat, dem Sohn Sichris, einen Bund*.", heading: "Verschwörung des Priesters Jojada gegen Atalja — Einsetzung des Joasch zum König — Ataljas Ende — Abschaffung des Götzendienstes", footnotes: ["℘ 2Kö 11,4-20", "w. und nahm die Obersten . . . mit sich in einen Bund", "w. und nahm die Obersten . . . mit sich in einen Bund"] },
      { number: 2, text: "Und sie zogen umher in Juda und versammelten die Leviten aus allen Städten Judas* und die Familienoberhäupter* von Israel; und sie kamen nach Jerusalem.", footnotes: ["℘ Kap. 11,13", "w. Häupter der Väter"] },
      { number: 3, text: "Und die ganze Versammlung schloss im Haus Gottes einen Bund mit dem König. Und Jojada sagte zu ihnen: Siehe, der Sohn des Königs soll König sein, wie der HERR über die Söhne Davids geredet hat*.", footnotes: ["℘ Kap. 6,16"] },
      { number: 4, text: "Das ist es, was ihr tun sollt: Ein Drittel von euch, von den Priestern und den Leviten, die ihr am Sabbat antretet, soll Torhüter an den Schwellen sein*,", footnotes: ["℘ 1Chr 9,25"] },
      { number: 5, text: "und ein Drittel soll im Haus des Königs sein, und ein Drittel am Grundtor; aber alles Volk soll in den Vorhöfen des Hauses des HERRN sein." },
      { number: 6, text: "Und es soll niemand in das Haus des HERRN hineingehen. Nur die Priester und die diensttuenden Leviten*, sie sollen hineingehen, denn sie sind heilig. Und alles Volk soll die Vorschriften des HERRN beachten.", footnotes: ["℘ 1Chr 23,28"] },
      { number: 7, text: "Und die Leviten sollen den König von allen Seiten umgeben, jeder mit seinen Waffen in seiner Hand. Und wer in das Haus hineingeht, soll getötet werden. Und ihr sollt bei dem König sein, wenn er hineingeht und wenn er herauskommt." },
      { number: 8, text: "Und die Leviten und ganz Juda taten nach allem, was der Priester Jojada befohlen hatte. Sie nahmen jeder seine Männer, die am Sabbat antraten, zusammen mit denen, die am Sabbat abtraten; denn der Priester Jojada hatte die Abteilungen nicht entlassen*.", footnotes: ["℘ 1Chr 24; 25; 26"] },
      { number: 9, text: "Und der Priester Jojada gab den Obersten über Hundert die Speere und die Kleinschilde und die Rundschilde, die dem König David gehört hatten, die im Haus Gottes waren." },
      { number: 10, text: "Und er stellte das ganze Volk auf, und zwar jeden mit seiner Waffe in seiner Hand, von der rechten Seite* des Hauses bis zur linken Seite* des Hauses, zum Altar und zum Haus hin, rings um den König herum.", footnotes: ["d. i. die Südseite", "d. i. die Nordseite"] },
      { number: 11, text: "Und sie führten den Sohn des Königs heraus und setzten ihm die Krone auf und gaben ihm die Ordnung*, und sie machten ihn zum König. Und Jojada und seine Söhne salbten ihn und riefen: Es lebe der König!*", footnotes: ["d. i. das Königsprotokoll", "℘ 1Kö 1,25.34.39"] },
      { number: 12, text: "Als aber Atalja das Geschrei des Volkes hörte, das herbeilief und den König rühmte, kam sie zum Volk ins Haus des HERRN." },
      { number: 13, text: "Und sie sah: Und siehe, da stand der König auf seinem erhöhten Standort* am Eingang* und die Obersten und die Trompeter beim König. Und alles Volk des Landes war fröhlich und stieß in die Trompeten. Und die Sänger standen da mit Musikinstrumenten und leiteten den Lobgesang*. Da zerriss Atalja ihre Kleider und rief: Verschwörung, Verschwörung!", footnotes: ["o. an seiner Säule", "℘ Hes 46,2", "℘ 1Chr 25,6"] },
      { number: 14, text: "Der Priester Jojada aber ließ die Obersten über Hundert, die Vorgesetzten des Heeres, heraustreten und sagte zu ihnen: Führt sie durch die Reihen hinaus*! Und wer ihr folgt, soll mit dem Schwert getötet werden! Denn der Priester hatte gesagt: Ihr sollt sie nicht im Haus des HERRN töten!", footnotes: ["o. Führt sie aus dem Inneren der Vorhöfe hinaus"] },
      { number: 15, text: "Und sie legten Hand an sie*, und sie ging zum Eingang des Rosstores am Haus des Königs; und sie töteten sie dort*.", footnotes: ["o. mit LXX, der syr. und aram. Üs.: Sie machten ihr Platz", "℘ 4Mo 35,33"] },
      { number: 16, text: "Und Jojada schloss einen Bund zwischen sich* und dem ganzen Volk und dem König, dass sie das Volk des HERRN sein sollten*.", footnotes: ["Andere ändern den Text nach 2Kö 11,17 in: einen Bund zwischen dem HERRN", "℘ Kap. 15,12; 5Mo 29,11-14"] },
      { number: 17, text: "Da ging das ganze Volk in das Haus des Baal und riss es nieder, und sie zerschlugen seine Altäre und seine Götzenbilder. Und Mattan, den Priester des Baal, ermordeten sie vor den Altären*.", footnotes: ["℘ 1Kö 18,40"] },
      { number: 18, text: "Und Jojada legte die Ämter des Hauses des HERRN in die Hand der Priester*, der Leviten, die David für das Haus des HERRN eingeteilt hatte, damit sie die Brandopfer des HERRN opferten, wie es im Gesetz des Mose geschrieben steht*, mit Freuden* und mit Gesang, nach der Anweisung Davids*.", footnotes: ["℘ Kap. 35,2; 1Chr 23,4", "℘ 4Mo 28", "℘ Esr 6,22", "℘ Kap. 7,6; 29,30; 1Chr 25,1"] },
      { number: 19, text: "Und er stellte die Torhüter an die Tore des Hauses des HERRN, damit keiner hineinging, der irgendwie unrein war*.", footnotes: ["℘ Kap. 8,14; 1Chr 9,23"] },
      { number: 20, text: "Und er nahm die Obersten über Hundert und die Mächtigen und die Gebieter im Volk und das ganze Volk des Landes und führte den König aus dem Haus des HERRN hinab, und sie kamen durch das obere Tor ins Haus des Königs. Und sie setzten den König auf den Thron des Königreichs*.", footnotes: ["℘ 1Chr 29,23"] },
      { number: 21, text: "Und das ganze Volk des Landes freute sich*, und die Stadt hatte Ruhe*. Atalja aber hatten sie mit dem Schwert getötet.", footnotes: ["℘ 1Chr 12,41; Spr 11,10", "o. aber die Stadt verhielt sich still; d. h. sie freute sich nicht mit"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "*Sieben Jahre war Joasch alt*, als er König wurde, und er regierte vierzig Jahre in Jerusalem; und der Name seiner Mutter war Zibja, von Beerscheba.", heading: "Joasch von Juda unter der Leitung Jojadas — Ausbesserung des Tempels", footnotes: ["℘ 2Kö 12,1-17", "w. Ein Sohn von sieben Jahren war Joasch"] },
      { number: 2, text: "Und Joasch tat, was recht war in den Augen des HERRN*, all die Tage des Priesters Jojada.", footnotes: ["℘ Kap. 25,2; 26,4.5"] },
      { number: 3, text: "Und Jojada nahm zwei Frauen für ihn; und er zeugte Söhne und Töchter." },
      { number: 4, text: "Und es geschah danach, dass es Joasch am Herzen lag, das Haus des HERRN zu erneuern." },
      { number: 5, text: "Und er versammelte die Priester und die Leviten und sagte zu ihnen: Zieht aus in die Städte Judas und sammelt von ganz Israel Geld ein, um das Haus eures Gottes von Jahr zu Jahr auszubessern*! Und ihr sollt euch mit der Sache beeilen! Aber die Leviten beeilten sich nicht.", footnotes: ["℘ Kap. 34,8-11"] },
      { number: 6, text: "Da rief der König den Oberpriester* Jojada und sagte zu ihm: Warum hast du die Leviten nicht aufgefordert, aus Juda und Jerusalem *die Abgabe hereinzuholen, die Mose, der Knecht des HERRN, der Versammlung Israels für das Zelt des Zeugnisses auferlegt hat*?", footnotes: ["w. das Haupt", "w. hereinzuholen die Abgabe des Mose, des Knechtes des HERRN, und der Versammlung Israels für das Zelt des Zeugnisses", "w. hereinzuholen die Abgabe des Mose, des Knechtes des HERRN, und der Versammlung Israels für das Zelt des Zeugnisses\n℘ 2Mo 30,12-16; Mt 17,24"] },
      { number: 7, text: "Denn Atalja*, die Gottlosigkeit in Person, und ihre Söhne sind in das Haus Gottes eingebrochen* und haben auch alle heiligen Gaben* des Hauses des HERRN für die Baalim verwendet*. —", footnotes: ["℘ Kap. 22,3.4; 2Kö 11,1", "o. haben das Haus Gottes verfallen lassen", "o. heiligen Dinge", "℘ Hos 2,10"] },
      { number: 8, text: "Und der König befahl, und man machte einen Kasten und stellte ihn draußen im Tor des Hauses des HERRN auf." },
      { number: 9, text: "Und man rief in Juda und in Jerusalem aus, dass man dem HERRN die Abgabe bringen solle, die Mose, der Knecht Gottes, Israel in der Wüste auferlegt hatte*.", footnotes: ["℘ 2Mo 30,12-16; Mt 17,24"] },
      { number: 10, text: "Da freuten sich alle Obersten und das ganze Volk*. Und sie brachten ihre Gaben und warfen sie in den Kasten, bis er voll war*.", footnotes: ["℘ 1Chr 29,9", "w. bis zum Vollenden"] },
      { number: 11, text: "Und es geschah jedes Mal*, wenn man den Kasten durch die Leviten zur Verwaltung des Königs brachte und wenn man sah, dass viel Geld darin war, dann kamen der Schreiber des Königs und der Beamte des Oberpriesters* und leerten den Kasten aus und nahmen ihn auf und brachten ihn wieder an seinen Platz. So machten sie es Tag für Tag und sammelten Geld in Menge.", footnotes: ["w. zur Zeit", "o. des ersten Priesters"] },
      { number: 12, text: "Und der König und Jojada gaben es denen, die das Werk der Arbeit am Haus des HERRN ausführten, und diese warben Steinhauer und Zimmerleute an, das Haus des HERRN zu erneuern, und auch Handwerker in Eisen und Bronze, das Haus des HERRN auszubessern*.", footnotes: ["℘ Kap. 34,8-11"] },
      { number: 13, text: "Und die Werkmeister arbeiteten, und die Ausbesserung des Werkes ging durch ihre Hand voran. Und sie stellten das Haus Gottes in seinem früheren Zustand* wieder her und verstärkten es.", footnotes: ["w. in seiner Abmessung"] },
      { number: 14, text: "Und als sie fertig waren, brachten sie den Rest des Geldes vor den König und vor Jojada. Und er ließ dafür Geräte* machen für das Haus des HERRN, Geräte für den Dienst und für die Brandopfer, und Schalen und goldene und silberne Geräte. Und man opferte regelmäßig Brandopfer* im Haus des HERRN, alle Tage Jojadas.", footnotes: ["℘ 2Kö 25,12", "℘ Kap. 2,3; 31,2.3; 1Chr 23,31"] },
      { number: 15, text: "Und Jojada wurde alt und der Tage satt*, und er starb. Er war 130 Jahre alt, als er starb.", footnotes: ["℘ 1Mo 25,8"] },
      { number: 16, text: "Und man begrub ihn in der Stadt Davids* bei den Königen, weil er Gutes getan hatte an Israel und für Gott und sein Haus.", footnotes: ["℘ 1Kö 2,10"] },
      { number: 17, text: "*Und nach dem Tod Jojadas kamen die Obersten von Juda und beugten sich vor dem König nieder; und der König hörte auf sie*.", heading: "Joaschs Abfall von Gott und seine Ermordung", footnotes: ["℘ 2Kö 12,18-22", "℘ Kap. 22,3"] },
      { number: 18, text: "Und sie verließen das Haus des HERRN, des Gottes ihrer Väter, und dienten den Ascherim und den Götzenbildern*. Da kam ein Zorn vom HERRN über Juda und Jerusalem wegen dieser ihrer Schuld*.", footnotes: ["℘ Kap. 21,13; 22,4; Ri 8,33; 1Kö 14,23", "℘ Kap. 12,1.2; 25,15; 28,13; 29,8; 32,25; 34,25; Eph 5,6"] },
      { number: 19, text: "Und er sandte Propheten unter sie, um sie zu dem HERRN zurückzuführen, und diese warnten sie; aber sie hörten nicht darauf*. —", footnotes: ["℘ Kap. 36,13.15.16; 2Kö 17,14.15; Neh 9,30; Jer 7,25.26; 25,3-8"] },
      { number: 20, text: "Und der Geist Gottes kam über Secharja*, den Sohn des Priesters Jojada*. Und er trat vor das Volk und sagte zu ihnen: So spricht Gott: Warum übertretet ihr die Gebote des HERRN*? So wird es euch nicht gelingen! Weil ihr den HERRN verlassen habt, so hat auch er euch verlassen*. —", footnotes: ["w. bekleidete Secharja", "℘ Kap. 15,1", "℘ 4Mo 14,41", "℘ Kap. 12,5"] },
      { number: 21, text: "Und sie machten eine Verschwörung gegen ihn* und steinigten ihn auf Befehl des Königs im Vorhof des Hauses des HERRN*.", footnotes: ["℘ Jer 18,18; Am 5,10", "℘ Kap. 25,16; Ps 94,21; Mt 21,35; Lk 11,51; Hebr 11,37"] },
      { number: 22, text: "Und der König Joasch dachte nicht an die Gnade, die sein Vater Jojada ihm erwiesen hatte*, und brachte dessen Sohn um. Und als der starb, sprach er: Der HERR möge es sehen und Rechenschaft fordern!*", footnotes: ["℘ Ri 8,35", "℘ Jos 22,23; Ps 9,13; 10,14; Jer 26,14.15"] },
      { number: 23, text: "Und es geschah um die Wende des Jahres*, dass ein Heer der Aramäer gegen ihn heraufzog. Und sie kamen nach Juda und Jerusalem und brachten aus dem Volk alle Obersten des Volkes um; und alle ihre Beute sandten sie zum König von Damaskus.", footnotes: ["w. um die Drehung des Jahres; d. h. viell. die Tag- und Nachtgleiche"] },
      { number: 24, text: "Obwohl das Heer der Aramäer mit nur wenigen Männern gekommen war, so gab doch der HERR ein viel größeres Heer in ihre Hand, weil sie den HERRN, den Gott ihrer Väter, verlassen hatten*. So vollzogen sie an Joasch das Strafgericht*.", footnotes: ["℘ 3Mo 26,25; 5Mo 32,30; Zef 1,2", "℘ Kap. 22,8"] },
      { number: 25, text: "Und als sie von ihm abgezogen waren — sie ließen ihn aber mit schweren Verwundungen zurück* —, machten seine Knechte eine Verschwörung gegen ihn* wegen des Blutes des Sohnes* des Priesters Jojada. Und sie ermordeten ihn* auf seinem Bett, und er starb. Und man begrub ihn in der Stadt Davids, aber man begrub ihn nicht in den Gräbern der Könige*.", footnotes: ["℘ Kap. 21,19", "℘ Kap. 25,27; 1Kö 15,27", "w. der Söhne", "℘ Kap. 22,9", "℘ Kap. 21,20"] },
      { number: 26, text: "Und diese sind es, die sich gegen ihn verschworen: Sabad, der Sohn der Schimat, der Ammoniterin, und Josabad, der Sohn der Schimrit, der Moabiterin*. —", footnotes: ["℘ Kap. 25,3"] },
      { number: 27, text: "Seine Söhne aber und die Menge des ihm auferlegten Tributs* und die grundlegende Instandsetzung des Hauses Gottes, siehe, das ist geschrieben in der Schrift* des Buches der Könige. Und sein Sohn Amazja wurde an seiner Stelle König*.", footnotes: ["o. der Last auf ihm; o. der prophetischen Aussprüche gegen ihn", "o. Erforschung; o. Untersuchung; o. Auslegung; hebr. Midrasch", "℘ Kap. 25,1"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "*Amazja war 25 Jahre alt, als er König wurde, und er regierte 29 Jahre in Jerusalem; und der Name seiner Mutter war Joaddan, von Jerusalem*.", heading: "Amazja von Juda — Sein Gottvertrauen und sein Sieg über Seïr", footnotes: ["℘ 2Kö 14,1-7", "℘ Kap. 24,27"] },
      { number: 2, text: "Und er tat, was recht war in den Augen des HERRN*, jedoch nicht mit ungeteiltem Herzen.", footnotes: ["℘ Kap. 24,2; 26,4"] },
      { number: 3, text: "Und es geschah, als das Königtum bei ihm gefestigt war, brachte er seine Knechte um, die den König, seinen Vater, erschlagen hatten*.", footnotes: ["℘ Kap. 21,4; 24,25.26; 33,25"] },
      { number: 4, text: "Aber ihre Söhne tötete er nicht, sondern handelte, wie es im Gesetz, im Buch des Mose, geschrieben steht, wo der HERR geboten hat: Nicht sollen Väter um der Söhne willen sterben, und Söhne sollen nicht um der Väter willen sterben, sondern jeder soll für seine eigene Sünde sterben*.", footnotes: ["℘ 5Mo 24,16"] },
      { number: 5, text: "Und Amazja versammelte Juda, und er stellte sie auf nach Vaterhäusern, nach Obersten über Tausend und nach Obersten über Hundert, von ganz Juda und Benjamin. Und er musterte sie von zwanzig Jahren an und darüber und fand, dass 300 000 Auserlesene da waren, die mit dem Heer auszogen, die Spieß und Langschild trugen*.", footnotes: ["℘ Kap. 14,7"] },
      { number: 6, text: "Und er warb aus Israel 100 000 wehrfähige* Männer für hundert Talente Silber an. —", footnotes: ["o. angesehene; o. tüchtige"] },
      { number: 7, text: "Da kam ein Mann Gottes zu ihm und sagte: König, lass das Heer von Israel nicht mit dir ziehen! Denn der HERR ist nicht mit Israel und mit allen Söhnen Ephraim." },
      { number: 8, text: "Wenn du denkst, dadurch stark zu sein zum Kampf, dann wird Gott* dich zum Stürzen bringen vor dem Feind. Denn bei Gott ist Macht, zu helfen* und zum Stürzen zu bringen.", footnotes: ["so in Anlehnung an LXX und Vulg.; Mas. T. unklar; viell.: Vielmehr zieh du selbst aus, handle, sei stark zum Kampf! Sonst wird Gott", "℘ Kap. 26,7"] },
      { number: 9, text: "Und Amazja sagte zu dem Mann Gottes: Und was soll mit den hundert Talenten geschehen, die ich der Kriegsschar von Israel gegeben habe? Der Mann Gottes sagte: Der HERR hat genug, um dir mehr als das zu geben*.", footnotes: ["℘ Ps 24,1"] },
      { number: 10, text: "Da sonderte Amazja sie ab, die Kriegsschar nämlich, die aus Ephraim zu ihm gekommen war, damit sie an ihren Ort zurückkehrten. Und ihr Zorn entbrannte sehr gegen Juda, und sie kehrten in glühendem Zorn an ihren Ort zurück." },
      { number: 11, text: "Amazja aber fasste Mut und führte sein Volk in den Kampf. Und er zog ins Salztal und schlug die Söhne Seïr, 10 000 Mann." },
      { number: 12, text: "Und die Söhne Juda führten 10 000 lebend gefangen fort und brachten sie auf den Gipfel eines Felsens*, und sie stürzten sie hinab von dem Gipfel des Felsens*, dass sie allesamt zerschmettert wurden.", footnotes: ["o. auf die Höhe der Stadt Sela", "o. von der Höhe der Stadt Sela"] },
      { number: 13, text: "Aber die Männer der Schar, die Amazja hatte zurückkehren lassen, dass sie nicht mit ihm in den Kampf zögen, fielen in die Städte Judas ein, von Samaria bis Bet-Horon*, und erschlugen dreitausend Mann von ihnen und erbeuteten eine große Beute.", footnotes: ["℘ Jos 10,10"] },
      { number: 14, text: "*Und es geschah, nachdem Amazja von der Schlacht gegen Edom* zurückgekommen war, brachte er die Götter der Söhne Seïr mit und stellte sie sich als Götter auf. Und er beugte sich vor ihnen nieder und brachte ihnen Rauchopfer dar*.", heading: "Amazjas Götzendienst, Selbstüberhebung, Niederlage und Ende", footnotes: ["℘ 2Kö 14,8-20", "w. vom Schlag gegen Edom", "℘ Kap. 28,23; 2Mo 23,24; Am 2,4"] },
      { number: 15, text: "Da entbrannte der Zorn des HERRN gegen Amazja*; und er sandte einen Propheten zu ihm. Der sagte zu ihm: Warum hast du die Götter des Volkes gesucht, die nicht einmal ihr Volk aus deiner Hand gerettet haben?*", footnotes: ["℘ Kap. 24,18", "℘ Jes 45,20; Jer 10,5; 48,13"] },
      { number: 16, text: "Und es geschah, während er zu ihm redete, sagte Amazja* zu ihm: Haben wir dich zum Ratgeber des Königs gemacht? Hör auf! Warum soll man dich schlagen?* Und der Prophet hörte auf und sagte: Ich habe erkannt, dass Gott beschlossen hat, dich zu vernichten, weil du das getan und auf meinen Rat nicht gehört hast!*", footnotes: ["w. er", "℘ Kap. 16,10; 24,20.21; 2Mo 10,28; Jes 30,10", "℘ Spr 1,29-31; Jer 2,19"] },
      { number: 17, text: "Und Amazja, der König von Juda, beriet sich* und sandte zu Joasch, dem Sohn des Joahas, des Sohnes Jehus, dem König von Israel, und ließ ihm sagen: Auf, lass uns einander ins Angesicht sehen*!", footnotes: ["℘ 1Sam 27,1", "d. h. im Gefecht"] },
      { number: 18, text: "Da sandte Joasch, der König von Israel, zu Amazja, dem König von Juda, und ließ ihm sagen: Der Dornstrauch auf dem Libanon sandte zu der Zeder auf dem Libanon und sagte: Gib meinem Sohn deine Tochter zur Frau! Da liefen die Tiere des Feldes, die auf dem Libanon leben, darüber und zertraten den Dornstrauch." },
      { number: 19, text: "Du sagst: Siehe, ich habe* Edom geschlagen! Und darum erhebt sich* dein Herz, noch mehr Ehre zu genießen. Bleib nun in deinem Haus! Wozu willst du dich mit dem Unglück einlassen? Damit du fällst, du und Juda mit dir? —", footnotes: ["so mit einer LXX-Ausgabe, Vulg. u. der aram. Üs.; Mas. T.: du hast", "w. erhebt dich"] },
      { number: 20, text: "Aber Amazja hörte nicht, denn das war von Gott, damit er sie in die Hand der Feinde gäbe, weil sie die Götter von Edom gesucht hatten*.", footnotes: ["℘ Kap. 10,15"] },
      { number: 21, text: "Da zog Joasch, der König von Israel, herauf. Und sie sahen einander ins Angesicht*, er und Amazja, der König von Juda, bei Bet-Schemesch, das zu Juda gehört.", footnotes: ["d. h. im Gefecht"] },
      { number: 22, text: "Und Juda wurde vor Israel geschlagen*; und sie flohen, jeder zu seinem Zelt.", footnotes: ["℘ 2Kö 13,12"] },
      { number: 23, text: "Und Joasch, der König von Israel, nahm Amazja, den König von Juda, den Sohn des Joasch, des Sohnes des Joahas*, bei Bet-Schemesch gefangen und brachte ihn nach Jerusalem. Und er riss eine Bresche in die Mauer Jerusalems, vom Tor Ephraim bis an das Ecktor*, vierhundert Ellen.", footnotes: ["℘ Kap. 21,17; 22,1.11", "℘ Kap. 26,9"] },
      { number: 24, text: "Und er nahm alles Gold und Silber und alle Geräte, die sich im Haus Gottes bei Obed-Edom* befanden, und die Schätze des Hauses des Königs und die Geiseln und kehrte nach Samaria zurück.", footnotes: ["℘ 1Chr 26,15"] },
      { number: 25, text: "Und Amazja, der Sohn des Joasch, der König von Juda, lebte nach dem Tod des Joasch, des Sohnes des Joahas, des Königs von Israel, noch fünfzehn Jahre." },
      { number: 26, text: "Und die übrige Geschichte* Amazjas, die frühere und die spätere*, siehe, ist sie nicht geschrieben in dem Buch der Könige von Juda und Israel*?", footnotes: ["w. der Rest der Begebenheiten", "℘ Kap. 26,22; 1Chr 29,29", "℘ Kap. 20,34; 27,7; 32,32; 35,27; 36,8; 1Kö 14,19.29"] },
      { number: 27, text: "Und von der Zeit an, da Amazja von der Nachfolge des HERRN abgewichen* war, machten sie in Jerusalem eine Verschwörung gegen ihn*. Er aber floh nach Lachisch*. Und sie sandten Männer hinter ihm her bis Lachisch und töteten ihn dort*.", footnotes: ["w. von hinter dem HERRN gewichen", "℘ Kap. 24,25", "℘ Kap. 11,9", "℘ Kap. 22,9; 2Kö 12,22"] },
      { number: 28, text: "Und sie hoben ihn auf die Pferde und begruben ihn bei seinen Vätern in der Stadt Judas*.", footnotes: ["Manche hebr. Handschr. überliefern: Stadt Davids"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "*Und das ganze Volk von Juda nahm Usija* — der war sechzehn Jahre alt —, und sie machten ihn zum König anstelle seines Vaters Amazja.", heading: "Usija von Juda — Seine Gottesfurcht und seine Siege über die Feinde Judas", footnotes: ["℘ 2Kö 14,21.22; 15,1-4", "d. i. Asarja; vgl. 2Kö 14 u. 15\n℘ Am 1,1"] },
      { number: 2, text: "Er baute Elat wieder auf und brachte es an Juda zurück, nachdem der König sich zu seinen Vätern gelegt hatte." },
      { number: 3, text: "Usija war sechzehn Jahre alt, als er König wurde, und er regierte 52 Jahre in Jerusalem; und der Name seiner Mutter war Jecholja, von Jerusalem." },
      { number: 4, text: "Und er tat, was recht war in den Augen des HERRN, nach allem, was sein Vater Amazja getan hatte*.", footnotes: ["℘ Kap. 24,2; 25,2; 27,2; 29,2"] },
      { number: 5, text: "Und er suchte Gott in den Tagen Secharjas*, der ihn in den Gesichten Gottes unterwies*; und in den Tagen, da er den HERRN suchte, gab ihm Gott Gelingen*.", footnotes: ["℘ Kap. 14,6; 24,2; 29,1", "o. der Einsicht hatte in Gesichten Gottes; einige hebr. Handschr. u. alte Üs.: der ihn in der Furcht Gottes unterwies\n℘ 1Mo 41,15; Dan 1,17", "℘ Kap. 32,30; Jos 1,7.8; 1Chr 22,13"] },
      { number: 6, text: "Und er zog aus und kämpfte gegen die Philister und riss die Mauer von Gat* nieder und die Mauer von Jabne* und die Mauer von Aschdod*. Und er baute Städte bei Aschdod und im Land der Philister.", footnotes: ["℘ Kap. 11,8", "℘ Jos 15,11", "℘ Jos 15,47; Jes 20,1"] },
      { number: 7, text: "Und Gott half ihm* gegen die Philister und gegen die Araber*, die in Gur-Baal wohnten, und gegen die Mëuniter*.", footnotes: ["℘ Kap. 14,10.11; 25,8; 1Chr 5,20", "℘ Kap. 21,16", "℘ Kap. 20,1"] },
      { number: 8, text: "Und die Ammoniter entrichteten Usija Tribut*. Und sein Name drang bis nach Ägypten*, denn er war überaus mächtig geworden*.", footnotes: ["℘ Kap. 27,5", "℘ 1Chr 14,17", "℘ Kap. 17,11.12"] },
      { number: 9, text: "Und Usija baute Türme in Jerusalem auf dem* Ecktor* und auf dem* Taltor* und auf dem* Winkel* und befestigte sie.", footnotes: ["o. am", "℘ Kap. 25,23; Jer 31,38; Sach 14,10", "o. am", "℘ Neh 2,13", "o. am", "℘ Neh 3,19"] },
      { number: 10, text: "Und er baute Türme in der Steppe* und grub viele Zisternen. Denn er hatte viel Vieh, sowohl in der Niederung* als auch in der Ebene, und Bauern und Weingärtner* im Gebirge und im Fruchtland*; denn er liebte den Ackerbau*.", footnotes: ["℘ Kap. 17,12.13", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza\n℘ 1Chr 27,29", "℘ 1Chr 27,27", "o. am Karmel\n℘ Kap. 32,29; Jos 15,55", "℘ Pred 5,8"] },
      { number: 11, text: "Und Usija hatte ein kriegstüchtiges Heer, das in Abteilungen in den Kampf zog nach der Zahl ihrer Musterung durch den Schreiber Jeïël und den Verwalter Maaseja unter der Leitung Hananjas, eines der Obersten des Königs." },
      { number: 12, text: "Die ganze Zahl der Familienoberhäupter* der Kriegshelden* war 2 600.", footnotes: ["w. der Häupter der Väter", "o. der vermögenden Männer"] },
      { number: 13, text: "Und unter ihrer Leitung stand eine Heeresmacht von 307 500 Mann, die den Krieg mit gewaltiger Kraft führte, um dem König gegen den Feind zu helfen*.", footnotes: ["℘ Kap. 14,7"] },
      { number: 14, text: "Und Usija beschaffte ihnen, dem ganzen Heer, Schilde und Spieße und Helme und Panzer und Bogen und Schleudersteine." },
      { number: 15, text: "Und er machte in Jerusalem kunstvoll erdachte Maschinen, die auf den Türmen und auf den Mauerecken stehen sollten, um mit Pfeilen und mit großen Steinen zu schießen. Und sein Name ging aus bis in die Ferne. Denn wunderbar wurde ihm geholfen, bis er sehr mächtig war." },
      { number: 16, text: "*Und als er mächtig geworden war, wurde sein Herz hochmütig*, bis er verderblich handelte*. Und er handelte treulos gegen den HERRN, seinen Gott, und drang in den Tempel des HERRN ein, um auf dem Räucheraltar zu räuchern*.", heading: "Usijas Selbstüberhebung, Untreue und Krankheit", footnotes: ["℘ 2Kö 15,5-7", "℘ 2Kö 14,10", "℘ Kap. 12,1; 32,25", "℘ Kap. 27,2; 4Mo 17,5"] },
      { number: 17, text: "Da ging der Priester Asarja hinter ihm her und mit ihm achtzig Priester des HERRN, tüchtige Männer*.", footnotes: ["w. Söhne der Kraft"] },
      { number: 18, text: "Und sie widerstanden dem König Usija und sagten zu ihm: Nicht dir, Usija, steht es zu, dem HERRN Rauchopfer darzubringen, sondern den Priestern, den Söhnen Aarons, die geheiligt sind, Rauchopfer darzubringen*! Geh aus dem Heiligtum hinaus! Denn du hast treulos gehandelt, und es wird dir nicht zur Ehre gereichen vor Gott, dem HERRN*.", footnotes: ["℘ 2Mo 28,1; 30,7", "℘ 1Sam 2,30"] },
      { number: 19, text: "Aber Usija wurde wütend*. Und er hatte schon in seiner Hand eine Räucherpfanne, um Rauchopfer darzubringen. Und als er über die Priester wütend wurde, brach der Aussatz aus an seiner Stirn*, angesichts der Priester im Haus des HERRN neben dem Räucheraltar.", footnotes: ["℘ Kap. 16,10", "℘ 4Mo 12,10"] },
      { number: 20, text: "Und der Oberpriester* Asarja und all die Priester wandten sich ihm zu, und siehe, er war aussätzig an seiner Stirn, und sie trieben ihn schleunigst von dort weg. Und auch er selbst beeilte sich hinauszukommen, weil der HERR ihn geschlagen hatte.", footnotes: ["o. der erste Priester"] },
      { number: 21, text: "Und der König Usija war aussätzig bis zum Tag seines Todes. Und er wohnte in einem abgesonderten Haus* als Aussätziger; denn er war von dem Haus des HERRN ausgeschlossen*. Und sein Sohn Jotam war über das Haus des Königs gesetzt worden und richtete das Volk des Landes*.", footnotes: ["s. Anm. zu 2Kö 15,5", "℘ 4Mo 5,4", "℘ Kap. 27,1"] },
      { number: 22, text: "Und die übrige Geschichte* Usijas, die frühere und die spätere*, hat der Prophet Jesaja* geschrieben, der Sohn des Amoz.", footnotes: ["w. der Rest der Begebenheiten", "℘ Kap. 25,26", "℘ Kap. 32,32; 2Kö 19,2; Jes 1,1"] },
      { number: 23, text: "Und Usija legte sich zu seinen Vätern*, und man begrub ihn bei seinen Vätern auf dem Feld bei dem Grab für die Könige; denn man sagte: Er war aussätzig. Und sein Sohn Jotam wurde an seiner Stelle König*.", footnotes: ["℘ Jes 6,1", "℘ Kap. 27,1"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "*25 Jahre war Jotam alt, als er König wurde*, und er regierte sechzehn Jahre in Jerusalem; und der Name seiner Mutter war Jeruscha, die Tochter Zadoks.", heading: "Jotam von Juda", footnotes: ["℘ 2Kö 15,32-38", "℘ Kap. 26,21.23"] },
      { number: 2, text: "Und er tat, was recht war in den Augen des HERRN, nach allem, was sein Vater Usija getan hatte*. Nur ging er nicht in den Tempel des HERRN*. Aber das Volk handelte noch verderblich*.", footnotes: ["℘ Kap. 26,4", "℘ Kap. 26,16", "℘ 2Mo 32,7; Jes 1,4"] },
      { number: 3, text: "Er baute das obere Tor am Haus des HERRN*. Auch an der Mauer des Ofel* baute er viel.", footnotes: ["℘ Jer 26,10", "d. i. eine Stelle in der Stadtmauer\n℘ Kap. 33,14; Neh 3,26.27"] },
      { number: 4, text: "Er baute auch Städte im Gebirge Juda; in den Waldgebieten baute er Burgen und Türme.*", footnotes: ["℘ Kap. 17,12"] },
      { number: 5, text: "Und er kämpfte mit dem König der Söhne Ammon und überwand sie. Und die Söhne Ammon gaben ihm in jenem Jahr 100 Talente Silber und 10 000 Kor Weizen und 10 000 Kor Gerste. Die gleiche Abgabe entrichteten ihm die Söhne Ammon auch im zweiten und im dritten Jahr*.", footnotes: ["℘ Kap. 26,8"] },
      { number: 6, text: "Und Jotam erstarkte; denn er richtete seine Wege vor dem Angesicht des HERRN, seines Gottes, aus*.", footnotes: ["℘ Kap. 17,3.5"] },
      { number: 7, text: "Und die übrige Geschichte* Jotams und alle seine Kriege und seine Wege, siehe, sie sind geschrieben in dem Buch der Könige von Israel und Juda*.", footnotes: ["w. der Rest der Begebenheiten", "℘ Kap. 25,26"] },
      { number: 8, text: "25 Jahre war er alt, als er König wurde, und regierte sechzehn Jahre in Jerusalem." },
      { number: 9, text: "Und Jotam legte sich zu seinen Vätern, und man begrub ihn in der Stadt Davids. Und sein Sohn Ahas wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 28,1"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "*Zwanzig Jahre war Ahas alt, als er König wurde, und er regierte sechzehn Jahre in Jerusalem*. Und er tat nicht, was recht war in den Augen des HERRN, wie sein Vater David.", heading: "Ahas von Juda — Sein Götzendienst und seine Niederlagen — Großmütigkeit Israels gegenüber den Gefangenen von Juda", footnotes: ["℘ 2Kö 16,1-20", "℘ Kap. 27,9"] },
      { number: 2, text: "Sondern er ging auf den Wegen der Könige von Israel*. Auch machte er Gussbilder für die Baalim*.", footnotes: ["℘ Kap. 21,6", "℘ Kap. 33,3; 3Mo 19,4; Ri 2,11; Jes 2,8; Jer 1,16"] },
      { number: 3, text: "Und er war es, der im Tal Ben-Hinnom* Rauchopfer darbrachte, und er verbrannte seine Söhne im Feuer* nach den Gräueln der Nationen, die der HERR vor den Söhnen Israel vertrieben hatte*.", footnotes: ["℘ Jos 15,8", "℘ Kap. 33,6; Jer 7,31; Hes 16,21", "℘ Kap. 33,6; 36,14; 5Mo 18,9.10"] },
      { number: 4, text: "Und er brachte Schlachtopfer und Rauchopfer dar auf den Höhen* und auf den Hügeln und unter jedem grünen Baum*.", footnotes: ["℘ Kap. 15,17", "℘ V. 19; 1Kö 14,2.3; Mi 1,5"] },
      { number: 5, text: "Da gab ihn der HERR, sein Gott, in die Hand des Königs von Aram. Und sie schlugen ihn und führten ihm eine große Menge Gefangene weg und brachten sie nach Damaskus. Und auch in die Hand des Königs von Israel wurde er gegeben, der ihm eine schwere Niederlage beibrachte*.", footnotes: ["w. und er schlug ihn, einen großen Schlag\n℘ Kap. 29,9; Ri 2,14; Jes 7,1; Hes 16,57"] },
      { number: 6, text: "Und Pekach, der Sohn Remaljas, brachte in Juda an einem Tage 120 000 Mann um, alles tapfere Leute*, weil sie den HERRN, den Gott ihrer Väter, verlassen hatten*.", footnotes: ["w. Söhne der Kraft", "℘ Kap. 21,10; Ps 37,38; Jes 1,28; 3,25"] },
      { number: 7, text: "Und Sichri, ein Held von Ephraim, brachte Maaseja um, den Sohn des Königs, und Asrikam, den Vorsteher* des Hauses, und Elkana, den Zweiten nach dem König.", footnotes: ["w. den Fürsten"] },
      { number: 8, text: "Und die Söhne Israel führten von ihren Brüdern 200 000 Frauen, Söhne und Töchter gefangen weg. Auch raubten sie große Beute von ihnen und brachten die Beute nach Samaria." },
      { number: 9, text: "Und dort war ein Prophet des HERRN mit Namen Oded. Und er ging hinaus, dem Heer entgegen, das nach Samaria kam, und sagte zu ihnen: Siehe, weil der HERR, der Gott eurer Väter, über Juda wütend war*, hat er sie in eure Hand gegeben. Und ihr habt sie mit einer Wut umgebracht, die bis an den Himmel reicht*.", footnotes: ["w. Siehe, im Zorn des HERRN, des Gottes eurer Väter, gegen Juda", "℘ 1Mo 4,10; 1Chr 21,13; Esr 9,6; Jon 1,2"] },
      { number: 10, text: "Und nun gedenkt ihr, euch die Söhne Judas und Jerusalems zu Knechten und Mägden zu unterwerfen*. Sind aber nicht bei euch selbst Verschuldungen gegen den HERRN, euren Gott*?", footnotes: ["℘ 3Mo 25,39-46", "℘ Röm 2,1"] },
      { number: 11, text: "Und nun hört auf mich und schickt die Gefangenen zurück, die ihr von euren Brüdern weggeführt habt*! Denn die Zornglut des HERRN ist über euch*.", footnotes: ["℘ Jes 58,6", "℘ Jak 2,13"] },
      { number: 12, text: "Da traten Männer von den Sippenhäuptern der Söhne Ephraim, nämlich Asarja, der Sohn Johanans, Berechja, der Sohn Meschillemots, und Jehiskija, der Sohn Schallums, und Amasa, der Sohn Hadlais, vor die vom Heereszug Heimkehrenden" },
      { number: 13, text: "und sagten zu ihnen: Ihr sollt die Gefangenen nicht hierherbringen! Denn ihr habt vor*, unsere Sünden und unsere Verschuldungen zu vermehren, zusätzlich zu der Verschuldung, die auf uns liegt. Unsere Schuld ist doch schon groß, und eine Zornglut ist über Israel!*", footnotes: ["w. ihr sprecht bei euch", "℘ Kap. 24,18; 4Mo 32,14"] },
      { number: 14, text: "Da gaben die Bewaffneten die Gefangenen und die Beute vor den Obersten und der ganzen Versammlung frei." },
      { number: 15, text: "Und die Männer, die mit Namen angegeben wurden, standen auf und nahmen sich der Gefangenen an. Und alle von ihnen, die nackt waren, bekleideten sie aus der Beute. Sie bekleideten sie und gaben ihnen Schuhe und speisten und tränkten sie* und salbten sie. Und alle, die ermattet waren*, geleiteten sie auf Eseln* und brachten sie nach Jericho, der Palmenstadt*, in die Nähe ihrer Brüder. Dann kehrten sie nach Samaria zurück.", footnotes: ["℘ 2Kö 6,22.23; Spr 25,21.22", "w. die stürzten", "℘ Lk 6,27", "℘ 5Mo 34,3"] },
      { number: 16, text: "In jener Zeit sandte der König Ahas zu den Königen von Assur, dass sie ihm helfen möchten*.", footnotes: ["℘ Jes 10,20; Jer 2,18"] },
      { number: 17, text: "Die Edomiter nämlich waren abermals gekommen* und schlugen Juda und führten Gefangene weg*.", footnotes: ["℘ Kap. 21,8; 2Kö 8,22", "℘ Hes 25,12"] },
      { number: 18, text: "Und die Philister fielen ein in die Städte der Niederung* und des Südens von Juda* und nahmen Bet-Schemesch* ein und Ajalon* und Gederot* und Socho* und seine Tochterstädte und Timna* und seine Tochterstädte und Gimso und seine Tochterstädte; und sie wohnten dort.", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Gaza und Jafo", "℘ Hes 16,27; 25,15", "℘ Jos 15,10.35", "℘ Kap. 11,10", "℘ Jos 15,41", "℘ Kap. 11,7", "℘ Jos 15,10"] },
      { number: 19, text: "Denn der HERR demütigte Juda wegen des Ahas, des Königs von Israel*, weil er in Juda Zügellosigkeit zugelassen und in seiner Untreue treulos gegen den HERRN gehandelt hatte*.", footnotes: ["℘ 1Kö 14,16; 18,18", "℘ V. 1-4; Kap. 33,9; 2Mo 32,25; Spr 14,34"] },
      { number: 20, text: "Und Tiglat-Pileser, der König von Assur*, zog gegen ihn und bedrängte ihn, anstatt ihn zu unterstützen.", footnotes: ["℘ 2Kö 15,29"] },
      { number: 21, text: "Obwohl Ahas nämlich das Haus des HERRN und das Haus des Königs* und die Häuser der Obersten beraubt und alles, was er geraubt hatte, dem König von Assur gegeben hatte, wurde ihm keine Hilfe zuteil*.", footnotes: ["℘ Kap. 16,2", "℘ Spr 25,19; Jer 2,36; Hos 5,13"] },
      { number: 22, text: "Und in der Zeit seiner Bedrängnis, da handelte er noch treuloser gegen den HERRN, er, der König Ahas*.", footnotes: ["℘ Jes 1,5; Jer 5,3"] },
      { number: 23, text: "Und er opferte den Göttern von Damaskus, die ihn geschlagen hatten, und sagte: Ja, die Götter der Könige von Aram, die helfen ihnen*. Denen will ich opfern*, dann werden sie auch mir helfen*. Sie aber dienten ihm und ganz Israel zum Sturz*.", footnotes: ["℘ Jes 45,20; Jer 2,25; Hos 2,7", "℘ Kap. 25,14", "℘ Jos 15,41", "℘ Jes 1,28; Hos 13,9"] },
      { number: 24, text: "Und Ahas brachte die Geräte des Hauses Gottes zusammen und zerschlug die Geräte des Hauses Gottes. Und er schloss die Türen des Hauses des HERRN* und machte sich Altäre an allen Ecken in Jerusalem*.", footnotes: ["℘ Kap. 29,3.7.19", "℘ Kap. 30,14; 33,3-5"] },
      { number: 25, text: "Und in jeder einzelnen Stadt von Juda errichtete er Höhen*, um anderen Göttern Rauchopfer darzubringen. Und er reizte den HERRN, den Gott seiner Väter*.", footnotes: ["℘ Hes 16,24", "℘ 2Kö 22,17; Jes 14,28; Jer 11,13"] },
      { number: 26, text: "Und seine übrige Geschichte* und all seine Wege, die früheren und die späteren*, siehe, die sind geschrieben im Buch der Könige von Juda und Israel*.", footnotes: ["w. der Rest seiner Begebenheiten", "℘ Kap. 12,15", "℘ Kap. 21,20"] },
      { number: 27, text: "Und Ahas legte sich zu seinen Vätern, und man begrub ihn in der Stadt, in Jerusalem; denn man brachte ihn nicht in die Gräber der Könige von Israel. Und Hiskia*, sein Sohn, wurde an seiner Stelle König*.", footnotes: ["Mas. T.: Jehiskia; d. i. sein Name in Chronik", "℘ Kap. 29,1"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "*Hiskia* wurde König, als er 25 Jahre alt war, und er regierte 29 Jahre in Jerusalem*; und der Name seiner Mutter war Abija, die Tochter Secharjas*.", heading: "Hiskia von Juda — Ausbesserung und Einweihung des Tempels", footnotes: ["℘ V. 1-19: 2Kö 18,1-6", "Mas. T.: Jehiskia; d. i. sein Name in Chronik", "℘ Kap. 28,27", "℘ Kap. 26,5"] },
      { number: 2, text: "Und er tat, was recht war in den Augen des HERRN, nach allem, was sein Vater David getan hatte*.", footnotes: ["℘ Kap. 17,3; 26,4; 34,2"] },
      { number: 3, text: "Er war es, der gleich im ersten Jahr seiner Regierung, im ersten Monat*, die Türen des Hauses des HERRN öffnete und sie ausbesserte*.", footnotes: ["℘ 2Mo 40,2; Mt 6,33", "℘ Kap. 28,24"] },
      { number: 4, text: "Und er ließ die Priester und die Leviten kommen und versammelte sie auf dem Platz im Osten" },
      { number: 5, text: "und sagte zu ihnen: Hört mich, ihr Leviten! Heiligt euch nun* und heiligt das Haus des HERRN*, des Gottes eurer Väter, und schafft den Unflat* aus dem Heiligtum*!", footnotes: ["℘ Kap. 35,6; 1Chr 15,12; 2Kor 7,1", "℘ Hes 8,6.9", "o. die Befleckung; o. das Abscheuliche", "℘ Neh 12,30; Ps 93,5"] },
      { number: 6, text: "Denn unsere Väter haben treulos gehandelt und getan, was böse ist in den Augen des HERRN, unseres Gottes*, und haben ihn verlassen. Und sie haben ihr Gesicht von der Wohnung des HERRN abgewandt und ihr den Rücken zugekehrt*.", footnotes: ["℘ Neh 9,16.34", "℘ Jer 2,27; Hes 8,16"] },
      { number: 7, text: "Auch haben sie die Türen der Vorhalle verschlossen* und die Lampen ausgelöscht* und dem Gott Israels kein Räucherwerk dargebracht* und kein Brandopfer im Heiligtum geopfert*.", footnotes: ["℘ Kap. 28,24", "℘ 3Mo 24,4", "℘ 2Mo 30,7.8", "℘ 2Mo 29,38-42"] },
      { number: 8, text: "So ist der Zorn des HERRN über Juda und Jerusalem gekommen*, und er hat sie zum Schrecken, Entsetzen und Zischen* gemacht*, wie ihr mit euren Augen seht*.", footnotes: ["℘ Kap. 24,18", "o. Pfeifen; als Ausdruck der Verachtung oder der Furcht", "℘ 1Kö 9,8; Jer 18,16; Hes 5,15", "℘ Kap. 30,7"] },
      { number: 9, text: "Und siehe, deswegen sind unsere Väter durch das Schwert gefallen, und unsere Söhne und unsere Töchter und unsere Frauen sind in Gefangenschaft*.", footnotes: ["℘ Kap. 28,5.8.17"] },
      { number: 10, text: "Nun aber liegt es mir am Herzen, einen Bund mit dem HERRN, dem Gott Israels, zu schließen*, damit sich die Glut seines Zornes von uns abwendet*.", footnotes: ["℘ Kap. 15,12", "℘ Kap. 30,8; Jos 7,26; Jer 3,5.12"] },
      { number: 11, text: "Nun, meine Söhne, seid nicht lässig! Denn euch hat der HERR erwählt, vor ihm zu stehen* und ihm zu dienen. Ihr sollt seine Diener sein und ihm Rauchopfer darbringen*.", footnotes: ["℘ 4Mo 3,6-8", "℘ Kap. 2,5"] },
      { number: 12, text: "Da machten sich die Leviten auf: Mahat, der Sohn Amasais, und Joel, der Sohn Asarjas, von den Söhnen der Kehatiter; und von den Söhnen Meraris: Kisch, der Sohn Abdis, und Asarja, der Sohn Jehallelels; und von den Gerschonitern*: Joach, der Sohn Simmas, und Eden, der Sohn Joachs;", footnotes: ["℘ 2Mo 6,16"] },
      { number: 13, text: "und von den Söhnen Elizafans*: Schimri und Jeïël; und von den Söhnen Asafs*: Secharja und Mattanja;", footnotes: ["℘ 2Mo 6,22", "℘ 1Chr 25,1-6"] },
      { number: 14, text: "und von den Söhnen Heman*: Jehiël und Schimi; und von den Söhnen Jedutun*: Schemaja und Usiël.", footnotes: ["℘ 1Chr 25,1-6", "℘ 1Chr 25,1-6"] },
      { number: 15, text: "Und sie versammelten ihre Brüder und heiligten sich*. Und sie kamen nach dem Befehl des Königs, den Worten des HERRN gemäß, um das Haus des HERRN zu reinigen.", footnotes: ["℘ Kap. 5,11"] },
      { number: 16, text: "Und die Priester gingen in das Innere des Hauses des HERRN, um es zu reinigen. Und sie brachten alles Unreine, das sie in dem Tempel des HERRN fanden, in den Hof des Hauses des HERRN hinaus. Und die Leviten nahmen es in Empfang, um es an den Bach Kidron hinauszubringen*.", footnotes: ["℘ Kap. 15,16; Neh 13,9"] },
      { number: 17, text: "Und sie fingen am Ersten des ersten Monats an, das Haus zu heiligen; und am achten Tag des Monats kamen sie zur Vorhalle des HERRN*. Und sie heiligten das Haus des HERRN acht Tage lang; und am sechzehnten Tag des ersten Monats waren sie fertig.", footnotes: ["℘ Kap. 3,4"] },
      { number: 18, text: "Und sie gingen zum König Hiskia hinein und sagten: Wir haben das ganze Haus des HERRN gereinigt und den Brandopferaltar und all seine Geräte und den Tisch der Schaubrote* und all seine Geräte*.", footnotes: ["w. den Tisch der Schicht", "℘ Kap. 4,1.8"] },
      { number: 19, text: "Und alle Geräte, die der König Ahas während seiner Regierung* in seiner Untreue entweiht hat*, haben wir hergerichtet und geheiligt; und siehe, sie sind vor dem Altar des HERRN. —", footnotes: ["w. Königsherrschaft", "o. für verworfen erklärt hat\n℘ Kap. 28,24; 2Kö 16,14.17"] },
      { number: 20, text: "Und der König Hiskia machte sich früh auf* und versammelte die Obersten der Stadt, und er ging hinauf in das Haus des HERRN.", footnotes: ["℘ 1Mo 21,14"] },
      { number: 21, text: "Und sie brachten sieben Stiere und sieben Widder und sieben Schafe und sieben Ziegenböcke als Sündopfer für das Königtum und für das Heiligtum und für Juda. Und er befahl den Söhnen Aarons, den Priestern, sie auf dem Altar des HERRN zu opfern." },
      { number: 22, text: "Und sie schlachteten die Rinder, und die Priester nahmen das Blut in Empfang und sprengten es an den Altar*; und sie schlachteten die Widder und sprengten das Blut an den Altar; und sie schlachteten die Schafe und sprengten das Blut an den Altar.", footnotes: ["℘ 3Mo 4,18"] },
      { number: 23, text: "Und sie brachten die Ziegenböcke* für das Sündopfer herbei vor den König und die Versammlung, und sie legten ihre Hände auf sie*.", footnotes: ["w. Haarigen", "℘ 3Mo 4,24"] },
      { number: 24, text: "Und die Priester schlachteten sie und brachten ihr Blut als Sündopfer an den Altar, um für ganz Israel Sühnung zu erwirken; denn für ganz Israel hatte der König das Brandopfer und das Sündopfer befohlen*.", footnotes: ["℘ Kap. 30,1; 3Mo 9,15; Esr 6,17"] },
      { number: 25, text: "Und er stellte die Leviten auf im Haus des HERRN, mit Zimbeln, mit Harfen und mit Zithern*, nach dem Befehl Davids* und Gads, des Sehers des Königs*, und des Propheten Nathan; denn der Befehl war durch den HERRN, durch seine Propheten ergangen*.", footnotes: ["℘ Neh 12,27", "℘ Kap. 8,14", "℘ 1Chr 21,9", "℘ 2Sam 7,2"] },
      { number: 26, text: "Und so standen die Leviten da mit den Instrumenten Davids* und die Priester mit den Trompeten.", footnotes: ["℘ 1Chr 23,5; Am 6,5"] },
      { number: 27, text: "Und Hiskia befahl, das Brandopfer auf dem Altar zu opfern. Und zur Zeit, als das Brandopfer begann, begann der Gesang für den HERRN* und auch die Trompeten, und zwar unter Begleitung der Instrumente Davids, des Königs von Israel*.", footnotes: ["o. begannen die Jahwelieder", "℘ Kap. 7,6; 30,21"] },
      { number: 28, text: "Und die ganze Versammlung betete an*, und der Gesang erscholl, und die Trompeten schmetterten. All das dauerte bis zur Vollendung des Brandopfers.", footnotes: ["℘ Kap. 7,3; Ps 95,6; 96,9"] },
      { number: 29, text: "Und als man das Brandopfer vollständig dargebracht hatte, knieten der König und alle, die sich bei ihm befanden, nieder und beteten an*.", footnotes: ["℘ Kap. 7,3; Ps 95,6; 96,9"] },
      { number: 30, text: "Und der König Hiskia und die Obersten sagten zu den Leviten, dass sie dem HERRN lobsingen sollten mit den Worten Davids und des Sehers Asaf*. Und sie lobsangen mit Freude* und neigten sich und beteten an*.", footnotes: ["℘ Ps 50,1", "℘ Kap. 23,18; 30,21.24; Esr 6,16.22; Ps 100,2", "℘ Kap. 7,3; Ps 95,6; 96,9"] },
      { number: 31, text: "Und Hiskia hob an und sagte: Nun habt ihr euch dem HERRN geweiht*. Tretet herzu und bringt Schlachtopfer und Dankopfer* zum Haus des HERRN! Und die Versammlung brachte Schlachtopfer und Dankopfer*, und jeder, der willigen Herzens war, brachte Brandopfer dar.", footnotes: ["w. habt ihr eure Hand für den HERRN gefüllt", "o. Lobopfer\n℘ 3Mo 7,11-15; Hebr 13,15", "o. Lobopfer"] },
      { number: 32, text: "Und die Zahl der Brandopfer, die die Versammlung darbrachte, war siebzig Rinder, hundert Widder, zweihundert Schafe, diese alle als Brandopfer für den HERRN*.", footnotes: ["℘ Kap. 30,15; 3Mo 1"] },
      { number: 33, text: "Und die heiligen Gaben* betrugen sechshundert Rinder und dreitausend Schafe.", footnotes: ["o. heiligen Dinge"] },
      { number: 34, text: "Es waren zu wenig Priester vorhanden, so dass sie nicht allen Brandopfern die Haut abziehen konnten. Daher unterstützten ihre Brüder, die Leviten*, sie, bis das Werk vollendet war und bis die Priester sich geheiligt hatten. Denn die Leviten waren mit redlichem Herzen bemüht, sich zu heiligen, mehr als die Priester*.", footnotes: ["℘ Kap. 35,11", "℘ Kap. 30,3.15"] },
      { number: 35, text: "Auch gab es Brandopfer in Menge mit den Fettstücken der Heilsopfer* und den Trankopfern zu den Brandopfern*. — Und so wurde der Dienst am Haus des HERRN geordnet.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ 3Mo 3,16.17", "℘ 4Mo 15,5-10"] },
      { number: 36, text: "Und Hiskia und das ganze Volk freuten sich über das, was Gott dem Volk bereitet hatte; denn die Sache war sehr schnell* geschehen.", footnotes: ["o. überraschend"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Und Hiskia sandte hin zu ganz Israel und Juda und schrieb auch Briefe an Ephraim und Manasse*, dass sie zum Haus des HERRN nach Jerusalem kommen möchten, um dem HERRN, dem Gott Israels, Passah zu feiern.", heading: "Hiskias Feier des Passah", footnotes: ["℘ Kap. 29,24"] },
      { number: 2, text: "Und der König und seine Obersten und die ganze Versammlung in Jerusalem beschlossen, das Passah im zweiten Monat zu feiern*.", footnotes: ["℘ V. 15; Kap. 35,1; 4Mo 9,10.11; 2Kö 23,22"] },
      { number: 3, text: "Denn sie konnten es nicht zur rechten Zeit* feiern, weil die Priester sich nicht in hinreichender Anzahl geheiligt hatten* und das Volk noch nicht in Jerusalem versammelt war.", footnotes: ["w. zu dieser Zeit", "℘ Kap. 29,34"] },
      { number: 4, text: "Und die Sache war recht in den Augen des Königs und in den Augen der ganzen Versammlung." },
      { number: 5, text: "Und sie fassten den Beschluss, eine Einladung* ergehen zu lassen durch ganz Israel, von Beerscheba bis Dan*, dass sie kämen, um dem HERRN, dem Gott Israels, Passah zu feiern in Jerusalem. Denn sie hatten es lange Zeit nicht so gefeiert, wie es vorgeschrieben war*.", footnotes: ["w. eine Stimme", "℘ Ri 20,1", "o. Denn sie hatten es nicht in der Größe gefeiert, wie es vorgeschrieben war"] },
      { number: 6, text: "Und die Läufer gingen mit den Briefen von der Hand des Königs und seiner Obersten durch ganz Israel und Juda, und zwar nach dem Befehl des Königs, um zu sagen: Söhne Israel, kehrt um zu dem HERRN*, dem Gott Abrahams, Isaaks und Israels*! Dann wird er umkehren zu den Entkommenen, die euch aus der Gewalt* der Könige von Assur übrig geblieben sind*.", footnotes: ["℘ Jes 55,7; Jer 3,14; Kla 3,40; Hos 6,1; Joe 2,12; Sach 1,3.4", "℘ 1Kö 18,36; 1Chr 29,18", "w. Hand", "℘ 1Chr 5,26"] },
      { number: 7, text: "Und seid nicht wie eure Väter* und wie eure Brüder, die treulos gehandelt haben gegen den HERRN, den Gott ihrer Väter, so dass er sie zum Entsetzen dahingegeben hat, wie ihr es seht*!", footnotes: ["℘ Hes 20,30", "℘ Kap. 26,18; 29,8"] },
      { number: 8, text: "Nun verhärtet euren Nacken nicht* wie eure Väter*! Gebt dem HERRN die Hand und kommt zu seinem Heiligtum, das er für ewig geheiligt hat*, und dient dem HERRN, eurem Gott, damit die Glut seines Zornes sich von euch wendet*!", footnotes: ["℘ 5Mo 10,16", "℘ 2Mo 32,9", "℘ Kap. 7,16", "℘ Kap. 29,10; Esr 10,14"] },
      { number: 9, text: "Denn wenn ihr zu dem HERRN umkehrt, dann werden eure Brüder und eure Kinder Barmherzigkeit finden bei denen, die sie gefangen weggeführt haben; und sie werden in dieses Land zurückkehren*. Denn gnädig und barmherzig ist der HERR, euer Gott*, und er wird das Angesicht nicht von euch abwenden, wenn ihr zu ihm umkehrt. —", footnotes: ["℘ 5Mo 30,1-5; 1Kö 8,50", "℘ 2Mo 34,6; Neh 9,31; Ps 111,4"] },
      { number: 10, text: "Und die Läufer zogen von Stadt zu Stadt durch das Land Ephraim und Manasse und bis nach Sebulon; aber man verlachte und verspottete sie*.", footnotes: ["℘ Kap. 36,16; Apg 2,13"] },
      { number: 11, text: "Nur einige Männer von Asser und Manasse und von Sebulon demütigten sich und kamen nach Jerusalem*.", footnotes: ["℘ Kap. 11,16; 1Chr 9,3"] },
      { number: 12, text: "Auch über Juda kam die Hand Gottes, dass er ihnen ein einmütiges Herz gab*, den Befehl des Königs und der Obersten auszuführen nach dem Wort des HERRN.", footnotes: ["℘ Jer 32,39"] },
      { number: 13, text: "So versammelte sich eine Menge Volk in Jerusalem, um das Fest der ungesäuerten Brote im zweiten Monat zu feiern*, eine sehr große Versammlung.", footnotes: ["℘ V. 15; Kap. 35,1; 4Mo 9,10.11; 2Kö 23,22"] },
      { number: 14, text: "Und sie machten sich auf und schafften die Altäre weg, die in Jerusalem waren*. Auch alle Räucheraltäre schafften sie weg und warfen sie in den Bach Kidron*.", footnotes: ["℘ Kap. 28,24", "℘ Kap. 15,16; 32,12; 34,3.4; Jes 36,7"] },
      { number: 15, text: "Und man schlachtete das Passah am Vierzehnten des zweiten Monats*. Die Priester und die Leviten aber hatten sich geschämt und hatten sich geheiligt*; und sie brachten Brandopfer in das Haus des HERRN*.", footnotes: ["℘ V. 2", "℘ V. 24; Kap. 29,34; 35,6; Esr 6,20", "℘ Kap. 29,32"] },
      { number: 16, text: "Und die standen an ihrem Standort nach ihrer Vorschrift, nach dem Gesetz des Mose, des Mannes Gottes*. Die Priester sprengten das Blut, das sie aus der Hand der Leviten entgegennahmen*.", footnotes: ["℘ 1Chr 23,14", "℘ Kap. 35,11"] },
      { number: 17, text: "Denn es waren viele in der Versammlung, die sich nicht geheiligt hatten. Daher besorgten die Leviten das Schlachten* der Passahopfer für jeden, der nicht rein war, um sie dem HERRN zu heiligen*.", footnotes: ["℘ Hes 44,11", "℘ Joh 11,55"] },
      { number: 18, text: "Denn ein großer Teil des Volkes, viele von Ephraim und Manasse, Issaschar und Sebulon hatten sich nicht gereinigt und aßen das Passah nicht so, wie es vorgeschrieben ist*. Doch Hiskia bat für sie* und sprach: Der HERR, der Gütige, möge jedem vergeben*,", footnotes: ["℘ 4Mo 9,7", "℘ 1Mo 20,7", "℘ 2Kö 5,18; Joh 18,28"] },
      { number: 19, text: "der sein Herz darauf gerichtet hat, Gott zu suchen*, den HERRN, den Gott seiner Väter, auch wenn er nicht der Reinheit des Heiligtums entspricht!", footnotes: ["℘ Kap. 20,33; Esr 6,21"] },
      { number: 20, text: "Und der HERR erhörte Hiskia und heilte das Volk*. —", footnotes: ["℘ 1Jo 5,16"] },
      { number: 21, text: "Und die Söhne Israel, die sich in Jerusalem befanden, feierten das Fest der ungesäuerten Brote sieben Tage lang* mit großer Freude*. Und die Leviten und die Priester lobten den HERRN Tag für Tag mit den Instrumenten des Lobes der Macht des HERRN*.", footnotes: ["℘ Kap. 35,17; 2Mo 12,15", "℘ Kap. 29,30.36; Neh 8,17", "℘ Kap. 29,25-28"] },
      { number: 22, text: "Und Hiskia redete zum Herzen* aller Leviten, die so gute Einsicht im Blick auf den HERRN bewiesen hatten*. Und sie aßen das Festopfer die sieben Tage hindurch*, indem sie Heilsopfer* opferten und den HERRN, den Gott ihrer Väter, priesen.", footnotes: ["℘ Kap. 32,6; 1Mo 50,21", "℘ 5Mo 33,10", "LXX: beendeten das Fest, die sieben Tage", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 23, text: "Und die ganze Versammlung beschloss, noch sieben weitere Tage zu feiern*; und sie feierten die sieben Tage mit Freuden*.", footnotes: ["℘ 1Kö 8,65", "℘ Kap. 29,30.36; Neh 8,17"] },
      { number: 24, text: "Denn Hiskia, der König von Juda, spendete* für die Versammlung 1 000 Stiere und 7 000 Schafe; und die Obersten spendeten* für die Versammlung 1 000 Stiere und 10 000 Schafe*. Und die Priester hatten sich in großer Menge geheiligt*.", footnotes: ["o. hob ab als Opfergabe", "o. hoben ab als Opfergabe", "℘ Kap. 35,7-9; 2Sam 6,19", "℘ V. 15"] },
      { number: 25, text: "Und so freute sich die ganze Versammlung von Juda und die Priester und die Leviten und die ganze Versammlung, die von Israel gekommen war, und die Fremden, die aus dem Land Israel gekommen waren*, und die, die in Juda wohnten.", footnotes: ["℘ V. 11.18; Kap. 2,16"] },
      { number: 26, text: "Und es war große Freude in Jerusalem*. Denn seit den Tagen Salomos, des Sohnes Davids, des Königs von Israel, war Derartiges in Jerusalem nicht gewesen*.", footnotes: ["℘ Kap. 29,30.36; Neh 8,17", "℘ Kap. 35,18"] },
      { number: 27, text: "Und die Priester, die Leviten, standen auf und segneten das Volk*. Und ihre Stimme wurde erhört, und ihr Gebet kam zu seiner heiligen Wohnung in den Himmel*.", footnotes: ["℘ 2Mo 39,43; 4Mo 6,23", "℘ Kap. 6,21"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Und als sie das alles vollendet hatten, zogen alle Israeliten, die sich dort befanden, hinaus zu den Städten Judas. Und sie zerschlugen die Gedenksteine* und hieben die Ascherim um und rissen die Opferhöhen nieder und die Altäre in ganz Juda und Benjamin und in Ephraim und Manasse, bis sie damit fertig waren*. Und alle Söhne Israel kehrten in ihre Städte zurück, jeder zu seinem Besitz.", heading: "Abschaffung des Götzendienstes — Versorgung der Priester und Leviten", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "℘ Kap. 14,2; 32,12; 33,3; 34,4.6; Jes 17,8"] },
      { number: 2, text: "Und Hiskia stellte die Abteilungen der Priester und der Leviten nach ihren Abteilungen auf, jeden seinem Dienst entsprechend, sowohl die Priester als auch die Leviten*, für die Brandopfer und für die Heilsopfer*, zum Dienen und zum Preisen und zum Loben in den Toren der Lager des HERRN*.", footnotes: ["℘ Kap. 35,2; 1Chr 23,6; 24; 25; 26", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 24,14"] },
      { number: 3, text: "Und ein Anteil des Königs von seinem Vermögen wurde für die Brandopfer gegeben, für die Morgen- und die Abendbrandopfer und für die Brandopfer an den Sabbaten und an den Neumonden und an den Festzeiten, wie es im Gesetz des HERRN vorgeschrieben ist*.", footnotes: ["℘ 4Mo 28; 29"] },
      { number: 4, text: "Und er befahl dem Volk, den Bewohnern von Jerusalem, den Anteil, der den Priestern und den Leviten zustand, zu geben*, damit sie am Gesetz des HERRN festhalten könnten*.", footnotes: ["℘ Mal 3,10", "℘ Neh 13,10-12"] },
      { number: 5, text: "Und als das Wort bekannt wurde*, brachten die Söhne Israel reichlich Erstlingsgaben vom Getreide, Most und Öl und Honig und von allem Ertrag des Feldes*; und den Zehnten von allem brachten sie in Menge.", footnotes: ["w. sich ausbreitete", "℘ 4Mo 18,8-24; Neh 10,36-38"] },
      { number: 6, text: "Und die Söhne Israel und Juda, die in den Städten Judas wohnten, brachten ebenfalls den Zehnten von Rindern und Schafen und den Zehnten von den heiligen Gaben, die dem HERRN, ihrem Gott, geheiligt waren, und sie legten Haufen an Haufen hin*.", footnotes: ["℘ 3Mo 27,30.32; Hebr 7,5"] },
      { number: 7, text: "Im dritten Monat fingen sie an, die Haufen aufzuschichten, und im siebten Monat waren sie damit fertig." },
      { number: 8, text: "Und Hiskia und die Obersten kamen und besichtigten die Haufen, und sie priesen* den HERRN* und sein Volk Israel.", footnotes: ["o. segneten", "℘ 1Chr 29,9-14; 2Kor 9,12"] },
      { number: 9, text: "Und Hiskia befragte die Priester und die Leviten wegen der Haufen." },
      { number: 10, text: "Da sprach Asarja, der Oberpriester*, vom Haus Zadok*, zu ihm und sagte: Seitdem man angefangen hat, das Hebopfer in das Haus des HERRN zu bringen, haben wir gegessen und sind satt geworden und haben viel übrig behalten; denn der HERR hat sein Volk gesegnet*. Und diese Menge haben wir übrig*.", footnotes: ["o. der erste Priester", "℘ 1Chr 5,34-40", "℘ 4Mo 22,12", "℘ 2Mo 36,7; Spr 3,9.10; 11,24; Hes 44,30; Mal 3,10; 2Kor 9,6"] },
      { number: 11, text: "Und Hiskia befahl, Vorratskammern* im Haus des HERRN herzurichten; und sie richteten sie her*.", footnotes: ["o. Zellen", "℘ Neh 13,5"] },
      { number: 12, text: "Und sie brachten das Hebopfer und den Zehnten und die heiligen Gaben* gewissenhaft* hinein. Und Oberaufseher* über sie war Konanja, der Levit, und sein Bruder Schimi, als Zweiter.", footnotes: ["o. heiligen Dinge", "w. in Treue", "w. Fürst\n℘ 1Chr 26,20-26; Neh 10,39.40"] },
      { number: 13, text: "Und Jehiël und Asasja und Nahat und Asaël und Jerimot und Josabad und Eliël und Jismachja und Mahat und Benaja waren Aufseher unter Konanja und seinem Bruder Schimi auf Anweisung des Königs Hiskia und Asarjas, des Oberaufsehers* im Haus Gottes*.", footnotes: ["w. des Fürsten", "℘ Kap. 35,8; 1Chr 9,11; Neh 11,11"] },
      { number: 14, text: "Und der Levit Kore, der Sohn des Jimna, der Torhüter im Osttor, war über die freiwilligen Gaben für Gott eingesetzt, damit er das Hebopfer für den HERRN und das Hochheilige ausgäbe*.", footnotes: ["o. damit man das Hebopfer für den HERRN und das Hochheilige abgäbe"] },
      { number: 15, text: "Und unter seiner Hand waren Eden und Minjamin und Jeschua und Schemaja, Amarja und Schechanja in den Städten der Priester*, um ihren Brüdern nach ihren Abteilungen gewissenhaft* ihren Anteil zu geben, dem Größten wie dem Kleinsten*.", footnotes: ["℘ Jos 21,9-19", "w. in Treue", "℘ 1Chr 24,31"] },
      { number: 16, text: "Außerdem hatte man von ihnen Geschlechtsregister angelegt, die die männlichen Personen von drei Jahren an und darüber erfassten, alle, die in das Haus des HERRN kamen nach der täglichen Ordnung, um ihren Dienst in ihren Ämtern, nach ihren Abteilungen zu verrichten." },
      { number: 17, text: "Was das Geschlechtsregister betrifft, so waren die Priester nach ihren Vaterhäusern und die Leviten von zwanzig Jahren an und darüber* in ihren Ämtern, nach ihren Abteilungen darin registriert*.", footnotes: ["℘ 4Mo 4,3", "℘ 1Chr 23,24-27"] },
      { number: 18, text: "Und für die Registrierung wurden sie mit all ihren kleinen Kindern, ihren Frauen und ihren Söhnen und ihren Töchtern erfasst, die ganze Versammlung. Denn gewissenhaft* heiligten sie sich für das Heilige.", footnotes: ["w. Denn in ihrer Treue"] },
      { number: 19, text: "Und für die Söhne Aarons, die Priester*, die in den Weidegebieten ihrer Städte wohnten, waren in jeder einzelnen Stadt Männer angestellt, die mit Namen bestimmt waren, um jedem Männlichen unter den Priestern und jedem ins Geschlechtsregister Eingetragenen unter den Leviten ihre Anteile zu geben*.", footnotes: ["o. von den Söhnen Aarons, den Priestern", "℘ 3Mo 25,32-34"] },
      { number: 20, text: "So machte es Hiskia in ganz Juda. Und er tat, was gut und recht und treu* war vor dem HERRN, seinem Gott*.", footnotes: ["o. wahr", "℘ Kap. 14,1; 2Kö 20,3; Jes 16,5"] },
      { number: 21, text: "Und bei jedem Werk, das er im Dienst für das Haus Gottes und im Gesetz und im Gebot begann, um seinen Gott zu suchen*, handelte er mit ganzem Herzen*; und er hatte Gelingen*.", footnotes: ["℘ Kap. 14,6", "℘ Ps 119,2", "℘ 2Kö 18,7; Mt 6,33"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "*Nach diesen Ereignissen und dieser Treue* kam Sanherib, der König von Assur. Und er drang in Juda ein und belagerte die befestigten Städte, und er gedachte, sie für sich zu erobern*.", heading: "Belagerung Jerusalems durch die Assyrer — Seine Befreiung", footnotes: ["℘ 2Kö 18,13-37; 19; Jes 36; 37", "℘ Kap. 35,20; Hebr 6,10", "w. aufzubrechen"] },
      { number: 2, text: "Und als Hiskia sah, dass Sanherib gekommen und dass sein Gesicht zum Kampf gegen Jerusalem gerichtet war*,", footnotes: ["℘ Jes 10,32"] },
      { number: 3, text: "da beriet er sich mit seinen Obersten und seinen Helden, ob sie die Wasser der Quellen, die außerhalb der Stadt lagen*, verstopfen* sollten. Und sie unterstützten ihn.", footnotes: ["℘ 2Kö 20,20", "o. verdecken; o. unkenntlich machen"] },
      { number: 4, text: "Und es versammelte sich viel Volk, und sie verstopften* alle Quellen und den Bach*, der im Innern der Erde fließt*. Denn sie sagten: Warum sollen die Könige von Assur kommen und viel Wasser finden?", footnotes: ["o. verdeckten; o. machten unkenntlich", "℘ V. 30", "o. der mitten durchs Land fließt"] },
      { number: 5, text: "Und er fasste Mut und baute die ganze Mauer, wo sie eingerissen war, wieder auf und errichtete auf ihr Türme* und baute die andere Mauer außerhalb* und befestigte den Millo* der Stadt Davids*; und er fertigte Waffen in Menge an und Schilde.", footnotes: ["so mit der aram. Üs.; Mas. T.: und er stieg auf die Türme\n℘ Kap. 33,14; Jes 22,9.10", "℘ Jer 39,4", "d. h. Aufschüttung; der Millo diente zur Befestigung der Stadt", "℘ 2Sam 5,9"] },
      { number: 6, text: "Auch setzte er Kriegsoberste über das Volk. Und er versammelte sie zu sich auf dem Platz am Stadttor und redete zu ihren Herzen* und sagte:", footnotes: ["℘ Kap. 30,22"] },
      { number: 7, text: "Seid stark und mutig*! Fürchtet euch nicht und seid nicht niedergeschlagen vor dem König von Assur und vor der ganzen Menge, die mit ihm ist!* Denn mit uns sind mehr als mit ihm*.", footnotes: ["℘ Kap. 15,7", "℘ Kap. 20,15; Neh 4,8", "o. Denn mit uns ist ein Größerer als mit ihm\n℘ 2Kö 6,16; 1Jo 4,4"] },
      { number: 8, text: "Mit ihm ist ein Arm aus Fleisch*. Aber mit uns ist der HERR, unser Gott*, um uns zu helfen und unsere Kriege zu führen*! Und das Volk verließ sich auf die Worte Hiskias, des Königs von Juda*.", footnotes: ["℘ Jes 31,3; Jer 17,5", "℘ Kap. 13,12; 2Kö 18,5", "℘ Kap. 14,10; 5Mo 20,3.4; Jes 30,32", "℘ 2Mo 4,31"] },
      { number: 9, text: "Danach sandte Sanherib, der König von Assur, seine Knechte nach Jerusalem — er war aber noch vor Lachisch* und seine ganze Streitmacht mit ihm — zu Hiskia, dem König von Juda, und zu ganz Juda, das in Jerusalem war, und ließ ihnen sagen:", footnotes: ["℘ Kap. 11,9"] },
      { number: 10, text: "So spricht Sanherib, der König von Assur: Worauf vertraut ihr, dass ihr in der Belagerung in Jerusalem aushalten wollt*?", footnotes: ["o. dass ihr in der befestigten Stadt, in Jerusalem, bleibt"] },
      { number: 11, text: "Verführt euch Hiskia nicht, um euch dem Tod durch Hunger und Durst preiszugeben, wenn er sagt: Der HERR, unser Gott, wird uns aus der Hand des Königs von Assur retten?" },
      { number: 12, text: "Ist es nicht Hiskia, der seine Höhen und seine Altäre beseitigt hat, als er zu Juda und zu Jerusalem gesagt hat: Vor einem Altar sollt ihr euch niederwerfen, und auf ihm sollt ihr Rauchopfer darbringen?*", footnotes: ["℘ Kap. 30,14; 31,1"] },
      { number: 13, text: "Erkennt ihr nicht, was ich und meine Väter allen Völkern der Länder getan haben? Konnten etwa die Götter der Nationen der Länder ihr Land aus meiner Hand retten?*", footnotes: ["℘ Jes 10,10.11.14"] },
      { number: 14, text: "Wer ist unter allen Göttern dieser Nationen, an denen meine Väter den Bann vollstreckt haben, der sein Volk aus meiner Hand hat retten können, so dass euer Gott euch aus meiner Hand retten könnte*?", footnotes: ["℘ Jes 10,10.11.14"] },
      { number: 15, text: "Und nun, lasst euch von Hiskia nicht täuschen und lasst euch nicht auf diese Weise verführen! Glaubt ihm nicht! Denn kein Gott irgendeiner Nation oder irgendeines Königreiches hat sein Volk aus meiner Hand und aus der Hand meiner Väter retten können. Wie viel weniger wird euer Gott euch aus meiner Hand retten!" },
      { number: 16, text: "Und noch mehr redeten seine Knechte gegen Gott, den HERRN, und gegen seinen Knecht Hiskia." },
      { number: 17, text: "Auch schrieb er einen Brief*, um den HERRN, den Gott Israels, zu verhöhnen* und gegen ihn zu reden, indem er behauptete: Wie die Götter der Nationen der Länder, die ihr Volk nicht aus meiner Hand gerettet haben, so wird auch der Gott Hiskias sein Volk nicht aus meiner Hand retten*.", footnotes: ["w. Briefe", "℘ 1Sam 17,36", "℘ 2Kö 19,11"] },
      { number: 18, text: "Und sie riefen dem Volk von Jerusalem, das auf der Mauer war, mit lauter Stimme auf Judäisch zu, um sie zu schrecken und bestürzt zu machen, damit sie die Stadt einnehmen könnten*.", footnotes: ["℘ Neh 6,9"] },
      { number: 19, text: "Und sie redeten von dem Gott Jerusalems wie von den Göttern der Völker der Erde*, die doch Machwerk von Menschenhänden sind*.", footnotes: ["℘ 1Kö 20,28", "℘ Ps 74,18; 115,4; Hes 25,8"] },
      { number: 20, text: "Und der König Hiskia und der Prophet Jesaja, der Sohn des Amoz, beteten deswegen und schrien zum Himmel um Hilfe*.", footnotes: ["℘ Kap. 13,14; 14,10; Mt 18,19"] },
      { number: 21, text: "Da sandte der HERR einen Engel, der jeden tapferen Helden und Fürsten und Obersten im Lager des Königs von Assur vertilgte*. Und dieser zog, mit Schanden bedeckt*, in sein Land zurück. Und als er in das Haus seines Gottes ging, brachten ihn dort seine Söhne* durch das Schwert zu Fall.", footnotes: ["℘ Ps 76,6; Jes 14,25; 29,8; Jer 21,2", "w. mit Schande des Gesichts", "w. die aus seinem Leib hervorgegangen waren"] },
      { number: 22, text: "So rettete der HERR Hiskia und die Bewohner von Jerusalem aus der Hand Sanheribs, des Königs von Assur, und aus der Hand aller Feinde*; und er gab ihnen Ruhe ringsumher*.", footnotes: ["so mit mehreren hebr. Handschr.; Mas. T.: aus der Hand aller", "so mit LXX und Vulg.; Mas. T.: und er geleitete sie ringsum\n℘ Ps 37,39"] },
      { number: 23, text: "Und viele brachten Gaben für den HERRN nach Jerusalem* und Kostbarkeiten für Hiskia, den König von Juda*; und er war seitdem hoch angesehen in den Augen aller Nationen*.", footnotes: ["℘ Esr 7,15", "℘ Kap. 17,5.11", "℘ Kap. 1,1"] },
      { number: 24, text: "*In jenen Tagen wurde Hiskia todkrank; und er betete zu dem HERRN. Und der HERR* redete zu ihm und gab ihm ein Wunderzeichen*.", heading: "Hiskias Krankheit und Genesung — Gesandtschaft von Babel — Seine gesegnete Regierung", footnotes: ["℘ 2Kö 20; Jes 38; 39", "w. er", "o. Wahrzeichen"] },
      { number: 25, text: "Aber Hiskia vergalt nicht die Wohltat, die an ihm erwiesen worden war, denn sein Herz wurde hochmütig*. Und es kam ein Zorn Gottes über ihn und über Juda und Jerusalem*.", footnotes: ["℘ Kap. 26,16; Dan 5,20", "℘ Kap. 24,18; 2Sam 24,1"] },
      { number: 26, text: "Da demütigte sich Hiskia wegen des Hochmutes seines Herzens, er und die Bewohner von Jerusalem*; und der Zorn des HERRN kam nicht über sie in den Tagen Hiskias*.", footnotes: ["℘ 2Kö 22,19; Jer 26,19", "℘ Kap. 12,7; 34,28"] },
      { number: 27, text: "Und Hiskia hatte sehr viel Reichtum und Ehre*. Und er machte sich Schatzkammern für Silber und Gold und Edelsteine und für Balsamöle und für Schilde und für allerlei kostbare Geräte", footnotes: ["℘ Kap. 17,5; 1Sam 2,7; 1Chr 29,28; Spr 10,22"] },
      { number: 28, text: "und Vorratshäuser für den Ertrag an Getreide und Most und Öl und Ställe für allerlei Vieh und Ställe für die Herden*.", footnotes: ["so mit LXX und Vulg.; Mas. T.: Herden für die Ställe"] },
      { number: 29, text: "Und er legte sich Städte an und Besitz von* Schafen und Rindern in Menge*; denn Gott gab ihm ein sehr großes Vermögen*.", footnotes: ["Andere üs. mit Textänderung: er schaffte sich Herden und Besitz an", "℘ Kap. 26,10", "℘ Kap. 17,5; 1Sam 2,7; 1Chr 29,28; Spr 10,22"] },
      { number: 30, text: "Und er, Hiskia, verstopfte* den oberen Abfluss des Wassers des Gihon* und leitete es unterirdisch* nach Westen in die Stadt Davids*. Und Hiskia hatte Gelingen in all seinem Tun*.", footnotes: ["o. verdeckte; o. machte unkenntlich", "℘ Kap. 33,14", "o. abwärts", "℘ V. 3.4", "℘ Kap. 26,5"] },
      { number: 31, text: "So war es auch bei den Gesandten der Obersten von Babel, die zu ihm gesandt hatten, um nach dem Wunderzeichen* zu fragen, das im Land geschehen war*. Da ließ Gott ihn allein*, um ihn zu prüfen, damit er alles erkannte, was in seinem Herzen war*.", footnotes: ["o. Wahrzeichen", "℘ Jes 39,1", "o. ließ Gott ihn gewähren", "℘ 5Mo 8,2"] },
      { number: 32, text: "Und die übrige Geschichte* Hiskias und seine guten Taten*, siehe, sie sind geschrieben in dem Buch der Vision des Propheten Jesaja*, des Sohnes des Amoz, in dem Buch der Könige von Juda und Israel*.", footnotes: ["w. der Rest der Begebenheiten", "o. seine Treuebeweise; o. Gnadenerweise\n℘ Kap. 35,26", "℘ Kap. 26,22; Jes 36-39", "℘ Kap. 25,26"] },
      { number: 33, text: "Und Hiskia legte sich zu seinen Vätern, und man begrub ihn bei dem Aufgang zu den Gräbern der Söhne Davids. Und ganz Juda und die Bewohner von Jerusalem erwiesen ihm Ehre bei seinem Tod*. Und sein Sohn Manasse wurde König an seiner Stelle*.", footnotes: ["℘ Kap. 16,14; 35,24.25", "℘ Kap. 33,1"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "*Zwölf Jahre war Manasse alt, als er König wurde, und er regierte 55 Jahre in Jerusalem*.", heading: "Manasse von Juda — Sein Götzendienst, seine Bestrafung und Buße", footnotes: ["℘ 2Kö 21,1-18", "℘ Kap. 32,33"] },
      { number: 2, text: "Und er tat, was böse war in den Augen des HERRN, nach den Gräueln der Nationen, die der HERR vor den Söhnen Israel vertrieben hatte*.", footnotes: ["℘ 3Mo 18,24.26; 5Mo 12,29.31"] },
      { number: 3, text: "Und er baute die Höhen wieder auf, die sein Vater Hiskia niedergerissen hatte*, und errichtete Altäre* für die Baalim und machte Ascheren* und warf sich nieder vor dem ganzen Heer des Himmels und diente ihnen*.", footnotes: ["℘ Kap. 31,1", "℘ Kap. 28,2", "℘ Ri 2,13", "℘ 5Mo 4,19"] },
      { number: 4, text: "Und er baute Altäre im Haus des HERRN*, von dem der HERR gesagt hatte: In Jerusalem soll mein Name sein für ewig!*", footnotes: ["℘ 2Kö 16,11", "℘ Kap. 6,5.6; 7,16"] },
      { number: 5, text: "Und er baute für das ganze Heer des Himmels Altäre in den beiden Vorhöfen des Hauses des HERRN*.", footnotes: ["℘ Kap. 28,24"] },
      { number: 6, text: "Und er ließ seine Söhne durchs Feuer gehen im Tal Ben-Hinnom*, und er trieb Zauberei und Beschwörung und Magie und ließ sich mit Totengeistern und Wahrsagegeistern* ein*. Er tat viel, was böse war in den Augen des HERRN, um ihn zum Zorn zu reizen*.*", footnotes: ["℘ Kap. 28,3; Jer 7,31", "o. mit Totenbeschwörern und Wahrsagern", "℘ 5Mo 18,10", "o. um ihn zu kränken", "℘ 1Kö 16,33"] },
      { number: 7, text: "Und er stellte das Götterbild des Götzen, das er gemacht hatte*, in das Haus Gottes, von dem Gott zu David und zu seinem Sohn Salomo gesagt hatte: In diesem Haus und in Jerusalem, das ich aus allen Stämmen Israels erwählt habe, will ich meinen Namen für ewig niederlegen!*", footnotes: ["℘ 2Mo 20,4.23; Ri 17,3.4; 1Kö 12,28", "℘ Kap. 6,5.6; 7,16"] },
      { number: 8, text: "Und ich will den Fuß Israels nicht mehr aus dem Land weichen lassen, das ich euren Vätern bestimmt habe, wenn sie nur darauf achten, alles zu tun, was ich ihnen geboten habe, nach dem ganzen Gesetz und den Ordnungen und den Rechtsbestimmungen durch Mose*.", footnotes: ["℘ Kap. 7,19; Jer 7,7"] },
      { number: 9, text: "Aber Manasse verführte Juda und die Bewohner von Jerusalem, mehr Böses zu tun als die Nationen, die der HERR vor den Söhnen Israel ausgetilgt hatte*.", footnotes: ["℘ Kap. 28,19"] },
      { number: 10, text: "Und der HERR redete zu Manasse und zu seinem Volk; aber sie achteten nicht darauf*.", footnotes: ["℘ Spr 1,24.25"] },
      { number: 11, text: "Da ließ der HERR die Heerobersten des Königs von Assur über sie kommen. Und sie nahmen Manasse gefangen* und banden ihn mit ehernen Fesseln* und führten ihn nach Babel*.", footnotes: ["w. sie fingen Manasse mit Haken. — Andere üs.: sie fingen Manasse in Schlupfwinkeln", "w. bronzenen Doppelfesseln", "℘ 5Mo 28,36; 2Kö 20,18; Hi 12,18; Kap. 15,2.4"] },
      { number: 12, text: "Und als er so bedrängt war, flehte er den HERRN, seinen Gott, an und demütigte sich sehr vor dem Gott seiner Väter*", footnotes: ["℘ 2Mo 10,3; Jon 2,2"] },
      { number: 13, text: "und betete zu ihm. Und er ließ sich von ihm erbitten und erhörte sein Flehen* und brachte ihn nach Jerusalem in seine Königsherrschaft zurück*. Da erkannte Manasse, dass der HERR der wahre Gott ist*.", footnotes: ["℘ Kap. 34,27; 1Kö 8,50; 2Kö 13,4; Esr 8,23; Ps 107,13; Lk 11,10", "℘ Kap. 12,7; Hi 36,9-11; Jes 55,7; Jak 4,10", "℘ 1Kö 18,39; Hi 22,22.26; Ps 46,11"] },
      { number: 14, text: "Danach baute er die äußere Mauer für die Stadt Davids, westlich vom Gihon*, im Tal und bis da, wo es zum Fischtor* hineingeht, und umschloss den Ofel*; und er baute sie sehr hoch*. Und er legte Heeroberste in alle befestigten Städte in Juda*.", footnotes: ["℘ Kap. 32,30; 1Kö 1,33", "℘ Neh 3,3", "d. i. eine Stelle in der Stadtmauer\n℘ Kap. 27,3; Jes 32,14", "℘ Kap. 32,5", "℘ Kap. 17,19"] },
      { number: 15, text: "Und er tat die fremden Götter weg und das Götzenbild aus dem Haus des HERRN und alle Altäre, die er auf dem Berg des Hauses des HERRN und in Jerusalem gebaut hatte; und er warf sie vor die Stadt hinaus*.", footnotes: ["℘ Kap. 34,3"] },
      { number: 16, text: "Und er baute den Altar des HERRN wieder auf und opferte auf ihm Heilsopfer* und Dankopfer*. Und er befahl Juda, dass sie dem HERRN, dem Gott Israels, dienen sollten*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ 3Mo 7,11.12", "℘ Kap. 14,3"] },
      { number: 17, text: "Aber das Volk opferte noch auf den Höhen*, jedoch nur dem HERRN, ihrem Gott.", footnotes: ["℘ Kap. 15,17; 20,33"] },
      { number: 18, text: "Und die übrige Geschichte* Manasses und sein Gebet zu seinem Gott und die Worte der Seher, die zu ihm redeten im Namen des HERRN, des Gottes Israels, siehe, das ist geschrieben in der Geschichte* der Könige von Israel*.", footnotes: ["w. der Rest der Begebenheiten", "w. über die Begebenheiten", "℘ 1Kö 14,19"] },
      { number: 19, text: "Sein Gebet aber, und wie Gott sich von ihm erbitten ließ*, und all seine Sünde und seine Untreue und die Orte, an denen er Höhen gebaut und die Ascherim und die Götterbilder aufgestellt hatte, bevor er sich demütigte, siehe, das ist geschrieben in der Geschichte* der Seher*.", footnotes: ["w. und das Sich-von-ihm-Erbittenlassen", "w. über die Begebenheiten", "so mit einer hebr. Handschr. und LXX; Mas. T.: meiner Seher, o. des Hosai"] },
      { number: 20, text: "Und Manasse legte sich zu seinen Vätern, und man begrub ihn in seinem Haus*. Und sein Sohn Amon wurde König an seiner Stelle*.", footnotes: ["℘ Kap. 21,20", "℘ V. 21"] },
      { number: 21, text: "*Zweiundzwanzig Jahre war Amon alt, als er König wurde, und er regierte zwei Jahre in Jerusalem*.", heading: "Amon von Juda", footnotes: ["℘ 2Kö 21,19-26", "℘ V. 20"] },
      { number: 22, text: "Und er tat, was böse war in den Augen des HERRN, wie sein Vater Manasse getan hatte. Und Amon opferte allen Götterbildern, die sein Vater Manasse gemacht hatte, und diente ihnen." },
      { number: 23, text: "Und er demütigte sich nicht vor dem HERRN, wie sein Vater Manasse sich gedemütigt hatte*; sondern er, Amon, vermehrte die Schuld*.", footnotes: ["℘ Dan 5,22", "℘ Jer 7,26"] },
      { number: 24, text: "Und seine Knechte verschworen sich gegen ihn und töteten ihn in seinem Haus*.", footnotes: ["℘ Kap. 22,9"] },
      { number: 25, text: "Das Volk des Landes aber erschlug alle, die sich gegen den König Amon verschworen hatten*. Und das Volk des Landes machte seinen Sohn Josia zum König an seiner Stelle*.", footnotes: ["℘ Kap. 25,3; 1Mo 9,5.6", "℘ Kap. 34,1"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "*Acht Jahre war Josia alt, als er König wurde, und er regierte 31 Jahre in Jerusalem*.", heading: "Josia von Juda — Abschaffung des Götzendienstes — Fund des Gesetzbuches — Bundeserneuerung", footnotes: ["℘ 2Kö 22; 23,1-20", "℘ Kap. 33,25; Jer 1,2"] },
      { number: 2, text: "Und er tat, was recht war in den Augen des HERRN. Und er ging auf den Wegen seines Vaters David* und wich nicht zur Rechten noch zur Linken ab.", footnotes: ["℘ Kap. 17,3.4; 29,2"] },
      { number: 3, text: "Und im achten Jahr seiner Regierung, als er noch ein Junge war*, fing er an, den Gott seines Vaters David zu suchen*. Und im zwölften Jahr fing er an, Juda und Jerusalem von den Höhen und den Ascherim und den geschnitzten und den gegossenen Bildern zu reinigen*.", footnotes: ["℘ Ps 71,5; Spr 20,11", "℘ Kap. 14,6; 2Kö 20,5", "℘ Kap. 33,15"] },
      { number: 4, text: "Und man riss die Altäre der Baalim vor ihm nieder; und die Räucheraltäre, die sich oben auf ihnen befanden, hieb er um. Und die Ascherim und die geschnitzten und die gegossenen Bilder zerschlug und zermalmte er und streute sie auf die Gräber derer, die ihnen geopfert hatten*.", footnotes: ["℘ Kap. 30,14; 3Mo 26,30; 2Kö 23,4.6"] },
      { number: 5, text: "Und die Gebeine der Priester verbrannte er auf ihren Altären*. So reinigte er Juda und Jerusalem.", footnotes: ["℘ V. 33; 1Kö 13,2"] },
      { number: 6, text: "Auch in den Städten von Manasse und Ephraim und Simeon und bis nach Naftali hin*, in ihren Trümmern ringsum,", footnotes: ["℘ Kap. 31,1"] },
      { number: 7, text: "riss er die Altäre nieder. Und die Ascherim und die Götzenbilder schlug er in Stücke und zermalmte sie*; und alle Räucheraltäre hieb er um im ganzen Land Israel. Dann kehrte er nach Jerusalem zurück*.", footnotes: ["o. um sie zu zermalmen\n℘ Kap. 14,2; 5Mo 9,21; 2Kö 10,26.27", "℘ 2Kö 23,15-19"] },
      { number: 8, text: "Und im achtzehnten Jahr seiner Regierung, während er das Land und den Tempel* reinigte, sandte er Schafan, den Sohn Azaljas, und den Stadtobersten Maaseja und den Berater* Joach, den Sohn des Joahas, um das Haus des HERRN, seines Gottes, auszubessern*.", footnotes: ["w. das Haus", "w. den Erinnerer, o. den Bekanntmachenden", "℘ Kap. 24,5"] },
      { number: 9, text: "Und sie kamen zu dem Hohenpriester Hilkija und gaben ihm das Geld, das in das Haus Gottes gebracht worden war, das die Leviten, die an der Schwelle wachten, eingesammelt hatten von der Hand Manasses und Ephraims und vom ganzen Rest Israels und von ganz Juda und Benjamin und den Bewohnern von Jerusalem." },
      { number: 10, text: "Sie gaben es in die Hand der Werkführer, die am Haus des HERRN eingesetzt waren. Und die gaben es den Werkmeistern, die im Haus des HERRN daran arbeiteten, das Haus instand zu setzen und auszubessern." },
      { number: 11, text: "Sie gaben es den Handwerkern und den Bauleuten zum Ankauf von behauenen Steinen* und von Holz für die Bindebalken und um die Häuser, die die Könige von Juda hatten verfallen lassen, mit neuen Balken zu versehen.", footnotes: ["o. Bruchsteinen"] },
      { number: 12, text: "Und die Männer arbeiteten gewissenhaft* an dem Werk. Und über sie waren die Leviten Jahat und Obadja, von den Söhnen Meraris, gesetzt, und Secharja und Meschullam von den Söhnen der Kehatiter, um die Aufsicht zu führen*. Und die Leviten, alle, die sich auf die Musikinstrumente verstanden*,", footnotes: ["w. in Treue", "℘ Esr 3,9", "℘ 1Chr 25,7"] },
      { number: 13, text: "waren sowohl über die Lastträger gesetzt als auch Aufseher über alle Werkführer in jedem Dienst. Und andere von den Leviten waren Schreiber und Verwalter und Torhüter*.", footnotes: ["℘ 1Chr 23,4.5"] },
      { number: 14, text: "Und als sie das Geld herausnahmen, das in das Haus des HERRN gebracht worden war, fand der Priester Hilkija das Buch des Gesetzes des HERRN, das durch Mose gegeben war." },
      { number: 15, text: "Da hob Hilkija an und sagte zu dem Schreiber Schafan: Ich habe das Buch des Gesetzes im Haus des HERRN gefunden. Und Hilkija gab das Buch dem Schafan." },
      { number: 16, text: "Und Schafan brachte das Buch zum König; und außerdem erstattete er dem König Bericht und sagte: Alles, was der Hand deiner Knechte übergeben worden ist, das tun sie." },
      { number: 17, text: "Sie haben das Geld, das sich im Haus des HERRN fand, ausgeschüttet und es in die Hand derer gegeben, die zur Aufsicht eingesetzt sind, und in die Hand der Werkführer." },
      { number: 18, text: "Und der Schreiber Schafan berichtete dem König weiter: Der Priester Hilkija hat mir ein Buch gegeben. Und Schafan las daraus* dem König vor.", footnotes: ["w. darin"] },
      { number: 19, text: "Und es geschah, als der König die Worte des Gesetzes hörte, da zerriss er seine Kleider*.", footnotes: ["℘ Neh 8,9"] },
      { number: 20, text: "Und der König befahl Hilkija und Ahikam, dem Sohn Schafans, und Abdon, dem Sohn Michas, und dem Schreiber Schafan und Asaja, dem Knecht des Königs, und sagte:" },
      { number: 21, text: "Geht hin, befragt den HERRN für mich und für die Übriggebliebenen* in Israel und in Juda wegen der Worte des Buches, das man gefunden hat! Denn groß ist der Zorn des HERRN, der sich über uns ergossen hat, weil unsere Väter das Wort des HERRN nicht beachtet haben, um nach allem zu tun, was in diesem Buch aufgeschrieben ist.", footnotes: ["℘ Jes 37,4.31.32"] },
      { number: 22, text: "Da gingen Hilkija und die, die der König bestimmt hatte, zu der Prophetin Hulda, der Frau des Schallum, des Sohnes des Tokhat, des Sohnes des Hasra, des Hüters der Kleider. Sie wohnte aber in Jerusalem im zweiten Stadtteil*. Und sie redeten in diesem Sinn mit ihr.", footnotes: ["d. i. die Neustadt von Jerusalem"] },
      { number: 23, text: "Und sie sagte zu ihnen: So spricht der HERR, der Gott Israels: Sagt dem Mann, der euch zu mir gesandt hat:" },
      { number: 24, text: "So spricht der HERR: Siehe, ich will Unheil über diesen Ort bringen und über seine Bewohner: all die Flüche, die in dem Buch geschrieben sind, das man dem König von Juda vorgelesen hat*.", footnotes: ["℘ Kap. 36,17-20; 3Mo 26,14-39; Esr 9,7; Hes 4,17; 33,10"] },
      { number: 25, text: "Weil sie mich verlassen und anderen Göttern Rauchopfer dargebracht haben, um mich zum Zorn zu reizen* mit all den Machwerken ihrer Hände, so wird sich mein Zorn über diesen Ort ergießen, und er wird nicht erlöschen*.", footnotes: ["o. um mich zu kränken\n℘ Esr 5,12", "℘ Kap. 24,18; Jer 4,4; Kla 2,4; Am 5,6"] },
      { number: 26, text: "Zu dem König von Juda aber, der euch gesandt hat, um den HERRN zu befragen, zu ihm sollt ihr so sagen: So spricht der HERR, der Gott Israels: Was die Worte betrifft, die du gehört hast, —" },
      { number: 27, text: "weil dein Herz weich geworden ist und du dich vor Gott gedemütigt hast, als du seine Worte über diesen Ort und über seine Bewohner hörtest, und weil du dich vor mir gedemütigt und deine Kleider zerrissen und vor mir geweint hast, darum habe auch ich es gehört, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN\n℘ Kap. 33,12.13; Ps 6,9.10; Jes 66,2.5"] },
      { number: 28, text: "Siehe, ich werde dich zu deinen Vätern versammeln, und du wirst zu deinen Gräbern versammelt werden in Frieden. Und deine Augen sollen all das Unheil nicht ansehen, das ich über diesen Ort und über seine Bewohner kommen lasse*. Und sie brachten dem König Antwort.", footnotes: ["℘ Kap. 32,26"] },
      { number: 29, text: "Und der König sandte hin und versammelte alle Ältesten von Juda und von Jerusalem." },
      { number: 30, text: "Und der König ging hinauf in das Haus des HERRN, und alle Männer von Juda und die Einwohner von Jerusalem und die Priester und die Leviten und alles Volk, vom Größten bis zum Kleinsten. Und man las vor ihren Ohren alle Worte des Bundesbuches, das im Haus des HERRN gefunden worden war." },
      { number: 31, text: "Und der König stand auf seinem erhöhten Standort und schloss den Bund vor dem HERRN*, dem HERRN nachzufolgen und seine Gebote und seine Zeugnisse* und seine Ordnungen zu bewahren mit ganzem Herzen und mit ganzer Seele*, um die Worte des Bundes zu tun, die in diesem Buch aufgeschrieben sind*.", footnotes: ["℘ Kap. 15,12; Esr 10,3", "o. Mahnungen", "w. mit seinem ganzen Herzen und mit seiner ganzen Seele\n℘ 5Mo 6,5; Ps 31,24", "℘ 5Mo 13,5; Neh 10,30; Ps 119,106"] },
      { number: 32, text: "Und er ließ alle in den Bund eintreten*, die sich in Jerusalem und in Benjamin befanden. Und die Bewohner von Jerusalem handelten nach dem Bund Gottes, des Gottes ihrer Väter.", footnotes: ["℘ Kap. 15,12; Esr 10,3"] },
      { number: 33, text: "Und Josia entfernte alle Gräuel aus allen Ländern, die den Söhnen Israel gehörten*. Und er hielt alle dazu an, die sich in Israel befanden, dem HERRN, ihrem Gott, zu dienen. Alle seine Tage wichen sie nicht von der Nachfolge des HERRN, des Gottes ihrer Väter, ab.*", footnotes: ["℘ V. 4.5; Jer 4,1", "℘ Jos 24,31"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "*Und Josia feierte dem HERRN Passah* in Jerusalem. Und man schlachtete das Passah am Vierzehnten des ersten Monats.", heading: "Josias Feier des Passah", footnotes: ["℘ 2Kö 23,21-25", "℘ Kap. 30,2.15; 2Mo 12,6"] },
      { number: 2, text: "Und er stellte die Priester an ihre Aufgaben* und ermutigte sie zum Dienst im Haus des HERRN.", footnotes: ["℘ Kap. 23,18; 31,2"] },
      { number: 3, text: "Und er sagte zu den Leviten, die ganz Israel unterwiesen* und dem HERRN geheiligt waren*: Setzt die heilige Lade in das Haus, das Salomo, der Sohn Davids, der König von Israel, gebaut hat*! Ihr braucht sie nicht mehr auf eurer Schulter zu tragen*. Dient jetzt dem HERRN, eurem Gott, und seinem Volk Israel!", footnotes: ["℘ Kap. 17,7-9", "℘ 2Mo 32,29", "℘ Kap. 5,7", "℘ 1Chr 23,26"] },
      { number: 4, text: "Und haltet euch bereit* nach euren Vaterhäusern, in euren Abteilungen, nach der Vorschrift Davids*, des Königs von Israel, und nach der schriftlichen Anordnung seines Sohnes Salomo!", footnotes: ["o. macht euch bereit", "℘ 1Chr 23-26"] },
      { number: 5, text: "Und stellt euch im Heiligtum auf* entsprechend den Gruppen der Vaterhäuser eurer Brüder, der Leute aus dem Volk*, und zwar für jede Gruppe je eine Abteilung eines Vaterhauses der Leviten!", footnotes: ["℘ Ps 134,1; 135,2", "w. Söhne des Volkes"] },
      { number: 6, text: "Und schlachtet das Passah und heiligt euch* und bereitet es für eure Brüder zu, dass ihr tut* nach dem Wort des HERRN durch Mose!", footnotes: ["℘ Kap. 5,11; 29,5; 30,3.15; 2Mo 12,21", "o. damit sie tun"] },
      { number: 7, text: "Und Josia spendete* für die Leute aus dem Volk* an Kleinvieh: Lämmer und junge Ziegenböcke, 30 000 an der Zahl, alles zu den Passahopfern für alle, die sich eingefunden hatten, und 3 000 Rinder. Das stammte aus dem Besitz des Königs*.", footnotes: ["w. Und Josia hob ab als Opfergabe", "w. Söhne des Volkes", "℘ Kap. 30,24; Hes 45,17"] },
      { number: 8, text: "Und seine Obersten spendeten freiwillig* für das Volk, für die Priester und für die Leviten*. Hilkija und Secharja und Jehiël, die Fürsten des Hauses Gottes*, gaben den Priestern zu den Passahopfern 2 600 Stück Kleinvieh und 300 Rinder.", footnotes: ["o. hoben als freiwillige Gabe ab", "℘ 1Chr 29,6; 2Kor 9,7", "℘ Kap. 31,13"] },
      { number: 9, text: "Und Konanja und Schemaja und Netanel, seine Brüder, und Haschabja und Jeïël und Josabad, die Obersten der Leviten, spendeten* für die Leviten zu den Passahopfern 5 000 Stück Kleinvieh und 500 Rinder.", footnotes: ["o. hoben ab als Opfergabe"] },
      { number: 10, text: "So wurde der Dienst geordnet. Und die Priester standen an ihrem Standort und die Leviten in ihren Abteilungen nach dem Befehl des Königs*.", footnotes: ["℘ Esr 6,18"] },
      { number: 11, text: "Und sie schlachteten das Passah. Und die Priester sprengten das Blut, das sie aus ihrer Hand entgegennahmen, während die Leviten den Tieren die Haut abzogen*.", footnotes: ["℘ Kap. 29,34; 30,16"] },
      { number: 12, text: "Und sie legten das zum Brandopfer Bestimmte beiseite, um es den Gruppen der Vaterhäuser der Leute aus dem Volk* zu geben, damit die es dem HERRN darbrächten, wie es im Buch des Mose geschrieben steht; und ebenso machten sie es mit den Rindern*.", footnotes: ["w. Söhne des Volkes", "℘ 3Mo 1,3; 4Mo 28,19"] },
      { number: 13, text: "Und sie brieten das Passah am Feuer nach der Vorschrift*. Und die heiligen Gaben* kochten sie in Töpfen und in Kesseln und in Schüsseln und verteilten sie schnell an alle Leute aus dem Volk*.", footnotes: ["℘ 2Mo 12,8.9", "o. heiligen Dinge", "w. Söhne des Volkes\n℘ Hes 46,20"] },
      { number: 14, text: "Und danach bereiteten sie es für sich und für die Priester zu; denn die Priester, die Söhne Aarons, waren mit der Darbringung der Brandopfer und der Fettstücke bis in die Nacht beschäftigt. Und so bereiteten die Leviten es für sich zu und für die Priester, die Söhne Aarons*.", footnotes: ["℘ Esr 3,10; 6,20"] },
      { number: 15, text: "Und die Sänger, die Söhne Asafs, waren an ihrem Standort nach der Anordnung Davids* und Asafs und Hemans und Jedutuns, des Sehers des Königs*. Und ebenso waren die Torhüter an jedem Tor*. Sie hatten es nicht nötig, sich von ihrem Dienst zu entfernen, weil ihre Brüder, die Leviten, für sie das Passah zubereiteten*.", footnotes: ["℘ Esr 3,10; 6,20", "℘ 1Chr 25,5", "℘ Kap. 8,14", "℘ Röm 12,10"] },
      { number: 16, text: "Und so wurde der ganze Dienst des HERRN an jenem Tag geordnet, um das Passah zu feiern und die Brandopfer auf dem Altar des HERRN darzubringen, nach dem Befehl des Königs Josia." },
      { number: 17, text: "Und die Söhne Israel, die sich einfanden, feierten in jener Zeit das Passah und das Fest der ungesäuerten Brote sieben Tage lang*.", footnotes: ["℘ Kap. 30,21"] },
      { number: 18, text: "Ein Passah wie dieses aber war in Israel nicht gefeiert worden seit den Tagen des Propheten Samuel. Denn alle Könige von Israel hatten kein Passah gefeiert wie das, das Josia feierte und die Priester und die Leviten und ganz Juda und Israel, das sich einfand, und die Bewohner von Jerusalem*.", footnotes: ["℘ Kap. 30,26"] },
      { number: 19, text: "Im achtzehnten Jahr der Regierung* Josias ist dieses Passah gefeiert worden.", footnotes: ["w. Königsherrschaft"] },
      { number: 20, text: "*Nach all diesem, als Josia das Haus wieder hergerichtet hatte*, zog Necho, der König von Ägypten, herauf, um bei Karkemisch* am Euphrat zu kämpfen. Und Josia zog aus, ihm entgegen.", heading: "Josias Tod im Krieg gegen Ägypten", footnotes: ["℘ 2Kö 23,26-30", "℘ Kap. 32,1", "℘ Jes 10,9"] },
      { number: 21, text: "Da sandte er Boten zu ihm und ließ ihm sagen: Was habe ich mit dir zu tun*, König von Juda? Nicht gegen dich komme ich heute, sondern gegen das Haus, mit dem ich Krieg führe. Und Gott hat zu mir gesagt, dass ich eilen soll*. Lass ab von Gott, der mit mir ist, damit er dich nicht verderbe! —", footnotes: ["w. Was ist mir und dir", "o. Gott hat gesprochen, um mich in Bestürzung zu versetzen"] },
      { number: 22, text: "Aber Josia wandte sein Gesicht nicht von ihm ab, sondern verkleidete sich, um gegen ihn zu kämpfen*. Und er hörte nicht auf die Worte Nechos, die aus dem Mund Gottes kamen. Und er kam in die Ebene von Megiddo*, um zu kämpfen.", footnotes: ["LXX: sondern war entschlossen, gegen ihn zu kämpfen\n℘ Kap. 18,29; 1Kö 22,30", "℘ Jos 17,11; Offb 16,16"] },
      { number: 23, text: "Und die Bogenschützen schossen auf den König Josia. Da sagte der König zu seinen Knechten: Bringt mich weg, denn ich bin schwer verwundet*!", footnotes: ["℘ Kap. 18,33; 1Kö 22,34"] },
      { number: 24, text: "Und seine Knechte schafften ihn aus dem Wagen hinüber und setzten ihn auf den zweiten Wagen, den er hatte, und brachten ihn nach Jerusalem. Und er starb und wurde in den Gräbern seiner Väter begraben. Und ganz Juda und Jerusalem trauerten um Josia*.", footnotes: ["℘ Kap. 32,33; Sach 12,11"] },
      { number: 25, text: "Und Jeremia stimmte ein Klagelied über Josia an*. Und alle Sänger und Sängerinnen haben in ihren Klageliedern von Josia gesungen* bis auf den heutigen Tag. Und man machte sie zu einem festen Brauch* in Israel*. Und siehe, sie sind geschrieben in den Klageliedern.", footnotes: ["℘ 2Sam 1,17", "w. gesprochen", "o. zu einer Ordnung", "℘ Ri 11,39.40"] },
      { number: 26, text: "Und die übrige Geschichte* Josias und seine guten Taten* nach dem, was im Gesetz des HERRN geschrieben steht,", footnotes: ["w. der Rest der Begebenheiten", "o. seine Treuebeweise; o. Gnadenerweise\n℘ Kap. 32,32; Jer 22,15.16"] },
      { number: 27, text: "und seine Geschichte*, die frühere und die spätere*, siehe, sie ist geschrieben in dem Buch der Könige von Israel und Juda*.", footnotes: ["w. seine Begebenheit", "℘ Kap. 12,15", "℘ Kap. 25,26"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "*Und das Volk des Landes nahm Joahas*, den Sohn Josias, und sie machten ihn zum König in Jerusalem anstelle seines Vaters*.", heading: "Joahas und Jojakim von Juda — Erste Wegführung nach Babel", footnotes: ["℘ 2Kö 23,31-37; 24,1-7", "℘ 1Chr 3,15", "℘ Hes 19,3"] },
      { number: 2, text: "23 Jahre war Joahas alt, als er König wurde, und er regierte drei Monate in Jerusalem." },
      { number: 3, text: "Und der König von Ägypten setzte ihn ab in Jerusalem. Und er legte dem Land eine Geldbuße von hundert Talenten Silber und einem Talent Gold auf." },
      { number: 4, text: "Und der König von Ägypten machte seinen Bruder Eljakim zum König über Juda und Jerusalem und änderte seinen Namen in Jojakim*. Seinen Bruder Joahas aber nahm Necho fest und brachte ihn nach Ägypten*.", footnotes: ["℘ Jer 26,1", "℘ Jer 22,11"] },
      { number: 5, text: "25 Jahre war Jojakim alt, als er König wurde, und er regierte elf Jahre in Jerusalem. Und er tat, was böse war in den Augen des HERRN, seines Gottes." },
      { number: 6, text: "Gegen ihn zog Nebukadnezar, der König von Babel, herauf. Und er band ihn mit ehernen Fesseln*, um ihn nach Babel zu bringen*.", footnotes: ["w. mit bronzenen Doppelfesseln", "℘ Jer 22,19; Hes 19,9"] },
      { number: 7, text: "Auch von den Geräten des Hauses des HERRN brachte Nebukadnezar einen Teil nach Babel* und legte sie in seinen Palast* in Babel.", footnotes: ["℘ V. 18; Esr 1,7; Dan 1,2", "o. Tempel"] },
      { number: 8, text: "Und die übrige Geschichte* Jojakims und seine Gräueltaten, die er verübt hat, und was sonst über ihn gefunden wurde*, siehe, das ist geschrieben in dem Buch der Könige von Israel und Juda*. Und Jojachin, sein Sohn, wurde an seiner Stelle König.", footnotes: ["w. der Rest der Begebenheiten", "o. was über ihn gekommen ist", "℘ Kap. 25,26"] },
      { number: 9, text: "*Achtzehn* Jahre war Jojachin alt, als er König wurde, und er regierte drei Monate und zehn Tage in Jerusalem. Und er tat, was böse war in den Augen des HERRN.", heading: "Jojachin und Zedekia von Juda — Zerstörung Jerusalems — Zweite Wegführung nach Babel", footnotes: ["℘ V. 9-10: 2Kö 24,8-17; Jer 22,24-30", "so mit LXX und 2Kö24,8; Mas. T.: acht"] },
      { number: 10, text: "Bei der Wiederkehr des Jahres* sandte der König Nebukadnezar hin und ließ ihn nach Babel bringen samt den kostbaren Geräten des Hauses des HERRN*. Und er machte seinen Bruder* Zedekia zum König über Juda und Jerusalem*.", footnotes: ["d. h. im folgenden Frühjahr; w. zur Zeit der Rückkehr des Jahres", "℘ V. 18; Jer 28,3", "d. h. Verwandten", "℘ 1Chr 3,15.16; Jer 37,1; Hes 17,6"] },
      { number: 11, text: "*Einundzwanzig Jahre war Zedekia alt, als er König wurde*, und er regierte elf Jahre in Jerusalem.", footnotes: ["℘ V. 11-21: 2Kö 24,18-20; 25,1-21; Jer 52,1-27", "℘ Jer 29,16"] },
      { number: 12, text: "Und er tat, was böse war in den Augen des HERRN, seines Gottes. Er demütigte sich nicht vor dem Propheten Jeremia, der nach dem Befehl* des HERRN zu ihm sprach*.", footnotes: ["w. aus dem Mund", "℘ Jer 37,2; 38,21"] },
      { number: 13, text: "Und auch empörte er sich* gegen den König Nebukadnezar, der ihn bei Gott hatte schwören lassen*. Und er verhärtete seinen Nacken* und verstockte sein Herz*, so dass er nicht umkehrte zu dem HERRN, dem Gott Israels.", footnotes: ["℘ Esr 4,12", "℘ 4Mo 30,3; Ps 15,4", "℘ Neh 9,16.17", "℘ 2Mo 7,13"] },
      { number: 14, text: "Auch alle Obersten der Priester und das Volk* häuften Untreue auf Untreue*, entsprechend allen Gräueln der Nationen*, und machten das Haus des HERRN unrein, das er in Jerusalem geheiligt hatte*.", footnotes: ["o. und des Volkes", "℘ Jer 5,5; Hes 22,26-28", "℘ Kap. 28,3; 5Mo 18,9; Hes 11,12", "℘ 3Mo 19,30; Jer 32,34.35"] },
      { number: 15, text: "Und der HERR, der Gott ihrer Väter, sandte zu ihnen durch seine Boten, früh sich aufmachend und sendend*; denn er hatte Mitleid mit seinem Volk* und seiner Wohnung.", footnotes: ["℘ Kap. 24,19; 2Kö 17,13; Jer 7,25", "℘ Hos 11,8"] },
      { number: 16, text: "Aber sie verhöhnten die Boten Gottes* und verachteten seine Worte* und verspotteten seine Propheten*, bis der Zorn des HERRN gegen sein Volk so stieg, dass es keine Heilung mehr gab*.", footnotes: ["℘ Kap. 30,10", "℘ Kap. 24,19; Ri 2,17; Spr 1,24-31; Dan 9,6", "℘ 2Kö 2,23; Jes 57,4; Apg 7,52", "℘ Spr 29,1; 1Thes 2,16"] },
      { number: 17, text: "*Und er ließ den König der Chaldäer gegen sie heraufkommen und brachte ihre jungen Männer mit dem Schwert um* im Haus ihres Heiligtums*. Er hatte kein Mitleid mit Jüngling oder Jungfrau, mit Altem oder Greis. Alle gab er in seine Hand*.", footnotes: ["℘ V. 17-21: Jer 39,1-10", "o. und der brachte . . . um", "℘ Jes 43,28", "℘ 5Mo 28,50; Esr 9,7; Jer 21,7; Kla 2,20-22; Hes 16,40"] },
      { number: 18, text: "Und alle Geräte des Hauses Gottes, die großen und die kleinen, und die Schätze des Hauses des HERRN* und die Schätze des Königs und seiner Obersten, alles brachte er nach Babel*.", footnotes: ["℘ V. 7.10", "℘ 2Kö 20,17; Jer 27,19-22; Kla 1,10"] },
      { number: 19, text: "Und sie verbrannten das Haus Gottes* und rissen die Mauer von Jerusalem nieder. Und all seine* Paläste verbrannten sie mit Feuer*, und all seine* kostbaren Geräte zerstörten sie*.", footnotes: ["℘ Kap. 7,20; Ps 74,7; Jes 64,10", "d. h. Jerusalems", "℘ Neh 1,3; Jer 32,29", "d. h. Jerusalems", "℘ Kap. 34,24; Ps 79,1; Sach 1,6"] },
      { number: 20, text: "Und was vom Schwert übrig geblieben war, führte er gefangen nach Babel*. Und sie mussten ihm und seinen Söhnen als Sklaven dienen*, bis das Königreich der Perser zur Herrschaft kam,", footnotes: ["℘ Esr 2,1; 5,12; Jes 47,6", "℘ Hes 19,13"] },
      { number: 21, text: "damit erfüllt würde das Wort des HERRN durch den Mund Jeremias, bis das Land seine Sabbate ersetzt bekam. All die Tage seiner Verwüstung hatte es Ruhe, bis siebzig Jahre voll waren*.", footnotes: ["℘ 3Mo 26,34.43; Jer 25,9-12; Dan 9,2; Sach 7,14"] },
      { number: 22, text: "*Und im ersten Jahr des Kyrus*, des Königs von Persien, damit das Wort des HERRN durch den Mund Jeremias erfüllt würde, erweckte der HERR den Geist des Kyrus, des Königs von Persien. Und er ließ einen Aufruf ergehen durch sein ganzes Königreich und auch schriftlich bekannt machen:", heading: "Ende der Babylonischen Gefangenschaft", footnotes: ["℘ Esr 1,1-3", "℘ Jes 44,28"] },
      { number: 23, text: "So spricht Kyrus, der König von Persien: Alle Königreiche der Erde hat der HERR, der Gott des Himmels, mir gegeben*. Und er hat mich beauftragt, ihm ein Haus zu bauen in Jerusalem, das in Juda ist*. Wer immer unter euch aus seinem Volk ist*, mit dem sei der HERR, sein Gott! Er ziehe hinauf!*", footnotes: ["℘ Jer 27,6; Dan 5,28", "℘ Jes 45,13", "℘ Jes 44,5", "℘ Mi 4,10"] },
    ]},
  ]
};
